window.__D("text/maamarei-admur-hazaken/c009",{"p":[[2100990310,"לך משתחווי' כו' שהוא בחי' ביטול הי\"ש לאי\"ן זהו בא מבחי' הטו\"ב שבו, וידוע שאינו בטל בכל פעם כי לא לעולם יש בו הביטול בהשתחוויי' אלא לפרקי' וכמ\"ש והי'<sup data-n=\"4961\">12</sup> מדי חדש ושבת יבא כל בשר להשתחוו' כו' או בכל בקר כמ\"ש חדשים<sup data-n=\"4962\">13</sup> לבקרים כו' אבל כל היום אין בו בחי' הביטול אלא הוא יש ודבר נפרד לגמרי בלתי ביטול כי הרי הביטול הנמצא בו הוא מצד הבחירה והרצון כו', הנה זה הפירוד בא מבחי' הר\"ע שבנוגה שנק' יש גמור וכללו' ענינם נק' קליפת נוג\"ה וכמו שידוע דנוג\"ה מעורב מטו\"ר וכמאמר הידוע דבהאי<sup data-n=\"4963\">14</sup> נוג\"ה מפתה לאיתת\"א ונטיל נהורהא כו' והיינו מצד בחי' הטו\"ב שבנוג\"ה שנכלל בקדוש' להיו' כי יש בו בטוב בחי' הביטול.\n<b>והנה</b> יש במזיגה זאת דטו\"ר שבנוג\"ה ריבוי המדרגו' מאד כי הנה הטוב שבנוג\"ה שהוא בחי' הביטול והר\"ע שבנוג\"ה שהוא בחי' הפירוד כנ\"ל כאשר מתערבי' יחד יש כמה אופני' שונים באופן התערובו' מטו\"ר אם כך או כך ומזה נמצא סיבת ריבוי המדרגו' בנוג\"ה דבי\"ע יש שהן בבחי' הביטול יותר ויש שאינם בבחי' הביטול כ\"כ, ואמנם הנה דרך כלל ג' מדרגות הן, הא' אשר הביטול בהם תמידי בלתי שינוי והפסק כלל וכמו מיכאל וגבריאל ומט\"ט וכיוצא ואע\"פ שלפרקי' רחוקי' יחטאו עד שיקבלו עונש גם הם וכמו שאמרו דאפקו\"ה<sup data-n=\"4964\">15</sup> למט\"ט והלקוהו כו' אבל אין זה שכיח כלל והגם שהן בעלי בחירה מ\"מ הביטול שלהן תמידי, אבל בחי' הר\"ע שבנוג\"ה כשגובר על הטוב הוא היפך זה ממש והן הע' שרים של מטה שהן בבחי' פירוד ממש ברוב הפעמי' וכמ\"ש שר של מצרים לי<sup data-n=\"4965\">16</sup> יאור\"י כו' וכיוצא בזה וזהו מדרג' השנית דרך כלל אבל בחי' הממוצע אשר בין שני הפכים הללו הוא אשר מעורב מטו\"ר במזיגה שלפעמי' בטל ולפעמי' אינו בטל זהו בא בריבוי אופני' מאד כנ\"ל, ומה שאמר דבהאי נוג\"ה מפתי לאיתתא היינו מצד בחי' הטו\"ב שבנוג\"ה כנ\"ל וד\"ל.\n<b>והנה</b> כל זה בנבראי' שנבראו ע\"י הצמצום דשם אלקי' כנ\"ל והן עשרה מאמרו' בכלל אבל שרש התהוות של הנשמות שהן באין מיחוד דזו\"נ כידוע הרי לא יתכן בהם לומר גם ענין בחי' הביטול כמו בענין הטוב שבנוגה כנ\"ל והיינו שא' בזוהר ונפש<sup data-n=\"4966\">17</sup> כי תחטא תווהא הוא כו'. וביאור הדברים הנה עד\"מ באיברי האדם לגבי חיות נפשו היתכן לומר שהרגל בטל הוא לגבי חיו' הנפש שבמוח המנהיג כל האיברי' אחר שהרגל נחשב גם הוא מבחי' עצמו' האדם ועצם א' הוא עם חיו' הנפש וכל שהוא בחי' עצם א' לא שייך לומר בחי' ביטול, שאין לשון ביטו\"ל נופל אלא בדבר הנבדל ונפרד חוץ מעצמו' האדם כידוע, וכמ\"כ בנשמו' שנמשכו ממוחי' דזו\"נ",[["4961","12","<b>והי' מדי חדש ושבת יבא כל בשר להשתחוו'</b>: ישעי' סו, כג. — והי' מדי חודש בחדשו ומדי שבת בשבתו יבא כל בשר."],["4962","13","<b>חדשים לבקרים</b>: איכה ג, כג."],["4963","14","<b>דבהאי נוג\"ה מפתה לאיתתא</b>: זהר ויקהל רג, ב."],["4964","15","<b>דאפקו\"ה למט\"ט והלקוהו</b>: ראה חגיגה טו, א."],["4965","16","<b>לי יאורי</b>: יחזקאל כט, ג."],["4966","17","<b>ונפש כי תחטא תווהא הוא</b>: ויקרא ה, א. ראה זהר ויקרא יג, ב. טז, א. מאמרי אדה\"א הנחות תקע\"ז ע' שיב. וש\"נ."]]],[2100990311,"ע\"ד הולדת ולד מאב ואם כידוע א\"כ הם נחשבי' ג\"כ מבחי' עצמיו' אלקו' והאיך יתכן לומר בהם בחי' הביטול שהם בטילי' לאלקות אחר שאינם בחי' נפרד כלל והגם שירדו הנשמו' למטה עד שיוכל להיו' שרש התהוו' הנשמה מי\"ס דעשי' בלבד ונק' עקבו' משיחא<sup data-n=\"4967\">18</sup> נשמו' שהן מבחי' עקביים כידוע, מ\"מ הרי ידוע דע\"ס דאצי' שמתלבשי' באורו' וכלים הרי המה באין ונמשכי' גם למטה בבי\"ע והן הן י\"ס דבריא' וי\"ס דיצי' וי\"ס דעשי' אלא ששם באין בבחי' מיעוט האור מפני בחי' המסכים שמבדילי' כו' עד שנתמעט האור מיעוט אחר מיעוט בי\"ס דעשי', אך אעפ\"כ אותו מיעוט האור גם שבספי' מל' דמל' דעשי' נחשב מבחי' עצם א' עם ע\"ס דאצי' ועד\"מ הרגל שמתאחד עם המוחי' שבראש וכנ\"ל, ולא יתכן לומר גם בנשמ' שנמשכה ממל' דמל' דעשי' ענין נפרד לגמרי עד שצריך לומר בה בחי' הביטו\"ל כו'.\n<b>ויובן</b><sup data-n=\"4968\">19</sup> זה בתוספת ביאור במשל השפעת שכל מרב לתלמיד דהנה הגם שהרב הוא חכם גדול ומשיג את השכל בעמקות גדולה מ\"מ יוכל להסביר השכל גם לתינוק קטן במשלים וחידו' והגם שאין זה ערך כלל להבנת עצמותו מ\"מ סברת השכל אחד הוא בין בעמקו' השגתו בין בצמצום הבנת התינוק שהרי זה נשפע מאור עצמות תבונתו ואין דיבורי' הללו שמדבר עם התינוק נבדל כלל מעצמות תבונתו בדבר השכל ההוא כו', ולפ\"ז מובן הנמשל שגם בחי' י\"ס דעשי' הרחוק יותר בהשתלשלות נתאחד עם י\"ס דאצי' עד שלא שייך בחי' הביטו'ל כלל וד\"ל.\n<b>וע\"כ</b> אמרו בזוהר דנפש כי תחטא תווהא הוא כו', אך מה שנמצא החטא בנשמו' היינו מצד בחי' הלבושי' שלהם בגוף אבל מצד שרשם גם נשמת פחו' הערך בישראל הוא חלק אלוה ממש וכמ\"ש כי<sup data-n=\"4969\">20</sup> חלק הוי' עמו, וכמו ע\"ד דוגמא מי שיוכל להשכיל בשכל וסברא בחכמה שבתורה שבע\"פ הגם ששרשו מבחי' חכמה שבמל' דעשי' בלבד מ\"מ מתאחד' נשמתו בחכמה דאצי' כי ישראל<sup data-n=\"4970\">21</sup> עלה במחשבה וכמשל ביטול הרגל לגבי הראש וכך נא' בני<sup data-n=\"4971\">22</sup> בכורי ישראל וברא<sup data-n=\"4972\">23</sup> כרעא דאבוה כו' וד\"ל.\n<b>ואחר</b> כל זה הנה מובן פי' מאמר התיקונים הנ\"ל ווי לי לס\"מ כד קדב\"ה תבע מיני' כו', דהנה יש ג' מדרגו' הא' מבחי' הטו\"ב שבנוג\"ה לגמרי כנ\"ל שהביטול תמידי והם נכללי' ממש בקדוש' וכמאמר דבהאי נוג\"ה מפתי לאיתתא כו' והיינו מ\"ש לעתיד ועמדו<sup data-n=\"4973\">24</sup> זרים ורעו צאנכם כו' וכן והיו<sup data-n=\"4974\">25</sup> מלכים אומנייך כו'",[["4967","18","<b>עקבו' משיחא נשמו'. . מבחי' עקביים כידוע</b>: ראה ג\"כ שערי אורה יט, א. קח, ב. דרך מצותיך קנב, א. קעו, א. ובכ\"מ."],["4968","19","<b>ויובן זה בתוספת ביאור</b>: באוה\"ת מסומן כאן סעיף ב)."],["4969","20","<b>כי חלק הוי' עמו</b>: האזינו לב, ט."],["4970","21","<b>ישראל עלה במחשבה</b>: ראה ב\"ר פ\"א ד."],["4971","22","<b>בני בכורי ישראל</b>: שמות ד, כב."],["4972","23","<b>וברא כרעא דאבוה</b>: יונת אלם רפ\"ב. ע\"ח שכ\"ג פ\"א בשם: רז\"ל. של\"ה קנז, א. וראה פרש\"י ד\"ה כבעל — כתובות צב, א. תוד\"ה מקמי — יבמות י, א. וראה ספר החקירה להצ\"צ ע' מו: וכמרגלא בפומי' דאינשי."],["4973","24","<b>ועמדו זרים ורעו צאנכם</b>: ישעי' סא, ה."],["4974","25","<b>והיו מלכים אומניך כו'</b>: ישיע' מט, כג."]]],[2100990312,"שיהיו בתכלית הביטול לנשמו' ישראל כו', והב' הממוצע שאינו נפרד כלל ולפעמי' בטל כנ\"ל, והג' שנפרד הוא ברוב הפעמי'. וכולל במאמר זה ג' אלה דמ\"ש דהוו אוקיר לישראל היינו שהיו בטילי' בתכלית ונכללי' היו בקדושה ממש, ובמדרג' הב' הממוצע הנ\"ל ג\"כ לא היו ס\"מ וממנן דילי' שהרי הממוצעי' אין בהם בחי' הרע שבנוג\"ה רק לפרקי' ועכ\"פ לא היו פועלי' רע, וס\"מ וממנן דילי' דעאקו לישראל ופעלו רע הרי הם מבחי' ר\"ע שבנוג\"ה לגמרי וע\"כ עליהם דוקא יאמר לעתיד יר\"א בוש\"ת כו' וכמו שאמר בסיום אותו המאמר ותוכן הכונה הוא שהי' בהם בחירה ורצון בבחי' הטו\"ב שבנוג\"ה לאוקי\"ר לישראל והם עשו ההיפוך ע\"כ בהכרח שאין להם תקו\"ה לעתיד אלא יבוערו לגמרי וכמ\"ש בתקונא הח' על הס\"מ ובת זוגי' דאיתמר עלייהו כי שמים כעשן נמלחו כו' שיתבטלו ויאבדו לגמרי וכמ\"ש ואת<sup data-n=\"4975\">26</sup> רוח הטומאה אעביר כו' מטעם הנ\"ל וד\"ל.\n<b>וזהו</b><sup data-n=\"4976\">27</sup> שרש כללו' ענין הקללות שבתוכחה דהנה הקללות האלה קאי הכל על בחי' הרע שבנוג\"ה מג' קליפו' הטמאות לגמרי שכללותם הן בחי' ס\"מ ונוקבי' שפעלו רע לישראל ולא אוקירו להו להתבטל ולהכלל בע\"ס דקדוש' מצד בחי' הטו\"ב שבהם כנ\"ל שבהכרח הוא להיות להם אבדון וכליון לגמרי כי אבדו תקוותם ועליהם הוא אומר כל אלה הקללות דהיינו שמקלל אותם להאבידם ולכלותם לגמרי עד השמדם כו', ואומר שלעתיד יקויים בהם כל הקללות האלה ויעשו בו כל המעשים האלה כמו ידבק ה' בהם הדבר עד כלותו וכו' ועד סוף הפרשה ההיא כל הקללות שנאמרו בה הכל קאי על בחי' הר\"ע שבנוג\"ה וע\"ד המאמר של התקונים הנ\"ל. והמופת לזה דקאי על הר\"ע דנוג\"ה הוא מן המבואר בפירוש בפ' נצבים ובאו<sup data-n=\"4977\">28</sup> כל הקללו' האלה על אויב\"ך ועל שונא\"ך אשר רדפו\"ך דוקא, והיינו אותם שפעלו רע לישראל כי הם מבחי' הפירוד לגמרי ואין בהם בחי' טוב כלל כנ\"ל שהוא מדרג' השלישי' כו' וד\"ל.\n<b>והנה</b><sup data-n=\"4978\">29</sup> קודם שהוא מקלל אותם בפרט הוא אומר תחלה שרש הכונה בקללות האלה והוא מ\"ש והי' אם לא תשמע בקול ה' כו' דהיינו לאוקי\"ר לישראל אלא אדרבה פעלת רע להם ובאו עליך כל הקללו' האלה כו' עד השמד\"ך כו' ידבק ה' כו' עד כלותו אותך מעל האדמה אשר אתה בא שמה לרשתה, הנה מ\"ש עד כלותו מעל האדמה כו' זהו תוכן הכוונה בכל הקללות האלה, וכן הוא מסיים בסוף הפרשה ונסחתם מעל האדמה אשר אתה בא שמה לרשתה כו'. והענין הוא כי הנה שרש יניקות החיצוני' הוא נמשך ובא מבחי' פסולת ומותרות ההשפעה שנשפע מבחי' מל' דאצי' וכידוע בפי' ועשתה<sup data-n=\"4979\">30</sup> את צפרני\"ה שהחיצוני' יונקים ממותרי",[["4975","26","<b>ואת רוח הטומאה אעביר כו'</b>: זכרי' יג, ב."],["4976","27","<b>וזהו שרש כללו' ענין</b>: באוה\"ת מסומן כאן סעיף ג)."],["4977","28","<b>ובאו כל הקללו' האלה על אויבך</b>: נצבים ל, ז — ונתן ה' אלקיך את כל האלות האלה על איביך ועל שונאך אשר רדפוך."],["4978","29","<b>והנה קודם</b>: באוה\"ת מסומן כאן סעיף ד)."],["4979","30","<b>ועשתה את צפרניה שהחיצוני' יונקים</b>: תצא כא, יב. וראה מאמרי אדה\"א דברים ח\"ב ע' תקלז. וראה סידור שער נט\"י ק, ג ואילך. סה\"מ תקס\"ב ח\"א ע' קד. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' נו. דרך חיים ע' 128. פירוש המלות מב, ב. מאמרי אדה\"ז הקצרים ע' תקי. וש\"נ."]]],[2100990313,"השפע שמגיע מן הצפרני' והשערו' כו', ועיקר כלל יניקתם הוא בא מבחי' ה' דמים טמאים שבאשה העליונה הנק' אשה<sup data-n=\"4980\">31</sup> יראת ה' כידוע.\n<b>וענין</b> ה' דמים טמאי' יובן מדוגמת ה' דמים טמאי' באשה הגשמית למטה דהנה אנו רואים סיבת התהוות דמים הטמאים באשה הוא מבחי' ריבוי הדמים כאשר מתרבה בה הדמים שאז ימצא בריבוי הדם פסולת הדמים הרבה והפסולת נדחה לחוץ וזהו ענין יציא' דם טמא שהוא הפסולת של הדם הנדחה לחוץ מפני שנתרבה דם הרבה וכמו ענין ותתחלחל<sup data-n=\"4981\">32</sup> המלכה שפירסה נדה שמפני הפחד נתבלבלו הדמים ונתערב הפסולת ויצא ונדחה לחוץ, וכן כל ענין פירסה נדה הוא רק ענין יציאת הפסולת מצד ריבוי הדמים כידוע, ויש ה' דמים טהורים כי באותו פסולת היוצא יש שאינו פסולת הדם המזוהם אלא הוא מן הנקי והטוב שיצא גם הוא לחוץ ונק' דם טהור והיינו ענין ההבדלה בין דם לדם, וכללו' הענין הוא כי הדם<sup data-n=\"4982\">33</sup> הוא הנפש שבו שוכן עיקר חיו' הנפש ובמובחר וטוב שבו סובב והולך רוח החיים בכל האיברי' ונק' בחי' גבורו' שהוא עיקר המחי' אך בפסולת הדם החיו' שבו קשה ורע מאד ויכול לקלקל כל הגוף וע\"כ נדחה ויוצא לחוץ וזה נק' בחי' גבורו' קשות כידוע.\n<b>והדוגמא</b> מכל זה יובן למשכיל למעלה דשרש יניקו' החיצוני' שנמשך מבחי' הדמים טמאי' שבאשה העליונה היינו מבחי' הגבורו' הקשו' שהוא ענין ובחי' פסולת השפע הנדחה לחוץ מבחי' מל' דאצי' והיינו מסיבת ריבוי הדמים עד שנמצא פסולת הרבה והוא ענין רוב התעוררו' גבורו' עליוני' ע\"י שעוברי' על שס\"ה ל\"ת שהן מבחי' הגבורו' של הדם הפסולת דאימא כמ\"ש במ\"א בענין שמי<sup data-n=\"4983\">34</sup> עם י\"ה שהן שס\"ה ל\"ת מפני שהוא בבחי' בינה שמלובשת בשס\"ה גידין וע\"ז נא' כי הדם הוא הנפש כו' וע\"י שנתעוררו גבורות הרבה ע\"י שס\"ה ל\"ת נמשך פסולת הדם הרבה ובהכרח שיהי' נדחה לחוץ והן בחי' ה' דמים הטמאי' שמקבלי' החיצוני' תוספ' יניק' מהם אבל ה' דמים הטהורי' נשארו בבחי' הקדושה כי בהם עיקר אור החיות כמבואר מתוך משל הנ\"ל בה' דמים טמאי' וה' דמי' טהורי' אשר באשה למטה וד\"ל.\n<b>והנה</b> כל זה בבחי' מל' דוקא שנק' אשה כידוע אבל מבחי' ז\"א אין לחיצונים יניקה כלל וכלל כי אין בזכר ענין פירסה נדה בה' דמים טמאי' כו', והטעם הוא כי הזכר רובו בחי' חסדי' וכמ\"ש כי<sup data-n=\"4984\">35</sup> זכ\"ר חסד\"ו כו' אבל הנוק' מלאה גבורו' ודינין כי",[["4980","31","<b>אשה יראת ה'</b>: משלי לא, א."],["4981","32","<b>ותתחלחל המלכה שפירסה נדה</b>: אסתר ד, ד. מגילה טו, א. סוטה כ, ב. נדה כא, א."],["4982","33","<b>הדם הוא הנפש</b>: פ' ראה יב, כג."],["4983","34","<b>שמי עם י\"ה שהן שס\"ה ל\"ת</b>: בלקו\"ת פקודי ג, ב מציין: בת\"ז בהקדמה ד' ד' סע\"ב וד' ה' ע\"א. (וראה בהנסמן בהמ\"מ לשם)."],["4984","35","<b>כי זכר חסדו</b>: תהלים צח, ג."]]],[2100990314,"עיקר בנינה הוא מבחי' הגבורו' כידוע וע\"כ מסתעפי' ממנה בחי' הגבורו' הקשות כמו ה' דמי\"ם טמאים הנ\"ל משא\"כ בזכ\"ר שאין בו בחי' גבורו\"ת בגילוי כ\"כ, והגם שבהכרח שימצא בו ג\"כ מבחי' הגבורו' שהרי נק' ז\"א בשם מל\"ך כידוע וכתיב מלך<sup data-n=\"4985\">36</sup> במשפט יעמיד ארץ כו' אבל מ\"מ אין הדינים שלו בהתגלו' כ\"כ והטעם הוא כי הנה כתיב באור<sup data-n=\"4986\">37</sup> פנ\"י מלך חיים דאנפהא<sup data-n=\"4987\">38</sup> דמלכא נהירין בתמידות והוא לעוצם רוממותו כי כל הגבוה גבוה יותר יאיר באור טוב וחסד לכל כו' וע\"כ אנפהא דמלכא נהירין בבחי' החסדי' לכל אך בחי' הדין שהוא מצד האימה של המלך הוא מכוסה ונעלם בתוך הארת הפנים הללו כנרא' לכל עין רואה פני המלך בפנים צהובות דאע\"פ שמדבר בקירוב גדול מ\"מ האימה שלו על העומד לפניו מתפשטת אך שהיא בהעלם והסתר וא\"כ הדינים שלו מכוסי' ונעלמי' לפי שהארת הפני' הוא בגילוי עליהם להעלימם ולהסתירם כו', ואחר שהדינים שלו מכוסי' ונעלמי' בתוך הארת הפנים איך יוכלו החיצוני' לקבל מפסולת הדיני' הללו אחר שלא יש מציאת גבורו' קשות כלל מהדינים שלו כמו הכעס והרוגז כי הרי המה מכוסי' ונעלמי' באור פני מלך כנ\"ל ולא מסתעף מהדיני' שלו המכוסי' שום ענין גבורו' קשו', וע\"כ אין מקום כלל וכלל לחיצונים להיו' להם שרש אחיזה ויניקה בגבורו' דז\"א אלא רק בבחי' גבורו' דמל' להיותם באין ונמשכין למטה בבחי' הגילוי כענין פירסה נדה כנ\"ל, וע\"כ נק' הדיני\"ם של בחי' המל' בשם דינא דמלכותא ממש לענוש בעונש רע ממש אבל בז\"א נא' מפי<sup data-n=\"4988\">39</sup> עליון לא תצא הרעות כו' כי אין<sup data-n=\"4989\">40</sup> רע יורד מלמעלה מטעם הנ\"ל, אבל בדינא דמלכותא שמלאה דינין נמשך ממנה גם בחי' גבורו' הקשו' לענוש ממש ומשם יש יניק' לחיצונים שהם כחות הדין לקטרג ולפעול רע ממש בבנ\"א וזהו כל עיקר חיותם כמ\"ש במ\"א וד\"ל.\n<b>וזהו</b><sup data-n=\"4990\">41</sup> עד כלותו מעל האדמה אשר אתה בא שמה לרשת\"ה וכן ונסחת\"ם מעל האדמ\"ה כו', כי פי' אדמ\"ה הוא בחי' מל' דאצי' כי ז\"א נק' אד\"ם כידוע והמל' נק' אדמ\"ה והוא ע\"ש האדמומי\"ת ג\"כ לפי שעיקר בנינה מבחי' הגבורו' והיינו מפני שהיא מלאה דמי\"ם הרבה עד שמסתעף ממנה בחי' גבורו' קשות ג\"כ שמהם מקבלי' גם החיצוני' הנק' רע גמור וכמ\"ש סבי\"ב<sup data-n=\"4991\">42</sup> רשעי\"ם יתהלכון והוא בחי' רע שבנוג\"ה מפני שהן יונקי' מה' הדמי\"ם הטמאי' שנק' אדמ\"ה אד\"ם ה' כלומר ה' דמים טמאי' והיינו שהוא מקלל הרע דנוג\"ה בתחלה להכריתם משרש יניקתם הכללית והוא בחי' האדמ\"ה שיש במל' והיינו ה\"ג הקשו' שבדם נדה שנק' אדמ\"ה ואמר עד כלות\"ך אותך מעל האדמה אשר אתה בא שמה לרשתה פי' אשר אתה לוקח יניק' וחיו' והיינו לרשתה לעצמך למקור וחיו', וכל הקללות האלה תוכן הכונה שלהם הוא כדי שעי\"ז תכלה כח יניקת\"ך מעל האדמ\"ה הנ\"ל שלא תקח אותם",[["4985","36","<b>מלך במשפט יעמיד ארץ</b>: משלי כט, ד."],["4986","37","<b>באור פני מלך חיים</b>: משלי טז, טו."],["4987","38","<b>דאנפהא דמלכא נהירין בתמידות</b>: ראה זהר (אד\"ר) נשא קלג, ב."],["4988","39","<b>מפי עליון לא תצא הרעות</b>: איכה ג, לח."],["4989","40","<b>אין רע יורד מלמעלה</b>: ראה ב\"ר פנ\"א, ג."],["4990","41","<b>וזהו עד כלותו</b>: באוה\"ת מסומן כאן סעיף ה)."],["4991","42","<b>סביב רשעים יתהלכון</b>: תהלים יב, ט."]]],[2100990315,"לך לירוש\"ה וזהו עד כלותך מעל האדמה כו', ובתחלה אמר עד השמד\"ך ועד אבד\"ך כו' כי לא יהי' להם עלי' למעלה כלל לברר מהם איזה טוב ואז ממילא יבאו כל הקללו' האלה להשמידם ולאבדם לגמרי ואח\"כ אמר עד כלות\"ך מעל האדמ\"ה שלא יוסיפו עוד לקבל יניק' גם מכאן ולהבא כי יכלו ויאבדו גם שרש יניק' למעלה וד\"ל.\n<b>ועד\"ז</b><sup data-n=\"4992\">43</sup> הוא ענין הפסוק ונסחת\"ם מעל האדמ\"ה כו' שיהיו נעתקים לגמרי מבחי' מל' גם מבחי' הג' הקשו' כי לעתיד הרי יתברר שם ב\"ן לגמרי וכמ\"ש והי'<sup data-n=\"4993\">44</sup> אור הלבנה כאור החמה כו' ולפי שכל זמן הגלות קיבלו יניקה כנ\"ל מקללם שיכרתו ויאבדו גם משרש יניקתם אשר קיבלו כבר וזהו ונסחת\"ם שיכלו אותם מן האדמ\"ה לבל יוסיף עוד לבא שם ערל וטמא כו' וד\"ל. וזהו שאמר מעל האדמ\"ה דוקא כי אינם מקבלי' רק מבחי' מל' ולא מבחי' ז\"א גם מבחי' הגבורו' שבו מטעם הנ\"ל.\n<b>ואחר</b> שהזכיר תוכן הכוונה הכללי' בכל הקללו' האלה שהוא כדי לנתקם ולהכריתם מעל האדמ\"ה כנ\"ל אח\"כ הוא מתחיל לקללם בפרט בקללות המיוחדי' לזה שבהם ועל ידם יוכרתו מעל האדמה כו' והוא מ\"ש יככה<sup data-n=\"4994\">45</sup> ה' כו' שהם בבחי' גבורו' הקשות מאד והוא בחי' הכליון שיש בחמימו' הקשה שבאה מצד ריבוי המותרו\"ת והן כמו שחפת וקדחת ודלקת כו' שזהו כל עיקר שרש יניקתם למעלה מפסולת הדמי' הטמאי' וזהו סיבת איבוד\"ם, וכמ\"ש תמות\"ת<sup data-n=\"4995\">46</sup> רשע רע\"ה שהרע\"ה<sup data-n=\"4996\">47</sup> עצמה תמית אותו וכמ\"ש במ\"א. ומובן זה ממשל העלוקה שמושכת הפסולת של הדם ומתמלאת ונופלת ומתה כו' וד\"ל.\n<b>והיו</b><sup data-n=\"4997\">48</sup> שמיך אשר על ראשך נחשת כו'. פי' כי הנה ידוע דאת<sup data-n=\"4998\">49</sup> זלע\"ז עשה האלקי' וכמו שיש בסטרא דקדוש' בחי' אור פנימי ובחי' אור מקיף כך יש בסט\"א בחי' א\"פ וא\"מ, וע\"ז אמר דהקללה תתפשט בחיצוני' בין בבחי' א\"פ שלהם המקבל להם השפע ובין בבחי' אור מקיף המביא להם השפע מסטרא דקדוש' כו'. וזהו והיו שמיך שהן בחי' אורו' מקיפי' אשר על ראשך להשפיע להם מוחי' תמיד נחש\"ת כמו הנחש\"ת שהוא חם ויבש היפך טבע המים שהוא קר ולח וזה מורה על בחי' העדר השפע מן המשפיע הנק' שמים, שזהו היפך מטר השמי\"ם שהוא כשהן מלאי' כל טוב וברכה כו', והארץ אשר תחתי\"ך בחי' א\"פ המקבל לא יוכל לקבל מפני קושיו שמתקשה כברז\"ל הקשה, וזהו גריעו' המקבל כי המקבל צריך שיהא היפך הקושי דוקא כי כלי בית קיבול א\"א להיו' אלא ברך ולא בקשה כידוע וד\"ל.",[["4992","43","<b>ועד\"ז הוא</b>: באוה\"ת מסומן כאן סעיף ו)."],["4993","44","<b>והי' אור הלבנה כאור החמה</b>: ישעי' ל, כו."],["4994","45","<b>יככה ה'</b>: תבוא כח, כב. כז. כח. לה."],["4995","46","<b>תמותת רשע רעה</b>: תהלים לד, כב."],["4996","47","<b>שהרע\"ה עצמה תמית אותו וכמ\"ש במ\"א</b>: ראה תו\"ח בראשית רנט, ב. רטז, ג. סה\"מ תקס\"ה ח\"ב ע' תרלט. מאמרי אדה\"א במדבר ח\"ב ע' תשסז וע' תת. מאמרי אדה\"א נ\"ך ע' תצח."],["4997","48","<b>והיו שמיך</b>: באוה\"ת מסומן כאן סעיף ז)."],["4998","49","<b>דאת זלע\"ז עשה האלקי'</b>: ע\"פ קהלת ז, יד."]]],[2100990316,"<b>יתן</b><sup data-n=\"4999\">50</sup> ה' מטר ארצך אבק ועפר כו'. פי' מטר ארצ\"ך הוא בחי' מ\"ה שיוצא ונמשך מן המשפיע למקבל שנק' ארצ\"ך כי השפע מ\"ד נמשל לגשמים שיורדין טיפין טיפין וכמ\"ש כי<sup data-n=\"5000\">51</sup> יבעל בחור כו'.\n<b>ומתחלה</b> דיבר בקללה על עצמו' המשפיע שיהא ריקן מכל שפע מצד עצמו שיהא כנחש\"ת וכן במקבל מצד עצמו כנ\"ל ועתה מקלל גם מה שנשפע מהמשפיע ונק' מט\"ר שיהא כאבק ועפר שאינו מצמי\"ח כלל, כי האב\"ק שרשו מיסוד האש המכלה ובמטר כתיב והרו\"ה<sup data-n=\"5001\">52</sup> את הארץ והוליד\"ה והצמיח' כו' לפי שהמטר ממים הוא מבחי' החסדי' המגדל ומצמיחי' כטבע בחי' החסדי' כו' כידוע אבל האב\"ק חם ויבש לכך אינו מגדל, וקילל המט\"ר של המשפיע שיהא כאבק ועפר שאינו מגדל כי אינו מרו\"ה את הארץ כלל וגם הנה העפר אין בו חיו' אלא מעט מזעיר כי הוא קר ולח (וגם יש בו מבחי' הגבורו' וע\"כ נצטוו ליתן מעפ\"ר<sup data-n=\"5002\">53</sup> אשר בקרקע המשכן במי נדה כו' כמ\"ש במ\"א), וזהו מורה על בחי' העדר החיו' ג\"כ כמו המת שאין בו חיו' הוא קר כעפר וע\"כ נא' והכל<sup data-n=\"5003\">54</sup> תשוב אל העפר כו', וכל זה קללה לרע שבנוג\"ה שלא יהא לו מקום יניק' מסטרא דקדושה משום צד וכנ\"ל וד\"ל.\n<b>מן</b><sup data-n=\"5004\">55</sup> השמים ירד עליך עד השמדך. פי' מן השמים הוא בחי' ז\"א דאצי' שנק' שמי\"ם וכמ\"ש ואתה<sup data-n=\"5005\">56</sup> תשמע השמי\"ם כידוע, והענין הוא כי בחי' המלחמה ללחום עם החיצוני' כדי להאבידם הוא דוקא מבחי' ז\"א ולא מבחי' מל' וכמ\"ש ה'<sup data-n=\"5006\">57</sup> אי\"ש מלחמה כו' וכמ\"ש וירעם<sup data-n=\"5007\">58</sup> מן שמי\"ם ה' ועליו\"ן יתן קולו כו' כי האיש<sup data-n=\"5008\">59</sup> דרכו לכבש המלחמה ולא האשה כו', והטעם הוא כי הנה מבואר למעלה דבחי' ז\"א רובו חסדים והדיני\"ן שבו מכוסי' ונעלמי' בחסדי' ואין לחיצוני' יניק' מהם כו' משא\"כ בנוק' דז\"א שיש לחיצוני' אחיזה שם ולכך אין ביכולת הנוק' ללחום עמהם ולהאבידם אחר שיש להם מקום ושרש אחיז' בדינין וצמצומי' שבמל' אבל בחי' ז\"א להיותו רם ונבדל מהם הרבה עד שאין להם שרש ומקום יניק' ממנו כלל ע\"כ ביכולתו ללחום עמהם להאבידם כו'.\n<b>וענין</b> המלחמה הוא לעורר עליהם מבחי' הדיני' הנעלמי' בחסדי' כמ\"ש ימינ\"ך<sup data-n=\"5009\">60</sup> הוי' תרעץ אויב וידוע שימי\"ן הוא בחי' קו החסדי' ואמר שימין ה' דוקא הוא",[["4999","50","<b>יתן ה' מטר ארצך</b>: באוה\"ת מסומן כאן סעיף ח)."],["5000","51","<b>כי יבעל בחור</b>: ישעי' סב, ה."],["5001","52","<b>והרוה את הארץ והולידה והצמיח'</b>: ישעי' נה, יו\"ד."],["5002","53","<b>מעפר אשר בקרקע המשכן</b>: לשון הכתוב נשא ה, יז."],["5003","54","<b>והכל תשוב אל העפר</b>: קהלת ג, כ — הכל היה מן העפר והכל שב אל העפר."],["5004","55","<b>מן השמים</b>: באוה\"ת מסומן כאן סעיף ט)."],["5005","56","<b>ואתה תשמע השמי'</b>: מלכים-א ח, לב. לד. לו. לט."],["5006","57","<b>ה' איש מלחמה</b>: בשלח טו, ג."],["5007","58","<b>וירעם מן שמים ה'</b>: שמואל-ב כב, יד — ירעם מן שמים ה'."],["5008","59","<b>האיש דרכו לכבוש</b>: יבמות סה, ב."],["5009","60","<b>ימינך ה' תרעץ אויב</b>: בשלח טו, ו."]]],[2100990317,"אשר תרעץ אויב דוקא, ולכאורה יפלא זה האיך יתכן שבמדת החסדי' ידין דין אף לאויב. אך הענין הוא דכל מה שנגדלו ונתגברו בחי' החסדי' בז\"א לישראל מזה נעשה ונמשך בחי' גבורו' ודיני' עצומים לפרעה וחילו, וזהו ימינ\"ך הוי' לישראל בזה תרעץ אויב דוקא. וביאור הדברים הוא כי בחי' הדיני' נעלי' ומכוסי' באנפוהי דמלכא דנהירין כנ\"ל אך כאשר אור החסד מאיר בגילוי לישראל עמו אזי יצאו הדיני' מתוך ההעלם על ההיפך המנגד לישראל, ומקודם שיצאו החסדי' בגילוי לישראל היו הדיני' נעלמי' אך כאשר יצאו בגילוי בהכרח שיצאו גם הדיני' הנעלמי', ולהיכן יצאו אם לא אל בחי' הקליפ' המנגד לאותו אור החסד שנתגלה כו'.\n<b>ויובן</b> דבר זה ממלך ב\"ו שיגלה אור טובו וחסדו לאוהבו לאיזה טעם שיש לו בזה הנה מזה הטעם עצמו יצא דין ועונש למקטרג על אוהבו כו', והא בהא תליא דלפי ערך טעם ההטבה לאוהב כן ערך הטעם לעונש לשונא כו', ונמצא ריבוי החסדי' גורמי' ריבוי הדיני' לההיפך המנגד כו' וד\"ל. וזהו מן השמי\"ם דז\"א ירד עליך בגילוי והיינו הדיני' שהיו נעלמי' תחלה בחסדי' יתגלו עלי\"ך כדי להאביד הר\"ע שבנוג\"ה, והוא כמו ענין המלחמה שהי' לה' עם שר של מצרים שריבוי החסדי' לישראל היו סיבה לאיבוד פרעה וחילו בים וכמ\"ש ימינך הוי' תרעץ אוי\"ב כנ\"ל וגם כאן או' עד השמד\"ך וד\"ל.\n<b>יתנך</b><sup data-n=\"5010\">61</sup> ה' נגף לפני אויביך בדרך אחד תצא אליו ובשבעה דרכים תנוס לפניו. פי' בדר\"ך אח\"ד הוא בחי' יסוד דנוק' שנק' דר\"ך אח\"ד, דהנה כל בחי' יסוד נק' דר\"ך לפי שבו עובר השפע, ובכל מקום יש בו ביסוד בחי' ההתכללות מכללות רבים ולכך נק' דר\"ך אח\"ד לפי שמתאחדי' שם רבים ונק' בזוהר בשם כניש\"ו<sup data-n=\"5011\">62</sup> דכל נהורין שכל האורו' מתכנסי' ביסוד ומתאחדי' בו והיו לאחדים ממש, עד\"מ הידוע מכל שפע סתם שכלולה מכללות מה שבשכל ומדו' שהתכללו' זאת בא' ביסו\"ד דוקא והוא הבל הלב שיוצא בגילוי לדיבור כו' וכיוצא בזה, וידוע שיש ב' מיני יסוד<sup data-n=\"5012\">63</sup> א' יסו\"ד דדכורא שהוא המשפיע השפע מלמעלה למטה ונק' ג\"כ דר\"ך וכמ\"ש דר\"ך<sup data-n=\"5013\">64</sup> גבר בעלמה, ויש בחי' יסוד דנוק' שהוא בחי' המקבל כל ההשפעו' ונק' ג\"כ דר\"ך כמ\"ש הנות\"ן<sup data-n=\"5014\">65</sup> בי\"ם דר\"ך ונק' ג\"כ דר\"ך אח\"ד לפי שמתאחדת שם לקבל השפע בתכלית היחוד וההתכללו' מלמטה למעלה ונק' מ\"ן והיינו ענין התכללות של הנשמות ומלאכים רבים מאד שנכללו ביסוד דנוק' וכמ\"ש ביד\"ך<sup data-n=\"5015\">66</sup> אפקי\"ד רוח\"י וידוע שהוא בחי' יסו\"ד דנוקבא שנק' באר כמ\"ש עלי<sup data-n=\"5016\">67</sup> באר ר\"ת",[["5010","61","<b>יתנך ה'</b>: באוה\"ת מסומן כאן סעיף י)."],["5011","62","<b>כנישו דכל נהורין</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' רח. במדבר ח\"א ע' צד (ובמילואים שם)."],["5012","63","<b>יסוד דדכורא</b>: ראה זהר מקץ ר, א. ויחי רמו, ב. אור החמה לזהר ויצא קנה, א ד\"ה והרח\"ו."],["5013","64","<b>דרך גבר בעלמה</b>: משלי ל, יט."],["5014","65","<b>הנותן בים דרך</b>: ישעי' מג, טז."],["5015","66","<b>בידך אפקיד רוחי</b>: תהלים לא, ו."],["5016","67","<b>עלי באר ר\"ת דבידך אפקיד רוחי כידוע בכתבי האריז\"ל</b>: חוקת כא, יז. וראה פע\"ח שער (טז) ק\"ש שעהמ\"ט פ\"ב, פ\"י. מאמרי אדה\"ז פרשיות התורה ח\"א ע' נט. ובהנסמן לשם. מאמרי אדה\"א דברים ח\"ד ע' א'רסה. וש\"נ. שמות ח\"א ע' רעז."]]],[2100990318,"דביד\"ך אפקיד רוחי כידוע בכתבי האריז\"ל ולכך נק' דר\"ך אח\"ד לפי שמתאחדים בה ריבוי נשמו' ומלאכי' והיו לאחדי' בהתכללו' אחת להיות מעלין מ\"ן ביסוד דנוק' כו' ע\"ד שמתאחדי' כל אורו' הנשפעי' מלמעלה למטה שהוא בחי' מ\"ד שביסוד דדכורא כנ\"ל וד\"ל.\n<b>והנה</b> להיו' כי על בחי' יסו\"ד דנוק' נא' זה השער להוי' שכולן עולין ונכללי' בו ויכולי' הכל ליכלל בה גם מי שיש בו אפס קצה מן חלק הטו\"ב שברפ\"ח ניצוצי' שנפלו כו' וכמאמר הנ\"ל בהאי נוג\"ה מפתי לה לאיתתא ונטיל נהורהא כי חלק הטו\"ב שבנוג\"ה עולה גם הוא עם המלאכי' ונשמו' בהעלא' מ\"ן ביסו\"ד דנוק', ומפתי לה ונטיל גם הוא אור וזיו האלקי בשעת היחוד כו' לפי שמתכלל גם הוא בתוך כללות המתכללי' אחר שהכל יכולי' ליכנס שם וא\"כ גם בחי' הר\"ע דנוג\"ה יוכל ליכנס לשם ולקבל יניק' גם הוא מבחי' היחוד העליון דזו\"נ כו', הנה לזה הוא מקלל את בחי' הר\"ע דנוג\"ה ואמר בדר\"ך אח\"ד תצ\"א אליו פי' בדרך אח\"ד דהיינו בחי' יסוד דנוק' ודאי תוכל גם אתה לצאת ולהתכלל שם כנ\"ל, אבל לא תהי' לך תקות יניק' משם כי אח\"כ בשבע\"ה דרכי\"ם תנו\"ס לפניו פי' בז' דרכים הן בחי' ז' המדו' דז\"א דאצי' שיש לכאו\"א דרך ומבוא בפ\"ע קודם שמתכנסי' בדרך אח\"ד שהוא בחי' יסוד כו' והרי מבואר למעלה דמן השמי\"ם שהוא בחי' ז\"א ירד על ר\"ע דנוג\"ה להלחם בו כו' וא\"כ מכל ז' המדו' דז\"א ילחם עמו וכמ\"ש ה'<sup data-n=\"5017\">68</sup> איש מלחמה כו', ובז' מדו' דז\"א אין לחיצוני' שרש יניק' ואחיזה כלל מטעם הנ\"ל שבחי' ז\"א עצמו מרומם ונבדל מכל ההשתלשלו' כו' ומה שיש להם אחיזה ויניק' הוא בבחי' יסו\"ד דנוק' בהעלא' מ\"ן שבה שהוא נקרא דרך אח\"ד מלמטה למעלה שיכולי' הכל לעלות שם אבל בהגלות נגלות מז' המדו' דז\"א מלמעלה שנק' ז' דרכי\"ם שמלמעלה למטה ששם אין להם שרש אחיז' כלל ממילא ינוסו החיצוני' ויתבטלו ממציאותם לגמרי. וזהו בז' דרכי\"ם תנו\"ס לפני\"ו וד\"ל. ולפ\"ז יתפרש פי' בז' דרכי\"ם בב' אופנים, הא' מפני הז' דרכים דאצי' העליוני' וכנ\"ל, ועוד יתפרש כפשוטו שינוסו בז' דרכי\"ם כי הרי יש דרך מיוחד לכל מדה ומדה לבער ולכלות הרע בדרך מלחמה הנ\"ל ולכך בז' דרכי\"ם ממש ינוסו ופי' לפני\"ו היינו כמ\"ש כהמ\"ס<sup data-n=\"5018\">69</sup> דונ\"ג מפני אש יאבדו רשעים מפני אלקי' כו' וד\"ל.\n<b>והיית</b><sup data-n=\"5019\">70</sup> לזעוה לכל ממלכו\"ת הארץ. פי' ממלכו\"ת האר\"ץ הן בחי' ז' מלכין קדמאין דתוהו דכתיב בהו וימלוך וימ\"ת שכולם בבחי' ב\"ן דמלכו' וירדו למטה בשם ב\"ן דבי\"ע והן רפ\"ח ניצוצו' דתוהו ששם ב\"ן מברר מהם בכל יום וכמ\"ש ותקם<sup data-n=\"5020\">71</sup> בעוד לילה כו'. והנה משיורי הז' מלכי' שלא נתברו הן הן בחי' קליפות הטמאו' לגמרי והוא בחי' הרע דנוג\"ה הנ\"ל אבל כל חלק הטוב שבקליפ'",[["5017","68","<b>ה' איש מלחמה</b>: בשלח טו, ג."],["5018","69","<b>כהמס דונג מפני אש</b>: תהלים סח, ג."],["5019","70","<b>והיית לזעוה</b>: באוה\"ת מסומן כאן סעיף יא)."],["5020","71","<b>ותקם בעוד לילה</b>: משלי לא, טו."]]],[2100990319,"נוג\"ה מתברר לעתיד וכמ\"ש מלך<sup data-n=\"5021\">72</sup> אלקי'<sup data-n=\"5022\">73</sup> על גוי\"ם שע' שרים יתבררו ג\"כ לעתיד כמ\"ש והיו<sup data-n=\"5023\">74</sup> מלכי\"ם אומנייך כי יהיו בטילי' לקדוש' ונק' עבדי\"ם כמו עבד כנעני וכמו שמבואר למעלה בענין ועמדו זרי\"ם ורעו צאנכם כו', וכאשר יהי' עליי' גם לבחי' הטו\"ב שבנוג\"ה ויוכלל גם הוא בקדוש' האלקי' הנה אזי ישאר בחי' הרע שבנוג\"ה למטה לזעו\"ה לכל<sup data-n=\"5024\">75</sup> ממלכו' הארץ שיבדלו המלכים הנ\"ל מהם ויתרחקו מהם תכלית הריחוק, כי המלכים שעל הארץ ששרשם מז' מלכין קדמאי' הרי יתבררו ויהפכו גם הם בטוב וא\"כ ממילא יהי' נמאס בעיניהם חלק הר\"ע דנוג\"ה עד שיהיו בעיניהם לזעו\"ה כו'.\n<b>וזהו</b> והיית לזעו\"ה לכל ממלכו\"ת הארץ דקאי על חלק הר\"ע דנוג\"ה שיהי' לזעו\"ה בעיני כל הממלכו\"ת של הארץ לפי שהן כולם יבאו בבירור ע\"י שם ב\"ן המבררם כנ\"ל, אבל חלק הרע דנוג\"ה יבדל ויורחק גם משם ב\"ן דבי\"ע, ומ\"ש לכל ממלכו\"ת הארץ לשון ריבוי כי יש הרבה שרי ממלכו\"ת באר\"ץ שכולם מקבלי' משם ב\"ן שהוא בחי' מל' דאצי' בכלל ונק' ממלכו\"ת הארץ אבל ס\"מ וממנן דילי' דעאק\"ו לישראל יהיו בעיניהם לזעו\"ה על שלא נתבררו גם הם ולא נכללו בקדוש' אם היו מכבדים לישראל כמבואר במאמר התיקוני\"ם הנ\"ל וד\"ל.\n<b>והיתה</b><sup data-n=\"5025\">76</sup> נבלתך<sup data-n=\"5026\">*76</sup> למאכל לכל עוף השמים ולבהמת הארץ ואין מחריד. פי' נבלת\"ך הוא לשון נובלו\"ת כמו נובלות<sup data-n=\"5027\">77</sup> חכמה וכיוצא. והענין הוא דהנה",[["5021","72","<b>מלך אלקים</b>: תהלים מז, ט."],["5022","73","<b>אלקים על</b>: בגוכתי\"ק יש סימן שיש כאן הג\"ה על הצד, אבל חסר בצידי הגליון. ובאוה\"ת כאן רשום: אלקים שהוא שם ב\"ן כו' על."],["5023","74","<b>והיו מלכים אומנייך</b>: משלי מט, כג."],["5024","75","<b>לכל ממלכות הארץ</b>: תבוא כח, כה."],["5025","76","<b>והיתה נבלתך</b>: באוה\"ת מסומן כאן סעיף יב)."],["5026","*76","<b>והיתה נבלתך. . ולבהמת הארץ</b>: ראה לקו\"ת שמיני יח, ד:\nהנה יש להקדים מ\"ש במ\"א ע\"פ והיתה נבלתך למאכל לכל עוף השמים ולבהמת הארץ כו' והענין שכל הקללות הם על הרע דנוגה ופי' נבלתך לשון נובלות היינו מה שנפל בבחי' נובלות ושבירת הכלים ומעורב תוך הרע דנוגה לא ישאר בו מאומה לעתיד אלא ילקטוהו עוף השמים ובהמת הארץ עוף השמים היינו כמארז\"ל ע\"פ ועוף יעופף ועוף זה מיכאל כו'. (ועיין בזח\"א בפ' בראשית די\"א סע\"ב ודי\"ב ע\"א ובע\"ח שער מ\"ן ומ\"ד דרוש ד' מענין עופין כו'. וע' בזח\"ג בפ' צו דכ\"ו ע\"ב ובפ' שמיני דל\"ט סע\"ב ובמק\"מ ובהרמ\"ז). ויש מלאכים שנקראים בהמת הארץ והוא המרכבה פני אריה פני שור כו' וגם בנשמות בני אדם יש ב' מדריגות אלו שיש נשמות שנק' עוף וכמ\"ש בזח\"ג בפ' פינחס (דרי\"ז ע\"ב) אשר שם צפרים יקננו בטוליהון מקננן נשמתיהון דצדיקייא וכ\"ה בזהר ח\"א בפ' ויצא (דקס\"ב סע\"ב) ויש נשמות שנק' בהמת הארץ כמ\"ש גור אריה יהודה יששכר חמור גרם כו' בכור שורו. והענין שבבחי' א' יש יתרון מעלה בעוף על הבהמה. שהעוף הוא פורח בכנפיו הגבה למעלה באויר משא\"כ הבהמה. ובבחי' א' יש יתרון בבהמה על העוף דהעוף זוטר חיותיה. ולכן הכשרו בסימן א' אבל הבהמה חיותה רב ועד\"ז יובן למעלה דבחי' המלאכים שנק' עוף השמים וכן הנשמות שמבחי' זו יש להם יתרון שיוכלו לעוף ולעלות בעילוי עד רום המעלות ע\"י הגדפין אהוי\"ר (וע' מענין העפיפה בהרמ\"ז פ' שמיני ד' ט\"ל סע\"ב ועמ\"ש עוד מענין בחי' העופות בפ' בהעלותך סד\"ה אם את כל דגי הים כו') ויש ג\"כ יתרון מעלה בבחי' המלאכים ונשמות הנק' בהמת הארץ שכחם רב וגדול וכמ\"ש בחיות המרכבה והחיות נושאות את הכסא כו' הרי שכחם עצום להיות נושאות את הכסא ועל הכסא כמראה אדם כו'. והנה ממוצא דבר מבואר דעם היות שבחי' עוף יש בו יתרון בחי' העפיפה לעלות בעילוי כו' עכ\"ז יש ג\"כ יתרון עצום לבחי' בהמת הארץ ברוב הכח שבהם. ובמ\"א נת' דהכח הזה בחיות המרכבה להיות נושאות את הכסא היינו לפי שהן ממה שנתברר משבה\"כ שהוא מעולם התהו כו' ששם הי' ריבוי האור כו' ועפ\"ז י\"ל דמה\"ט אין כן בעופין לפי שהן נמשכו מזיווג נשיקין וזיווג דנשיקין הוא אפילו כשא\"צ לברר משבה\"כ כמ\"ש בע\"ח שם בהדיא, וצ\"ע דלכאורה משמע שכל המלאכים יצאו מזיווג נשיקין כמ\"ש בע\"ח שם. ומ\"מ עכ\"פ יש יתרון לבחינת בהמה על בחי' עוף בענין הכח והגבורה כו' הגם שיש יתרון לעוף בענין העפיפה כו' (ואפשר לומר דזהו כענין בחי' ב' שמות מ\"ב וע\"ב שבשמע והיה אם שמוע אשר שם מ\"ב הוא בחי' העלאות ובשתים יעופף כו' והוא בחינת ובכל מאדך שבפ' שמע ובחי' זו הוא נעלה יותר משם ע\"ב כמ\"ש בפ' תרומה דקל\"ב ב'. אך להיות המשכת אלקות מלמעלה למטה ע\"י תורה ומצות מעשיות זהו בחי' שם ע\"ב ונתתי עשב בשדך לבהמתך ע\"ב שי\"ן (כמ\"ש בת\"ז)."],["5027","77","<b>נובלות חכמה</b>: ב\"ר פי\"ז, ה."]]],[2100990320,"גם בחי' הרע שבנוג\"ה מ\"מ יש בו קצת מבחי' הטוב דקדוש' ממה שנפל בו בבחי' גלות ונק' נובלו\"ת לפי שנפל שם מלמעלה כענין הנפילי\"ם<sup data-n=\"5028\">78</sup> היו בארץ כו', וכן בכל דור ובכל זמן יש כמה ניצוצי' קדושה שנופלים בקליפה ומשתקעים שם ונק' נופלי\"ם וכמ\"ש סומך<sup data-n=\"5029\">79</sup> ה' לכל הנופלי\"ם והם שם בבחי' גלות כענין גלות<sup data-n=\"5030\">80</sup> השכינה בכלל בע' שרים וכמ\"ש<sup data-n=\"5031\">81</sup> במ\"א ע\"פ עת אשר שלט האד\"ם באד\"ם כו', וע\"ז קילל אותו ג\"כ דמה שנפל ברע דנוגה בבחי' נופלי\"ם ונק' נבלת\"ך גם זה לא ישאר בו אלא ילקטוהו עוף השמים ובהמת הארץ ויהי' להם למאכל ולא ישאר שום טוב ברע דנוג\"ה.\n<b>וענין</b> עוף<sup data-n=\"5032\">82</sup> השמי\"ם הן המלאכים כמ\"ש רז\"ל ועוף<sup data-n=\"5033\">83</sup> יעופף עוף זה מיכאל כו', ויש מלאכי' שנק' בהמת הארץ והוא בחי' המרכבה דפני<sup data-n=\"5034\">84</sup> אריה להימין ופני שור מהשמאל כו' ונק' חיות ובהמות כידוע, וגם בנשמות יש ב' מדרגות הללו עוף השמים ובהמת הארץ, כי יש נשמו' שנק' עופות ויש נשמו' שנק' חיו' ובהמו' כאריה ושור שהרי ביהודה<sup data-n=\"5035\">85</sup> נא' ארי\"ה וביוסף<sup data-n=\"5036\">86</sup> שור ויש נשמו' שנא' בהם כצפור<sup data-n=\"5037\">87</sup> נודדת כו', והענין של ב' מדרגו' הללו הנה יש יתרון מעלה בעוף על בהמה ויש יתרון מעלה בבהמה [על] עוף, דהנה בעוף ובהמה הגשמיי' אנו רואי' דהעוף זוטר חיותי' מחיות הבהמה וע\"כ הכשרו בסימן א' בלבד והבהמה בב' סימני' משום דחיותה<sup data-n=\"5038\">88</sup> רב",[["5028","78","<b>הנפילים היו בארץ</b>: בראשית ו, ד."],["5029","79","<b>סומך ה' לכל הנופלים</b>: תהלים קמה, יד."],["5030","80","<b>גלות השכינה בכלל בע' שרים</b>: ראה זהר בראשית מו, סע\"ב. סידור שער המילה קמה, ג."],["5031","81","<b>וכמ\"ש במ\"א ע\"פ עת אשר שלט האדם באדם</b>: קהלת ח, ט. תו\"ח בראשית לג, ב בהערה 11."],["5032","82","<b>עוף השמים הן המלאכים. . מלאכי' שנק' בהמת הארץ</b>: ראה בכ\"ז לקו\"ת שמיני יח, ד שנסמן בהערה *76."],["5033","83","<b>ועוף יעופף עוף זה מיכאל</b>: בראשית א, כ. ב\"ר פ\"ג, ח. ראה זהר בראשית מו, ב. ובהנסמן בהערה *76. בחיי בראשית שם."],["5034","84","<b>דפני אריה להימין</b>: ראה יחזקאל א, י."],["5035","85","<b>ביהודה נא' ארי\"ה</b>: ראה ויחי מט, ט."],["5036","86","<b>וביוסף שור</b>: פ' ברכה לג, יז."],["5037","87","<b>כצפור נודדת</b>: משלי כז, ח."],["5038","88","<b>דחיותה רב וכמ\"ש בגמ'</b>: ראה חולין נז, א. וראה לקו\"ת הנסמן בהערה *76."]]],[2100990321,"וכמ\"ש בגמ', ויש יתרון מעלה בעוף על בהמה במה שהעוף הוא פורח הגבה למעלה מעלה מה שאין כח זה בבהמה כלל כידוע.\n<b>והדוגמא</b> מזה יובן למעלה בנשמו' ומלאכי' העליוני', דהנשמו' ומלאכי' שנק' עוף השמים הנה אע\"פ שחיותם מועט דהיינו שהאור האלקי מצומצם בו מאד אבל מ\"מ יתרון מעלה יש בהם על אותן הנשמו' ומלאכי' שנק' בהמו' וחיות במה שיוכלו לעלות בעילוי למעלה מעלה ברום המעלות ע\"י הכנפים שלהם שהן המדו' אוי\"ר שנושאי' אותם מאד הגבה למעלה מה שאין ביכולת אותם הנשמו' ומלאכי' שנק' בהמו' להגיע לשם כלל וכלל. ויש יתרון מעלה בנשמו' ומלאכי' שנק' חיו' ובהמו' במה שחיותם מאור האלקי רב מאד כמו פני אריה ופני שור הנושאו'<sup data-n=\"5039\">89</sup> את הכסא שיש בהם ריבוי הכח והחיות עד שביכולתם יש כח ועוז גדול כזה להיות נושאו' עליהם את הכסא כו' וד\"ל.\n<b>ועכ\"פ</b> יהי' איך שיהי' בענין הברורי' דניצוצי הטוב מבחי' הנובלו\"ת שנפלו ברע דנוג\"ה הנה ב' מדרגות הללו מנשמו' ומלאכי' הנק' עוף השמי\"ם ובהמת הארץ שניהם יבררו וילקטו בחי' הטו\"ב ההוא זה לפי כחו בהעלא' עד רום המעלות וזה כפי כחו בריבוי החיו' כו' ומבין שניהם יחד לא ישאר מאומה מן הנובלו\"ת ברע דנוג\"ה כי יאכלוהו עוף השמים ובהמת הארץ הנ\"ל לגמרי עד שלא ישאר רק בחי' הרע עצמו כמו שהוא בלתי נובלו\"ת כלל, וזהו והיתה נבלת\"ך למאכ\"ל לעו\"ף השמי\"ם ולבהמ\"ת האר\"ץ ואין מחריד וד\"ל.\n<b>והיית</b><sup data-n=\"5040\">90</sup> ממשש בצהרי\"ם כאשר ימשש העור באפילה כו'. פי' בצהרי\"ם הוא כשהאור של השמש מאיר בתגבורת גדול שאז האור בהיר וצהיר כענין צה\"ר<sup data-n=\"5041\">91</sup> תעשה כו' ולכך נק' צהרי\"ם כלומר צוה\"ר היום וגם החום של השמש מתגברת בצהרי\"ם יותר מכל היום, וכך יובן למשכיל למעלה דיש עת מיוחד למעלה ונק' צהרי\"ם והוא בשעה שהאור האלקי מאיר בגילוי גדול עד שהכל מקבלי' האור ולא חשך האור להאיר בכל מקום גם מפחותי הערך במדרגו' הנמוכו' ועד\"מ יובן זה ממלך ב\"ו כשעושה סעודה ומשתה גדולה שקוראין לכל אדם על הסעודה ומקבלי' כולם שפע וברכה גם העבדים הקטני' ופחותי הערך כעניים הנבזים ושפלים וגם יגיע להבהמות וחיו' הגרועי' כמו גם לכלבים העצמו' הנופלים וזורקין מעל השולחן ואין זה אלא לפי שגדול אור החסד כ\"כ עד שימצא נובלו\"ת הרב\"ה שמספיקי' לכל גם להיותר נמוך במדרגה עד שגם הכלב מקבל מזונו כו', והנמשל יובן למעלה שזהו הנק' צהרי\"ם שמגיע למטה בחי' נובלו\"ת הרבה מפני ריבוי האור כי רב הוא מאד עד שהכל מקבלי' אין איש נעדר שלא יקבל רב טוב ושפע, ואעפ\"כ קיללו לר\"ע דנוג\"ה שגם בסעוד\"ת הצהרי\"ם למעלה יהי' ממשש באפיל\"ה כי לא יקבל אור גם",[["5039","89","<b>הנושאו' את הכסא</b>: ראה בחיי תרומה כה, יוד בשם הפדר\"א ספ\"ד."],["5040","90","<b>והיית ממשש</b>: באוה\"ת מסומן כאן סעיף יג)."],["5041","91","<b>צהר תעשה</b>: לשון הפסוק נח ו, טז."]]],[2100990322,"בשעה ההיא שהיא עת רצון לכל וגם לכלבי\"ם לא יהי' לו דמיון וערך כלל מפני שנלקח ממנו כל טו\"ב ולא נשאר רק רע גמור וע\"כ ימשש כעו\"ר באפילה גם בצהרי\"ם וד\"ל.\n<b>והיית</b><sup data-n=\"5042\">92</sup> אך עשוק כל הימים כו'. פי' מלבד שלא יהא לו תקוה ועליי' למעלה אלא שיהי' תמיד עשו\"ק וגזו\"ל, מפני שיבררו ויגזלו ממנו כל חלקי ניצוצי הטוב שקיבץ בגזל כל זמן הגלות וכמ\"ש גוז\"ל<sup data-n=\"5043\">93</sup> אביו ואמו כו', וכל מי שירצה יעשו\"ק ויגזו\"ל אותו הטוב, וזהו והיית אך עשו\"ק וגזו\"ל כל הימים כו' וד\"ל.\n<b>אשה</b><sup data-n=\"5044\">94</sup> תארש ואיש אחר ישגלנה בית תבנה ולא תשב בו כרם תטע ולא תחללנו. פי' אש\"ה תאר\"ש כי יש בחי' אירוסין ונישואין בקליפה כמו שיש בחי' אירוסין ונישואין בסטרא דקדושה. דהנה ידוע בחי' אירוסי' בקדושה הוא בחי' המשכת אור המקיפי' בחופ\"ה וקידושי' בטבעת<sup data-n=\"5045\">95</sup> עגול הן עניני אורו' מקיפי' ואח\"כ נעשה היחוד והזווג בבחי' המשכת א\"פ כו'.\n<b>וביאור</b> הדברים ידוע שבקידושי' באמרו הרי את מקודש\"ת לי ממשיך עליו אור מקיף והוא הנק' בחי' אירוסי\"ן<sup data-n=\"5046\">96</sup> למעלה וכמ\"ש וארשתי\"ך<sup data-n=\"5047\">97</sup> לי באמונה כו' ואח\"כ נעשה גופו של יחוד בהמשכת מ\"ד כו' דהיינו בבחי' א\"פ, וכך יש בסט\"א בחי' מקיפי' דאירוסין בתחלה ואח\"כ בחי' נישואין דיחוד בהמשכת א\"פ. דהנה אנו רואי' כאשר נתפסה איזה ניצוץ האלקי בידי החיצוני' כמו בנפול הנופל באיזה תאוה רעה כו' הרי תחלה הוא מהרהר הרהורים רעים הרבה מאד וזהו הנק' בגמרא הרהורי<sup data-n=\"5048\">98</sup> עבירה שקשין מגופה של עבירה להיותם באי' על הניצוץ בבחי' מקיף להקיפה ולבלבלה מכל צד ופנה במחשבו' זרות שונות מאד עד שמושקעת ונופלת בתוך הבלבול ההוא ממחשבו' והרהורי' הרעים ומחמתם נעשה סיבה אח\"כ להיות הניצוץ ההוא באה לידי גופה של העבירה בפ\"מ שזהו כמו בבחי' היחוד דקדושה בהמשכת א\"פ כך משפיעי' החיצוני' שפע בפ\"מ באותו הניצוץ ובתחלה מארסין בבחי' המקיפי' לבלבלה במ\"ז כנ\"ל ואח\"כ מייחדי' אותה בבחי' נישואי\"ן ממש לגמור העבירה עמה בפ\"מ כו' וכמ\"ש בספרי הקבלה וד\"ל.\n<b>וזהו</b> שקילל לר\"ע דנוג\"ה אם יארס ניצוץ מניצוצי הטוב בבחי' מקיפי' לבלבלה במ\"ז כנ\"ל לא יבא עמה לידי היחוד בהמשכת א\"פ הנק' נישואי\"ן שזהו היה עיקר הכונה באירוסין כי איש ישגלנה, מפני שהכל יוציאו ממנה וגם אחר שתפס",[["5042","92","<b>והיית אך עשוק</b>: באוה\"ת מסומן כאן סעיף יד)."],["5043","93","<b>גוזל אביו ואמו</b>: משלי כח, כד."],["5044","94","<b>אשה תארש</b>: באוה\"ת מסומן כאן סעיף טו)."],["5045","95","<b>בטבעת עגול. . מקיפי'</b>: ראה תו\"א מד, א. באוה\"ת ברכה ע' א'תתמה."],["5046","96","<b>אירוסין למעלה</b>: ראה ג\"כ לקו\"ת שה\"ש מח, א. סידור (עם דא\"ח) ברכת נישואין קלח, ג ואילך. אוה\"ת שה\"ש ע' תז. ועוד."],["5047","97","<b>וארשתיך לי באמונה</b>: הושע ב, כב."],["5048","98","<b>הרהורי עבירה שקשין מגופה של עבירה</b>: יומא כט, א. וראה ביאוה\"ז פינחס קיא, א."]]],[2100990323,"בניצוצי הטוב בבחי' מקיפי' יוציאו אותו הניצוץ ויעלה ויתייחד למעלה ביחוד העליון האלקי ולא יגיע ממנה שום אור ברע דנוג\"ה ונמצא כל מה שטרח בבחי' אירוסי\"ן לא עשה כלום, וזה צער גדול מאד לר\"ע דנוג\"ה עד\"מ המארס אשה בגשמיו' ובא אחר ונושאה וד\"ל.\n<b>ועד\"ז</b> יתפרש בית תבנה בחי' כלי לאורו', והוא בהיפוך מענין אירוסי' שקדם המקיף לא\"פ ובבנין הבית שוכן המקיף על הבית אחר המשכת א\"פ, וגם ע\"ז קיללו שלא ישב הוא במקיפי' דבי\"ת אשר יבנ\"ה גם לאחר שטרח וגזל א\"פ מהניצוצו' דקדוש' אבל לא יתיישב הוא בבי\"ת זה שהוא המקיף שעשה לא\"פ כו' וד\"ל. ועד\"ז כרם תטע אע\"פ שגזל אורו' ונטעם בתוך שלו ונעשה כר\"ם, אבל איש אחר יחללנו שיוציאו ויבררו מהכרם ההוא כל הטוב דקדוש' למעלה ונמצא יגיעתו לריק כו' וד\"ל.\n<b>שורך</b><sup data-n=\"5049\">99</sup> טבוח לעיני\"ך ולא תאכל ממנו. פי' שור\"ך השו\"ר אשר הוא שלך דוקא אשר בא מבחי' פני שור אשר מהשמא\"ל למעלה כידוע דבחי' פסולת הגבורו' דאותו שו\"ר הוא למטה<sup data-n=\"5050\">100</sup> והוא נעשה שרש לקליפת נוג\"ה בבחי' הר\"ע שבה וכידוע בענין שרש דשו\"ר מועד כו' ואותו השו\"ר יהי' טבו\"ח לעיני\"ך ולא תאכל ממנו.\n<b>והענין</b> הוא כי הנה ידוע בענין הקרבנות שע\"ג המזבח שהדם הנזרק ע\"ג המזבח הוא בחי' העלא' הטוב והמובחר של החיו' לקדוש' האלקי' במתן הדמים כנגד היסו\"ד של המזבח כו' והקטרת האימורי' לריח ניחוח לה' הוא עולה בבחי' הפנימיו' יותר כידוע אך האיברי' והפדרי' שלא נתאכלו מבע\"י שהולכין וקריבין כל הלילה מהם ניזונין גם הע' שרים של מעלה כי זהו רק בחי' התמצית הניתן לחיצונים ג\"כ בלילה וכמ\"ש בזוהר אבל פנימי' החיו' עולה למעלה כי בחי' הברורי' דנוג\"ה הפנימי' דנוג\"ה עולה והחיצוניו' יורדת למטה וכך הקרבנות הדם שהוא בחי' פנימי' דנוג\"ה עולה ונכלל במזבח וכן הקטרת האימורי' ביום אך החיצוניו' מהם הנשאר בלילה יכולי החיצוני' לקבל יניק' משם וזהו מבואר בספרי הקבלה ולע\"ל שיבורר כל חלקי הנוג\"ה מבחי' הטוב שבה אזי לא יתנו עוד חלק מקרבנו' לחיצוני' כלל אלא יהי' הקרבן כולו כליל ע\"ג המזבח כי גם החיצוניו' יוכל לעלות במזבח כו' וא\"כ גם מבחי' פסולת הגבורו' דפני שור העליון שבמרכבה שממנה נעשה הפר למטה לקרבן ע\"ג המזבח ג\"כ יהי' כולו כליל כו' ולא יבא ממנו שום חלק שפע לחיצוני' שהן בחי' הר\"ע דנוג\"ה כנ\"ל.\n<b>וזהו</b> שור\"ך טבו\"ח, שור\"ך השייך לחלק\"ך וגורלך יהי' טבו\"ח בהעלא' ע\"ג המזבח מכל וכל גם בחיצוניות שלו ולא יגיע לך חלק ממנו כלל ולא תאכ\"ל ממנו",[["5049","99","<b>שורך טבוח</b>: באוה\"ת מסומן כאן סעיף טז)."],["5050","100","<b>למטה</b>: באוה\"ת כאן: למעלה."]]],[2100990324,"מאומה, והיינו הקללה שמקלל לרע דנוג\"ה שגם מהשו\"ר שלו לא יאכל, ולא עוד אלא שלעיניו יהי' טבו\"ח כנ\"ל ולא יאכל ממנו מטעם הנ\"ל וד\"ל. ועד\"ז יתפרש חמור\"ך וצאנ\"ך כו' הכל מדרגו' שמקבלי' מהן נוג\"ה ומכולם יבורר הכל ולא ישאר מהם שום מחי' ומזון יניקה לר\"ע שבנוג\"ה וד\"ל.\n<b>זרע</b><sup data-n=\"5051\">101</sup> רב תוצי\"א השד\"ה ומעט תאסוף כי יחסלנו הארב\"ה. פי' ארב\"ה<sup data-n=\"5052\">102</sup> בגי' יצח\"ק והוא בחי' גבורו\"ת דיצח\"ק העליו\"ן שמכלה ואוכל כל מה שמתברר מרפ\"ח ניצוצי' דתוה\"ו ואע\"פ שהרבה ניצוצי' העליוני' נפלו ונזרעו במקום היכלות החיצונים כי זר\"ע ר\"ב תוציא השד\"ה שהוא שם ב\"ן כו' אך מעט מהם תאסוף אליך ולא יגיע לך רק חלק א' מריבוא כי הכל יאכלנו הארב\"ה והוא בחי' גבורו' דקדוש' הנק' ארב\"ה כידוע בפי' וארב\"ה את זרעו במ\"א כו' וד\"ל.\n<b>כרמים</b><sup data-n=\"5053\">103</sup> תטע ועבדת ויין לא תשתה ולא תאגור כי תאכלנו התולעת. פי' תולע\"ת<sup data-n=\"5054\">104</sup> הוא בחי' שם מ\"ב דאנא בכח כו' שנק' תול\"ע כי תול\"ע מספרו תק\"ו שהוא מספר אבגית\"ץ שעולה ג\"כ תק\"ו, וכמ\"ש בספרי הקבלה והוא בחי' חסד שבגבורה כידוע דאנא<sup data-n=\"5055\">105</sup> בכח יש בו ז\"פ ששה תיבות וששה תיבו' הראשוני' הוא חסד שבגבורה וששה תיבו' השניי' גבורו' שבגבורו' כו' עד מל' שבגבורה הן ששה תיבו' האחרוני' וע\"ז נא' ביד\"ך אפקי\"ד רוח\"י מפני שכל העלא' הנשמו' למעלה ע\"י שם מ\"ב הוא, וע\"כ כשאו' ביד\"ך אפקי\"ד רוח\"י דהיינו שהנשמה רוצה לעלו' וליכלל למעלה בהכרח שתעלה ע\"י שם מ\"ב והוא אנא בכח כו' וכמ\"ש במ\"א, ואמנם כח הששה תיבו' הראשוני' דאנא בכח הוא בחי' חסד שבגבור' כו' וזהו הנק' בשם תול\"ע, והטעם הוא כי הנה התולע הגשמי אין כחו אלא בפיו בלבד ולא מצד עצמו שהרי התולעת יוכל לקצוץ גם אילן עב וגס מאד בפיו שיאכלנו מעט מעט עד אשר יכנס בכל עוביו ויקצצנו כמו שקוצצין בגרזן וכיוצא, והנמשל למעלה היינו שיש כח אלקי בקדוש' שאין כחו אלא בפיו ונמשל בשם תול\"ע והוא שמכרית ומבדיל את אור השפע האלקי המלובש בחיצוני' שלא יקרבו גם הם ויקבלו יניק' כמו שהתולע הגשמי יקצץ הארז הגבוה והוא בחי' חסד שבגבורה להיו' כי כח כריתה זו היא חסד לסטרא דקדוש' אע\"פ שהוא דין לסט\"א, ועד\"ז הוא בחי' התפלה בכלל כי במה שעושין ישראל בתפלתם הוא מצד הכח אשר יש בפיהם בלבד דהיינו בדיבור בתפלה כמו התולע שאין כחו אלא בפיו ולכך נא' אל תיראי תולע\"ת יעקב כו' וד\"ל.",[["5051","101","<b>זרע רב</b>: באוה\"ת מסומן כאן סעיף יז)."],["5052","102","<b>ארבה בגי' יצחק. . במ\"א</b>: ראה סה\"מ תקס\"ב ח\"א ע' ה בשם הלקו\"ת — ראה שם טעמי המצות פ' שמיני. פע\"ח (שער הק\"ש) ש\"ח, פכ\"ח. סידור שער התקיעות רמז, א. תו\"ח תולדות קנג, ב. וישלח קפב, א."],["5053","103","<b>כרמים תטע</b>: באוה\"ת מסומן כאן סעיף יח)."],["5054","104","<b>תולעת הוא בחי' שם מ\"ב דאנא בכח</b>: ראה אוה\"ת חקת (הוספות) ע' 34 שמביא ענין זה ממאמר זה."],["5055","105","<b>דאנא בכח. . ז\"פ ששה תיבות</b>: ראה ג\"כ לקו\"ת מסעי צב, ב."]]],[2100990325,"<b>וכך</b> הוא הענין כאן דר\"ע דנוג\"ה כאשר יטע כרם מזריעת אורו' עליוני' שנפלו שמה כנ\"ל יהי' מקולל שלא יגיע לו מן הכרם שום יין באסיפה כי תאכלנ\"ו התולע\"ת הוא שם מ\"ב בששה תיבו' הראשוני' דאנא בכח שמספרו תול\"ע והוא הכח האלקי אשר הוא קוצץ וכורת היניק' מן החיצוני' כנ\"ל וע\"כ לא יגיע לחיצוני' שום יניק' מהכרם הזה וד\"ל.\n<b>זיתים</b><sup data-n=\"5056\">106</sup> יהיו לך בכל גבולך ושמן לא תסוך. פי' זהו ענין קללה באופן יותר קשה משאר הקללות לפי שיש בה הוספת צער ויגון יותר משאר קללות, כי שאר קללו' הם רק העדר הטוב מכל וכל ואין הצער קשה כ\"כ כשאין לאדם כלום מיגיעתו וטרחתו שיוכל לומר לנפשו שהרי זה כאילו לא עשה כלום בתחלה, אך בהיות האדם מייגע ומוצא קצת תקוה מיגיעתו בעשותו בחי' הכלי להיו' מוכן להכנס בו אור ושפע כמו הזיתים שיהיו לאדם בכל גבולו שיש ריבו\"י הכלי\"ם ואמנם כאשר האור לא יבא בהם כלל והיינו ושמן לא תסו\"ך זהו שבירת לב וצער גדול יותר משלא הי' לו כלום, וכך הוא למעלה בקללה זו לקלל ר\"ע דנוג\"ה שיהיו לו זיתי\"ם בכל גבולו ולא יסו\"ך שמ\"ן דחכמ\"ה כו' כלומר הכלי יהי' לך והאור לא תקח כדי לצערו ביותר ואמר הטעם כי יש\"ל זיתי\"ך כו'.\n<b>הגר</b><sup data-n=\"5057\">107</sup> אשר בקרבך יעלה עליך מעלה מעלה ואתה תרד מטה מטה. פי' הג\"ר הוא בחי' מל' דאצי' שהיא בגלות בע' שרים כמ\"ש כי<sup data-n=\"5058\">108</sup> גר הייתי בארץ נכריה כו' וכמארז\"ל גלו<sup data-n=\"5059\">109</sup> לאדום שכינה עמהם ועד עתה הי' בחי' הג\"ר הזה בגלות ובדוחק אצל הר\"ע דנוג\"ה שפעלו בהם רע ונשתעבדו בהם בישראל כנ\"ל במאמר התיקוני' וכשיתברר כל הטו\"ב שבנוג\"ה אזי יבאו כל הקללו' האלה על בחי' הר\"ע דנוג\"ה להאבידו ולהכריתו לגמרי מלמעלה כנ\"ל שזהו תוכן הקללה בכל הקללו' וע\"כ אמר שיהי' אז להיפך מכמו שהי' שהגר הי' בגלו' ואז הג\"ר אשר בקרב\"ך יעלה מעלה כי שם ב\"ן המלובש בנוג\"ה יתעלה ויעלה עמו גם כל חלקי הטוב שבה והר\"ע דנוג\"ה יפול למטה, וזהו ואתה תרד מט\"ה מט\"ה וד\"ל.\n<b>ומסיים</b><sup data-n=\"5060\">110</sup> טעם הקללות כולם תחת<sup data-n=\"5061\">111</sup> אשר לא עבדת ה' כו', פי' תחת אשר לא נדבקת בקדוש' להיות טפל ובטל לישראל ולאוקיר להו וכנ\"ל בתיקוני' והי' לך עלי' ג\"כ עם עליי' המל' ולא הי' לך ירידה כלל, אך אתה עשית ההיפך שפעלת רע ונפרדת מישראל לגמרי כנ\"ל ע\"כ באו עליך כל הקללו' האלה ורדפו\"ך עד השמד\"ך כו' כנ\"ל וד\"ל.",[["5056","106","<b>זיתים יהיו לך</b>: באוה\"ת מסומן כאן סעיף יט)."],["5057","107","<b>הגר אשר בקרבך</b>: באוה\"ת מסומן כאן סעיף כ)."],["5058","108","<b>כי גר הייתי בארץ נכריה</b>: שמות ב, כב. יתרו יח, כג."],["5059","109","<b>גלו לאדום שכינה עמהם</b>: ספרי ס\"פ מסעי. וראה מגילה כט, א."],["5060","110","<b>ומסיים טעם הקללות</b>: באוה\"ת מסומן כאן סעיף כא)."],["5061","111","<b>תחת אשר לא עבדת</b>: תבוא כח, מז."]]],[2100990326,"<b>(וי\"ל</b><sup data-n=\"5062\">112</sup> הגר אשר בקרבך היינו ט\"ס דנוק' המתלבשי' בקליפות אחר חורבן בית שני כמ\"ש בע\"ח שער מיעוט הירח פ\"ב ושער מ\"ח פ\"ג, והיינו בסוד עת אשר שלט כו', אך זהו לרע לו כי עי\"ז יבררו ממנו ואז תתעלה המל' למעלה מעלה כו').",[["5062","112","<b>(וי\"ל הגר. . מעלה כו')</b>: הג\"ה זו, בגוכתי\"ק כ\"ק אדמו\"ר הצ\"צ, נדפסה ג\"כ באוה\"ת כי תבוא כרך ו ב'שצה (מגוכתי\"ק זה)."]]],[2100990327,"<h3>כי כארץ תוציא צמחה</h3>\n<b>בעזר\"ה שבת פ' נצבים</b>\n<b>כי</b><sup data-n=\"5063\">1</sup> כארץ תוציא צמחה וכגנה זרועיה תצמיח כן יצמיח ה' צדקה ותהלה נגד כל הגוים<sup data-n=\"5064\">2</sup>. הנה כל<sup data-n=\"5065\">3</sup> הנביאים לא נתנבאו על שכרן של המצות רק לענין אכילת פירותיהן בעוה\"ז בשכר גשמי לעתיד אבל לענין שכר הרוחני שיש בכל מצוה מצד עצמה כי שכר<sup data-n=\"5066\">4</sup> מצוה מצוה ע\"ז נא' עין<sup data-n=\"5067\">5</sup> לא ראתה כו' ולא דיברו הנביאים בזה כלל אך אעפ\"כ ישנה בהעלם בכל נפש מישראל בבחי' עבודה גם עתה בעשותו המצוה ובזמן ר\"ה ויו\"כ נתגלה מן ההעלם והיינו כללות ענין הפסוק הזה כן יצמיח ה' צדקה כו'.\n<b>ולהבין</b> ביאור ענין זה הנה בעי\"ת<sup data-n=\"5068\">6</sup> אומרי' המלך הקדוש כו' ולכאורה אין לזה טעם דבשלמא בר\"ה<sup data-n=\"5069\">7</sup> המלך יושב על כסא דין אומרי' המלך הקדוש אבל בעי\"ת שאחרי ר\"ה מאיזה טעם אומרי' המלך הקדוש המלך המשפט וגם מהו ענין המלך אצל הקדוש כי קדושה ענין אחר ומלוכה ענין אחר ולמה תיקנו לומר זה בברכת אתה קדוש ולא בשאר ברכות.",[["5063","1","<b>כי כארץ תוציא צמחה</b>: נעתק מגוכתי\"ק 1025 (קא, א). נמצא ג\"כ בכת\"י 611 פח, א. נדפס בתו\"א — לעמברג תרי\"א כה, ד.\nמאמר זה באריכות מכ\"ק אדה\"א נדפס במאמרי אדה\"א נצבים ע' תתצח ואילך.\nמאמר זה נדפס בתוס' הגהות וכו' בלקו\"ת נצבים נ, ב. ועם הגהות אחרות (מפ' נצבים תקצ\"א) נדפס באוה\"ת נצבים כרך ו ע' ב'תג. ובלקו\"ת שם ק, א. נדפס קיצורים. וראה לקמן ע' תשט קיצורים להמאמר. וראה מאמרי אדה\"א הנחות תקע\"ז ע' שמ שמיוסד על מאמר זה."],["5064","2","<b>כי כארץ תוציא צמחה. . נגד כל הגוים</b>: ישעי' סא, יא. וראה לקו\"ת שם הג\"ה — (ועיין בזוהר תרומה קס\"ו, ב)."],["5065","3","<b>כל הנביאים לא נתנבאו</b>: ברכות לד, ב. מובא ברש\"י עה\"פ בישעי' (סד, ג)."],["5066","4","<b>שכר מצוה מצוה</b>: אבות פ\"ד מ\"ב. ראה תניא רפל\"ז. פל\"ט (נב, ב)."],["5067","5","<b>עין לא ראתה</b>: ישעי' סד, ג. וראה לקו\"ת בהעלותך לד, א."],["5068","6","<b>בעי\"ת אומרי' המלך הקדוש</b>: ברכות יב, ב. שו\"ע אדה\"ז הל' ר\"ה סתקפ\"ב ס\"א-ב. וראה עטרת ראש שער ר\"ה ו, א."],["5069","7","<b>בר\"ה המלך יושב על כסא דין</b>: ראה ר\"ה ח, סע\"א. טז, א-ב. וראה ויק\"ר כט, ח. שו\"ע אדה\"ז שם רסתקפ\"ד."]]],[2100990328,"<b>אך</b> הענין הוא כי הנה ידוע דהמלאכי' נבראו ברוח פיו וכמ\"ש ברוח<sup data-n=\"5070\">8</sup> פיו כל צבאם ועד\"מ הבל הלב באדם למטה שיוצא בקול לדיבור אבל שרש &lt;שמז&gt;\nהנשמות עלו במחשבה עליונה וכמאמר ישראל<sup data-n=\"5071\">9</sup> עלה במחשבה כו' וההפרש אשר ביניהם למעלה הנה מובן ממה שאנו רואי' בהפרש שיש בין הבל הדיבור למחשבה למטה דהנה הבל הלב הוא נמשך מהגוף החומרי ואע\"פ שהוא בחי' העלם לגבי קול הדיבור אבל מתאחד ההבל עם שאר הגוף גם הנה נעשה ההבל מופרד בקול הדיבור משא\"כ המחשבה שמתאחדת עם השכל הנה היא התפשטות השכל ולא התפשטות גופני וגם איננה נפרדת בבחי' הפירוד בקול הדיבור הגם שהיא ג\"כ בחי' העלם לגבי הדיבור כי אין למחשבה קשר וחיבור במהות א' עם קול הדיבור משא\"כ הבל הלב שמהותו ממש מתפשט בקול הדיבור וד\"ל וכדוגמא זאת יובן למעלה דבי' מאמרו' נבראו כל הנבראי' גם המלאכים וכמו שאמרו במדרש ועוף<sup data-n=\"5072\">10</sup> יעופף עוף זה מיכאל כו' אבל ישראל עלו במחשבה קודם שבא הדיבור בי' מאמרות והיינו בראשית<sup data-n=\"5073\">11</sup> בשביל ישראל שנק' ראשית לפי שעלו במחשבה שקודם ששת ימי בראשית כו' והמה מתאחדי' בחכמה עליונ' כמו שיש יחוד אמיתי למחשבה עם השכל משא\"כ הבל הדיבור דרוח פיו בי' מאמרו' שהוא נבדל וגם הוא רק מבחי' התפשטו' הגוף ולא מהתפשטו' הנפש השכלי' כנ\"ל וד\"ל.\n<b>ב</b> והנה ידוע דירידת<sup data-n=\"5074\">12</sup> הנשמו' בעוה\"ז בחומר גופני הוא לצורך עלי' והעלי' היינו למעלה גם ממקור חוצבם במחשבה עליונה ואם לאו אין זו עלי' והענין הוא כי מתעלים לבחי' קדש העליון וכמ\"ש כי<sup data-n=\"5075\">13</sup> עם קדוש אתה וכתיב קדש<sup data-n=\"5076\">14</sup> ישראל לה' כו' אבל הנה אמרו ז\"ל ע\"פ<sup data-n=\"5077\">15</sup> קדושים תהיו יכול כמוני ת\"ל כי קדוש אני קדושתי למעלה מקדושתכם. ולהבין ביאור כל זה הנה המלאכי'<sup data-n=\"5078\">16</sup> אומרי' ג\"פ קדוש בוי\"ו כי הוי\"ו<sup data-n=\"5079\">17</sup> מורה ההמשכה והוא בחי' ההמשכה שנמשך מקדש העליון בלבד ולא גופו ומהותו של קדש וג\"פ קדוש היינו ג' מיני המשכו' וירידות מקדושה העליונה העצמי' מתחלה יורד אור הקדש למחשבה וממחשבה למדות וממדו' לדיבור כו' עד שקדוש הג' הוא הוי' צבאות להוות כל צבא השמים ברוח פיו כנ\"ל שמן הדיבור הוא שרש התהוות המלאכי' משא\"כ למעלה מבחי' המחשבה דהיינו בעצמו' אור המאציל אין למלאכי' שום השגה עד שיאמרו קדוש בהמשכת וי\"ו כי אין ערוך כלל וכלל בין עצמותו ומהותו ית' לנאצלי' ונבראי' וכמשל זיו השמש שאין לו ערך עם גופו של שמש שגם אם ימעט האור ע\"י ריבוי המסכים אין זה נוגע כלל",[["5070","8","<b>ברוח פיו כל צבאם</b>: תהלים לג, ו."],["5071","9","<b>ישראל עלה במחשבה</b>: ב\"ר רפ\"א."],["5072","10","<b>ועוף יעופף עוף זה מיכאל</b>: בראשית א, כ. זח\"א מו, ב. אוה\"ת חנוכה כרך ה ס\"ע 1836. לעיל ע' תרצד."],["5073","11","<b>בראשית בשביל ישראל</b>: ראה רש\"י בראשית א, א. הנסמן בלקו\"ש ח\"ג ע' 820 הערה 7."],["5074","12","<b>דירידת הנשמו'. . לצורך עלי'</b>: ראה גם תו\"ח ח\"ש קלב, ג. ובהנסמן לשם."],["5075","13","<b>כי עם קדוש אתה</b>: ואתחנן ז, ו."],["5076","14","<b>קדש ישראל לה'</b>: ירמי' ב, ג."],["5077","15","<b>ע\"פ קדושים תהיו יכול כמוני</b>: קדושים יט, ב. ויק\"ר פכ\"ד, ט."],["5078","16","<b>המלאכי' אומרי' ג\"פ קדוש</b>: ישעי' ו, ג."],["5079","17","<b>הוי\"ו מורה ההמשכה</b>: ראה אגה\"ת פ\"ד."]]],[2100990329,"לעצמיו' השמש כך כתיב כי<sup data-n=\"5080\">18</sup> שמש ומגן הוי' אלקי' וע\"כ נא' בהוי' אני<sup data-n=\"5081\">19</sup> הוי' לא שניתי כידוע ולזה הטעם או' המלאכי' איה<sup data-n=\"5082\">20</sup> מקום כבודו כו' אך הנשמו' שמקיימין המצות בעוה\"ז בהתלבשם בגופים דוקא בזה הן מגיעי' לבחי' עצמותו ומהותו ית' בקדש העצמי שלמעלה מקדוש בוי\"ו שהמלאכי' אינם משיגי' ואו' איה כו' וזהו אשר קדשנו במצוותיו פי' בקדש עצמו כי המצות הן הן רצונו ממש ונק' רצון העליון שלמעלה מן החכמה והטעם כו' כענין שתוק<sup data-n=\"5083\">21</sup> כך עלה במחשבה לפני לפי שאין טעם כלל לרצון ולכך נק' תרי\"ג<sup data-n=\"5084\">22</sup> מצו' דאוריי' וז' דרבנן בשם תר\"ך עמודי אור לפי שהם בבחי' כתר שהוא בחי' רצון העליון ועי\"ז קדשנו בקדש העליון שלמעלה &lt;שמח&gt;\nמקדוש והיינו שאמרו ז\"ל עתידים<sup data-n=\"5085\">23</sup> צדיקים שיאמרו לפניהם קדוש כו' לפי שלעתיד יהי' קדש זה בגילוי ויאמרו לפניהם קדוש בוי\"ו להמשיכו למטה כו' וד\"ל וזהו ועשיתם<sup data-n=\"5086\">24</sup> את כל מצוותי והייתם קדושים שהמצו' מביאין לידי קדושה העליונה הנ\"ל ומ\"ש לאלקיכם לפי שעי\"ז צרורי' הם בצרור החיים את ה' ממש וכמ\"ש רננו<sup data-n=\"5087\">25</sup> צדיקים בה' בה' ממש וד\"ל.\n<b>אבל</b> עכשיו קדש זה הוא בהעלם בכל מצוה בעשותה וקצת קדוש' זו נמשך באמרו ברכת המצוה ברוך אתה ה' כו' כי פי' ברכה זו ג\"כ ע\"ד הנ\"ל דהנה ברכת<sup data-n=\"5088\">26</sup> המצוה היא מד\"ס כדי לעורר קדוש' עליונה הנ\"ל וזהו פי' ברו\"ך כלומר שיהא ברוך ונמשך מלמעלה מעצמו' אור א\"ס דכולא קמי' כו' להיות בבחי' בריכה מן ההעלם לגילוי בשם הוי' והיינו ברוך אתה לנוכח כו' עד שיהי' נק' מלך העולם וע\"י קבלת מלכות שמים יוכל לקבל אח\"כ קדושה העליונ' באמרו אשר<sup data-n=\"5089\">27</sup> קדשנו במצוותיו כו' כי מדת מלכות הוא מתלבש בזמן ומקום מלך ימלוך כו' ויש כלי לשכון בו אור קדש העליון כו' וד\"ל.\n<b>וזהו</b> שאמרו ז\"ל בברכות המצות שצריך לברך עליהן עובר<sup data-n=\"5090\">28</sup> לעשייתן דהנה לשון עובר לישנא דאקדומי הוא כידוע והענין הוא כי המצות הן מלובשי' בדברים גשמיים כלבישת טלית ותפילין וכיוצא וכדי שיוכל אור קדש העליון הנ\"ל לשכון בדבר גשמי צריך להקדים לעשות לזה הכנה בתחלה קודם עשיית המצוה והוא בברכת המצוה שימשיך קדש העליון בקבלת מ\"ש שמקבל תחלה כנ\"ל והיינו פי' עובר לעשייתן לישנא דאקדומי להקדים להמשיך מריש כל דרגין להיות ברוך",[["5080","18","<b>כי שמש ומגן הוי' אלקי'</b>: תהלים פד, יב."],["5081","19","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["5082","20","<b>איה מקום כבודו</b>: נוסח קדושת כתר."],["5083","21","<b>שתוק כך עלה במחשבה</b>: מנחות כט, ב."],["5084","22","<b>תרי\"ג מצות דאוריי' וז' דרבנן בשם תר\"ך עמודי אור</b>: ראה פי' ר\"מ בוטריל לס\"י פ\"ב, מ\"ג [ירושלים תשכ\"ב לט, ד] בשם ר\"י ב\"ר נסים. פרדס שער מהות והנהגה פ\"ג. ונמנו בפרטיות בספר שיעור קומה [להרמ\"ק] סצ\"ג [צא, א]."],["5085","23","<b>עתידים צדיקים שיאמרו לפניהם קדוש</b>: ב\"ב עה, ב. ראה אמרי בינה שער הק\"ש עח, ב."],["5086","24","<b>ועשיתם את כל מצותי והייתם קדושים</b>: שלח טו, מ."],["5087","25","<b>רננו צדיקים בה'</b>: תהלים לג, א."],["5088","26","<b>ברכת המצוה היא מד\"ס</b>: ראה ברכות טו, א. רמב\"ם הל' ברכות פ\"א ה\"ב וה\"ג."],["5089","27","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות."],["5090","28","<b>עובר לעשייתן</b>: פסחים ז, ב."]]],[2100990330,"ונמשך במלך העולם וכנ\"ל ואזי יוכל לשכון אור קדש העליון גם למטה כמו בלבישת טלית ותפילין כו' וד\"ל אך הנה גם על קדש זה העליון שנמשד במצות מעשיו' אמרו יכול כמוני ת\"ל כי קדוש אני קדושתי למעלה מקדושתכם פי' גם מקדושתכם שע\"י המצות והטעם יתבאר בסמוך בעזר\"ה וד\"ל.\n<b>ג</b> וזהו כי כארץ תוציא צמחה וכגנה זרועיה תצמיח וכו'. דהנה הגרעין הנזרע בארץ אין לו כח וטעם כלל שיהי' סיבת הצמיחה מכחו של גרעין ולכאורה יפלא מדוע יצמח ממנו פרי בטעמה עד שיש בה עונג ממש, אך הענין הוא דעיקר הצמיחה אינו מחמת הגרעין אלא מחמת כח<sup data-n=\"5091\">29</sup> הצומח שיש בארץ מכבר מששת ימי בראשית והוא מבחי' מאמר תדשא<sup data-n=\"5092\">30</sup> הארץ דשא כו' ועץ עושה פרי כו' ועשב מזריע זרע כו' שכל זה המאמר מלובש הוא בכח הצומח שבארץ הכללי להוציא כל מיני צמח בטעמים שונים כו' מן האדמה והכל נצמח ע\"י המאמר הזה אלא שיש בו התחלקו' מאמר עץ עושה פרי מצמיח פירות האילן ומאמר דעשב מזריע זרע מצמיח הזרעים שבגינה והארץ תוציא צמח התבואות וכיוצא בזה מתחלק עוד לרבבו' מיני צמיחת עונג וא\"כ מה מהצורך לכאורה לזרוע הגרעין אחר שכל צמיחה באה רק מכח הצומח אבל הענין הוא לפי שאין הברכה שורה מן כח המצמיח אלא כשיש בחי' כלי לשכון בו הברכה וכמאמר הזוהר<sup data-n=\"5093\">31</sup> דלית ברכתא שריא באתר רקניא כו' ע\"כ זורעין הגרעין שיהא בחי' כלי לשכון בו אור שפע כח הצומח &lt;שמט&gt;\nלהצמיח על ידו מיני צמח הרבה כו' והמופת לזה הוא ממה שהזרע<sup data-n=\"5094\">32</sup> הנזרע כלה בארץ כי כל כחו נכלל בכח הצומח שבארץ להיו' מוריד משם ההמשכה כו' וד\"ל.\n<b>והדוגמא</b> מכל זה יובן למעלה בארץ העליונה דאור הזרוע בה בכנ\"י היינו בחי' מעשה המצות שעושין בעוה\"ז וכמאמר זורע<sup data-n=\"5095\">33</sup> צדקות כו' ולעתיד תוציא צמחה מכח הצומח שיש בה בריבוי טעמים ותענוגים שונים והוא תענוג הנשמו' שיהיו נהנין מזיו ועונג העליון בריבוי מדרגות שונות שזהו ענין שכר מצות בג\"ע התחתון ובג\"ע העליון שמתגלה שם בחי' עונג העליון מבחי' כתר והוא כמשל כח הצומח שבארץ והוא עונג נפלא עד שכדאי לסבול כל יסורי גיהנם עד שיזכה לעונג זה וכמו שאמרו באחר דמוטב<sup data-n=\"5096\">34</sup> דלידייני' כו' וזה העונג הוא צומח מכח הזריעה שנזרע במעשה המצות בעוה\"ז והגם שאוכל<sup data-n=\"5097\">35</sup> פירותיהן בעוה\"ז זהו שכר הגשמי בלבד אבל שכר הרוחני שלא דיברו בה הנביאי' היינו בחי' זיו ועונג העליון",[["5091","29","<b>כח הצומח. . מששת ימי בראשית</b>: ראה רמב\"ן בראשית א, יא."],["5092","30","<b>תדשא הארץ דשא כו' ועץ עושה פרי כו' ועשב מזריע זרע</b>: ראה בראשית א, יא-יב."],["5093","31","<b>הזוהר דלית ברכתא שריא באתר רקניא</b>: ראה זהר יתרו פז, ב. תרומה קנה, א. (רעיא מהימנא) צו לד, א. ויחי רטז, ב."],["5094","32","<b>שהזרע. . כלה בארץ</b>: ראה אגה\"ק ס\"ח (קיג, א)."],["5095","33","<b>זורע צדקות</b>: ברכת יוצר."],["5096","34","<b>דמוטב דלידייני'</b>: חגיגה טו, ב."],["5097","35","<b>שאוכל פירותיהן בעוה\"ז</b>: ראה קידושין לט, ה. וש\"נ."]]],[2100990331,"שנצמח מהם והוא שאמרו שכר מצוה מצוה עצמה שהוא בחי' רצון ועונג העליון כנ\"ל בפי' אשר קדשנו במצוותיו כו' וד\"ל.\n<b>ומה</b> שאמר וכגנה זרועיה לשון רבים לפי שיש ב' זריעות הא' זריעה גשמית והוא זריעת גופה של מעשה המצוה שהיא באה בפועל ממש בהגשמה גדולה ומזה נצמח בחי' הזי\"ו בג\"ע התחתון בלבד וזריעה הב' היינו זריעה רוחניו' יותר והוא כונות המצות כי כל המצות<sup data-n=\"5098\">36</sup> צריכות כונה דוקא כידוע והכונה הוא בלבו ומוחו שהוא ענין רוחני יותר מגופה של מעשה המצוה כי הרי עיקר הכוונה היא לדבקה בו ית' ע\"י מעשה המצוה הזאת וכן במצות ל\"ת בחי' הכונה הוא שלא להיו' נפרד עי\"ז מיחודו וכמ\"ש ולא<sup data-n=\"5099\">37</sup> תתורו כו' אשר אתם זונים אחריהם כמו הזונה<sup data-n=\"5100\">38</sup> עד\"מ שאסורה לבעלה וכך א\"א לו עוד לקבל השפע מקדש העליון ולדבקה בו כשיעשה איזה עון וחטא ממצות ל\"ת ובמה שהוא סור מרע בפ\"מ גם בלתי כוונה זו ה\"ז כמו הזריעה בגשמיו' בעשיי' המצות כי גם העדר ומניעת המעשה בשם מעשה יחשב כענין עקימת<sup data-n=\"5101\">39</sup> שפתיו הוי מעשה כו' ובכל המצות מ\"ע ומל\"ת בחי' העשי' היא זריע' גשמי' והכונה היא בחי' זריעה רוחניו' וזהו שאמר זרועי\"ה ב' זריעו' והצמיחה ג\"כ באה מהם בב' מדרגו' ג\"ע העליון וג\"ע התחתון וזהו זרועי\"ה תצמיח וד\"ל.\n<b>והנה</b> מלבד ב' צמיחות הללו יש עוד מדרגה שלישית והוא הצמיחה אשר תצמח בלתי זריעה כלל כענין הספיחים<sup data-n=\"5102\">40</sup> והם העשבים שנצמחים ממילא ומאליו בלתי זריע' כלל וכלל וזהו פי' כארץ תוציא צמחה תוציא מעצמה את צמחה בלתי זריעה כלל וזהו מדרגה נמוכה גם מבחי' זריעה גשמית הנ\"ל והיינו כמו ענין התפוחים שגדילין ונצמחין ביער שאע\"פ שיש בהן ג\"כ איזה טעם מ\"מ אין טעמן דומה כלל לטעם פרי התפוחים הגדילי' באילנות שבגינה לפי שתפוחי היער גדילי' מצד עצמם אבל תפוחי' שבגינה טעמן מתוקי' ביותר מסיבת הזריעה מנטיעת אילן תפוח וכו' ועד\"ז בכל הפירו' ידוע שיש שינוי גדול בין פירו' הצומחי' ע\"י זריעה בין פירו' הצומחין מאליהן כו' והנמשל מזה יובן במעשה המצות שמדרגה זו הג' היינו ענין מצות מעשיו' אשר נעשים בלא כוונה כלל וכלל רק ע\"י מצות<sup data-n=\"5103\">41</sup> אנשים מלומדה בלבד שאין כאן בחי' זריעה כלל אך מ\"מ הארץ תוציא &lt;שנ&gt;\nצמחה מצד עצמה לעתיד גם מאותן מצות אנשים מלומדה דהיינו מצד כח הצומח שיש בה כו' (שהוא ענין אתעדל\"ע בלתי אתעדל\"ת כו' והיינו בעי\"ת שאז נא' ויעבור<sup data-n=\"5104\">42</sup> ה' על פניו ויקרא",[["5098","36","<b>המצות צריכות כונה</b>: ראה עירובין צה, סע\"ב."],["5099","37","<b>ולא תתורו</b>: שלח טו, לט."],["5100","38","<b>הזונה עד\"מ שאסורה לבעלה</b>: סוטה כו, ב. וראה שערי תשובה ח\"א שער התשובה פ\"ד-ה."],["5101","39","<b>עקימת שפתיו הוי מעשה</b>: ראה ב\"מ צ, סע\"ב."],["5102","40","<b>הספיחים. . שנצמחים ממילא</b>: ראה תו\"ח ויחי קו, ב-ג. וראה ג\"כ תו\"א ויגש מד, ג. סה\"מ תקס\"ה ח\"א ע' קצח. סידור שחרית נח, ג. ובכ\"מ."],["5103","41","<b>מצות אנשים מלומדה</b>: ישעי' כט, יג. וראה גם הנסמן בתו\"ח ויחי רמב, סע\"ג הערה 44."],["5104","42","<b>ויעבור ה' על פניו ויקרא</b>: תשא לד, ו."]]],[2100990332,"בהתעורר' עצמותו גם שלא יש העלא' מ\"ן מלמטה כלל וכמשי\"ת בסמוך) וזהו כי כארץ תוציא צמחה כו' כן יצמיח ה' כו' וד\"ל.\n<b>ד</b> אך הנה כל זה כשהאדם הוא סור מרע ועשה טוב כמו שמהראוי להיות שאז הוא ענין הזריעה והצמיחה ע\"ד הנ\"ל, אבל כאשר האדם מבטל מצות מעשיות נקרא חוטא שהחטא<sup data-n=\"5105\">43</sup> הוא לשון חסרון כידוע וגם בביטול מ\"ע נעשה חסרון ופגם בהעדר אור הקדוש' כו' אבל בפגם העובר על ל\"ת הוא קשה מן החטא והוא<sup data-n=\"5106\">44</sup> הנק' עון מלשון העוה<sup data-n=\"5107\">45</sup> דרכו כו' שהעון הוא פוגם ממש להיו' מזה יניקה לחיצוני' שהוא עיוות דרך מפני שנק' מעוות ועקום כו' וד\"ל. ועל העון והחטא שבאדם נאמר ולרשע<sup data-n=\"5108\">46</sup> מה לך לספר חוקי פי' מה לך כי הגם שהחוקים והמצות הן בודאי בחי' המשכו' גילוי אלקות אבל מ\"ה ל\"ך כי אליך אין מגיע מהם שום גילוי אור מפני העון והחטא שפוגמים האור ומעוות הדרך וא\"כ מה לך לספר חוקי אחר שאין מגיע לך כלום מהם אלא הולכי' ליכלל למעלה ולך אין מגיע כלום וד\"ל.\n<b>ולהיות</b> כן אין כאן בחי' זריעה כלל וכלל אחר שאינו סור מרע ועשה טוב בפ\"מ כנ\"ל ולזאת ניתנה העצה בעי\"ת לעורר רחמים רבים על הנפש בי\"ג מדה\"ר שאו' בכל יום כי הנה בכל השנה הוא ע\"י אתעדל\"ת בתפלה ובתחנוני' בצעקה וכמ\"ש ויצעקו<sup data-n=\"5109\">47</sup> אל ה' בצר להם כו' אבל בעי\"ת הי\"ג מדה\"ר נמשכי' מצד אתעדל\"ע בלבד גם בלתי אתעדל\"ת כו' וזהו ויעבור<sup data-n=\"5110\">48</sup> ה' על פניו ויקרא ה' אל רחום וחנון פי' ויעבור מצד עצמו כו' להיות נקרא רחום וחנון ולהיו' נק' ארך אפים ורב חסד כו' וע\"ז נאמר וזרקתי<sup data-n=\"5111\">49</sup> עליכם מים טהורים וטהרתם מכל פשעיכם כו' והטעם הוא לפי שיו\"כ<sup data-n=\"5112\">50</sup> נק' קדוש הוי' מכובד כלומר בחי' קדש העצמי שלמעלה מבחי' קדוש בוי\"ו שאו' המלאכי' כנ\"ל כי נק'<sup data-n=\"5113\">51</sup> שבת שבתון כו' ולכך נק' קדוש הוי' שמובדל ומרומם גם מבחי' הוי' וזהו שאו' לפני<sup data-n=\"5114\">52</sup> הוי' תטהרו לפני וקודם לשם הוי' דהיינו בבחי' קדש העליון עצמו שלמעלה מקדוש ולכך אתעדל\"ע שם מצד עצמו להיות בא ונמשך בי\"ג מדה\"ר עד שנק' ארך אפים כלומר אריכא<sup data-n=\"5115\">53</sup> דאנפין שמתארך להתמשך ולבא עד למטה מטה גם במקום העונות והחטאי' שפגמו האור למטה ולתקן אותם ולמלאת כל חסרון ופגם להיו' נושא עון ועובר על פשע כו' והוא ע\"י זריקת מים טהורים מלמעלה מבחי' קדש העליון שהוא מקור הרחמי' כו' וכמ\"ש במ\"א וד\"ל.",[["5105","43","<b>שהחטא הוא לשון חסרון</b>: ראה ס' שופטים כ, טז. מלכים-א א, כא."],["5106","44","<b>והוא הנק' עון</b>: ראה לקו\"ת מטות פב, א. אוה\"ת ר\"ה ע' א'שפו."],["5107","45","<b>העוה דרכו</b>: ראה ירמי' ג, כא."],["5108","46","<b>לרשע מה לך לספר חוקי</b>: תהלים נ, טז."],["5109","47","<b>ויצעקו אל ה' בצר להם</b>: תהלים קז, ו. כח."],["5110","48","<b>ויעבור ה' על פניו ויקרא</b>: תשא לד, ו."],["5111","49","<b>וזרקתי עליכם מים טהורים</b>: יחזקאל לו, כה."],["5112","50","<b>שיו\"כ נק' קדוש הוי' מכובד</b>: ישעי' נח, יג. ע\"ש בפי' הרד\"ק."],["5113","51","<b>נק' שבת שבתון</b>: אחרי טז, לא. אמור כג, לב."],["5114","52","<b>לפני הוי' תטהרו</b>: אחרי טז, ל."],["5115","53","<b>אריכא דאנפין</b>: ראה זהר במדבר קכח, ב."]]],[2100990333,"<b>ה</b> וזהו כן אד' הוי' יצמיח (ה') צדקה ותהלה נגד כל הגוים. דהנה צדקה<sup data-n=\"5116\">54</sup> הוא בשם אד'<sup data-n=\"5117\">55</sup> והוא בר\"ה<sup data-n=\"5118\">56</sup> שהוא דינא דמלכותא כו' ותהלה הוא ביו\"כ<sup data-n=\"5119\">57</sup> שהוא בשם הוי' בניקוד אלקים כו'. וביאור הדברים הנה תחלה יש להבין שרש ענין מה שאומרי' המלך הקדוש בעי\"ת שלא הי' צריך לאמרו רק בר\"ה בלבד כנ\"ל.\n<b>אך</b> הנה ידוע בשרש ענין ר\"ה<sup data-n=\"5120\">58</sup> שהוא תחלת בנין הנוקבא &lt;שנא&gt;\nדהיינו בחי' מלכו' והיינו ענין אמרו<sup data-n=\"5121\">59</sup> לפניו מלכיות כו' וביאור הדברים הנה ידוע מארז\"ל דבכ\"ה<sup data-n=\"5122\">60</sup> באלול נברא העולם וביום הששי נברא האדם ואמר אותו מזמור שיר שאו' הלוים ביום הו' דהיינו ה'<sup data-n=\"5123\">62</sup> מלך גיאות לבש כו' לפי שבו נמשך להיות בחי' מלך ונתלבש בלבוש גיאות מלך כו' והיינו יום ר\"ה שהוא תחלת עי\"ת להמשיך בחי' מלך והענין הוא למעלה הוא ענין מה שעלה במחשבה הקדומה אנא<sup data-n=\"5124\">63</sup> אמלוך כו' כלומר זהו בחי' הרצון שעלה במחשבה הקדומה של עצמות המאציל להיו' בחי' מלך על עם נפרד ורצון זה להיו' מלך הוא הוא בחי' המקור למציאת התפשטו' מדה זו דמלכות אח\"כ דהיינו להיות בחי' הצמצום ולצמצם ולהסתיר א\"ע כדי שיהא בחי' דבר נפרד להיו' עליו למלך כי באמת כתיב אני<sup data-n=\"5125\">64</sup> הוי' לא שניתי כו' בין<sup data-n=\"5126\">65</sup> קודם שנברא העולם כו' וכולא<sup data-n=\"5127\">66</sup> קמי' כלא כו' וא\"כ אין לך דבר חוץ ממנו ועל מי הוא מולך אלא אנו ממשיכי' תחלה להיו' לו תחלה הרצון למלוך והוא ענין מחשבה הנ\"ל אנא אמלוך כו' בי' פסוקי' דמלכיו' שאו' בר\"ה וכמארז\"ל אמרו לפניו מלכיות כו' ואח\"כ ממילא נעשה בחי' צמצום כדי שיהא בחי' נפרד להיו' מלך על עם ממש אך גם הרצון הזה אנא אמלוך כו' הוא רק בחי' לבוש בעלמא שמתלבש ברצון זה אחר שאין עוד מלבדו איך יתכן בחי' המלוכה וזהו ה' מלך גיאות לבש וכמ\"ש<sup data-n=\"5128\">67</sup> במ\"א וד\"ל.\n<b>וזהו</b> ענין מה שאו' בר\"ה המלך הקדוש כי מלך סתם הוא כל השנה דהיינו מדת מלכותו אשר מתפשטת בעולמו' וכמ\"ש ומלכותו<sup data-n=\"5129\">68</sup> בכל משלה כידוע אבל",[["5116","54","<b>צדקה הוא בשם אד'</b>: ראה זהר אחרי עב, א."],["5117","55","<b>אד'. . דמלכותא</b>: זהר ויקרא יא, א. עקב רעב, ב. תקו\"ז ת\"א קכג, א."],["5118","56","<b>בר\"ה שהוא דינא דמלכותא</b>: ראה מאמרי אדה\"א תקע\"ז ע' שמג ובהנסמן שם בהמ\"מ."],["5119","57","<b>ביו\"כ שהוא בשם הוי' בניקוד אלקים</b>: וראה מ\"ח מס' יומא ג, א. פע\"ח שער יוהכ\"פ פ\"ב ד\"ה מהחברים."],["5120","58","<b>ר\"ה. . בנין. . בחי' מלכו'</b>: ראה פע\"ח שער (כד) ר\"ה פ\"א ואילך."],["5121","59","<b>אמרו לפניו מלכיות</b>: ראה ר\"ה טז, א. לד, ב."],["5122","60","<b>דבכ\"ה באלול נברא העולם</b>: ויק\"ר רפכ\"ט. פדר\"א פ\"ח. פסיקתא דרב כהנא פסקא כג בחודש השביעי. ראה ר\"ן ר\"ה טז, א. רבינו בחיי בראשית א, ג ד\"ה ויש [ירושלים תשל\"א ע' כו].\n61 האדם ואמר. . שיר שאו' הלוים ביום הו': ראה פדר\"א פי\"א."],["5123","62","<b>ה' מלך גיאות לבש</b>: תהלים צג, א."],["5124","63","<b>אנא אמלוך</b>: ראה לקו\"ת נשא כא, ד. ובהנסמן שם בהמ\"מ."],["5125","64","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["5126","65","<b>בין קודם שנברא העולם</b>: ראה פדר\"א פ\"ג."],["5127","66","<b>וכולא קמי' כלא</b>: זח\"א יא, ב."],["5128","67","<b>וכמ\"ש במ\"א</b>: ראה לקו\"ת נשא כ, ד. כא, ד. נצבים נא, ב. וראה המשך תער\"ב ע' קפא. ע' תשצט."],["5129","68","<b>ומלכותו בכל משלה</b>: תהלים קג, יח."]]],[2100990334,"המלך הקדוש<sup data-n=\"5130\">69</sup> לשון מובדל הוא תחלת מקור מדת המלוכה<sup data-n=\"5131\">70</sup> דהיינו בחי' תחלת עליית המחשבה אנא אמלוך שנק' מלך הקדוש שעדיין מובדל ומרומם הוא מהיות מלך על עם נפרד אחר שאין עוד מלבדו אלא רק שעלה ברצונו להיו' מלך כו' וכנ\"ל ומה שנק' קדוש בוי\"ו הענין הוא כמו שנא' קדוש<sup data-n=\"5132\">71</sup> יהי' גדל כו' שהוי\"ו<sup data-n=\"5133\">72</sup> הזה מורה בחי' ההמשכה מבחי' קדש העליון עצמו דהיינו אור המאציל עצמו והרצון הנמשך מאתו להיו' מלך נק' קדוש כו' וד\"ל. ואמנם הנה התעוררו' זאת להיו' לו הרצון למלוכה בר\"ה הוא מצד עצמו כדי שיתוודע לנבראי' בו משא\"כ בכל השנה כנ\"ל (ע\"י אתעדל\"ת) והיינו שאו' המלך הקדוש בעי\"ת גם אחר ר\"ה כי כל הימים הללו ממשיכי' בכל יום מעצמו' המאציל רצון למלוכה עד יו\"כ בנעילה שאז עולה המל' עד הכתר עצמו שנק' רעוא<sup data-n=\"5134\">73</sup> דכל רעוין כו' ואז אומרי' ויעבור ה' על פניו ויקרא ופי' ויעבור מעצמותו להיו' רחום וחנון כו' כמו העובר מעולם לעולם שלמטה הימנו וד\"ל.\n<b>ו</b> וזהו כן אד' הוי' יצמיח צדקה ותהלה כו' פי' אד' הוא בחי' ר\"ה שנק' דינא דמלכותא כי בו תחלת בנין מדת המלכו' כנ\"ל והוא שם אד' כמאמר אנת<sup data-n=\"5135\">74</sup> אשתמודע אדון על כולא כו' וד\"ל והיינו ענין צדקה<sup data-n=\"5136\">75</sup> צדק ה\"א כי צדק<sup data-n=\"5137\">76</sup> איהו דין דינא דמלכותא והה\"א הוא בחי' החסדי' שבמל' להחיו'<sup data-n=\"5138\">77</sup> רוח שפלים עד\"מ הצדקה הגשמית שנתנית לעני דלית לי' מגרמי' כלום כו' כך למעלה כתיב צדיק<sup data-n=\"5139\">78</sup> ה' בכל דרכיו וכן צדיק<sup data-n=\"5140\">79</sup> ה' צדקו' אהב כו' כי הנה &lt;שנב&gt;\nבר\"ה<sup data-n=\"5141\">80</sup> אדם נידן גם בנפשו האלקי' איך וכמה תקבל אור ושפע אלקי' בתורה ועבודה כל השנה הבאה וז\"ש כי<sup data-n=\"5142\">81</sup> חק לישראל הוא משפט לאלקי יעקב פי' המשפט והדין הוא איך וכמה יתפשט אור אלקי ביעקב בכאו\"א לפום שיעורא דילי' כמ\"ש נודע<sup data-n=\"5143\">82</sup> בשערים בעלה כו' כידוע ואופן הדין והמשפט הזה תלוי במעשיו של אדם של שנה שעברה לפי מה שהמשיך בשנה שעברה גילוי אלקו' בתורתו ועבודתו כך לפי ערך ישפטו לו גילוי אור אלקי בשנה הבאה כו' אך מ\"מ אע\"פ שבדינא דמלכותא ישפטו בחי' צדקה וחסד הוא להיו' נמשך גילוי אלקו' בכאו\"א לפום שיעורא דילי' כי כמו צדקה הגשמי' לעני כו' וזהו צדיק ה' בכל דרכיו בכאו\"א מן הנבראי' שבכל ההשתלשלו' וצדיק ה' צדקו' אהב הוא הנק' בעל צדקה וזהו כמשל הנותן השפע לעני וההשפעה עצמה נק' צדקה והוא שם",[["5130","69","<b>הקדוש לשון מובדל</b>: ראה תניא פמ\"ו."],["5131","70","<b>המלוכה. . מלך על עם נפרד</b>: ראה שער היחוד והאמונה רפ\"ז."],["5132","71","<b>קדוש יהי' גדל</b>: במדבר ו, ה."],["5133","72","<b>שהוי\"ו הזה מורה בחי' ההמשכה</b>: ראה אגה\"ת פ\"ד."],["5134","73","<b>רעוא דכל רעוין</b>: ראה זהר (ספרא דצניעותא) תרומה קעו, ב. תו\"ח בראשית לו, ג. ובהערה 1."],["5135","74","<b>אנת אשתמודע אדון על כולא</b>: ת\"ז בהקדמה (יז, ב)."],["5136","75","<b>צדקה צדק ה\"א</b>: ראה זהר אחרי עב, א."],["5137","76","<b>צדק איהו דין</b>: ראה ת\"ז בהקדמה (יז, א) וראה ביהל אור ע' קלד ואילך."],["5138","77","<b>להחיו' רוח שפלים</b>: ישעי' נז, טו."],["5139","78","<b>צדיק ה' בכל דרכיו</b>: תהלים קמה, יז."],["5140","79","<b>צדיק ה' צדקו' אהב</b>: תהלים יא, ז."],["5141","80","<b>בר\"ה אדם נידון גם בנפשו האלקי'</b>: ראה לקו\"ת דרושי ר\"ה נט, ב."],["5142","81","<b>כי חק לישראל הוא משפט לאלקי יעקב</b>: תהלים פא, ה."],["5143","82","<b>נודע בשערים בעלה</b>: משלי לא, כג."]]],[2100990335,"אד' שנמשך לכאו\"א ע\"י מדה זו בר\"ה על כל השנה וזהו כן שם אד' כו' יצמיח צדקה והוא בר\"ה מטעם הנ\"ל וד\"ל.\n<b>ופי'</b> תהלה<sup data-n=\"5144\">83</sup> הוא ביו\"כ והוא ע\"י שם הוי' בניקוד אלקי' כנ\"ל וביאור הדברי' הנה פי' תהלה<sup data-n=\"5145\">84</sup> לשון הילול ע\"ד הפשוט וגם לשון בהירות אור כמו בהלו<sup data-n=\"5146\">85</sup> נרו כו' וכמו יהילו<sup data-n=\"5147\">86</sup> אורם כו' ושניהם ענין א' הוא כי ההארה האלקי' שמאיר על נפש האדם ע\"י התהלה בפסוקי דזמרה בשבחים בזה האור נדחה החושך דקליפות המסתירים וכמ\"ש כהמס<sup data-n=\"5148\">87</sup> דונג מפני אש יאבדו רשעי' כו' ולכך נקראו בשם פסוקי<sup data-n=\"5149\">88</sup> דזמרה ע\"ש הכריתה שנכרתו ונזמרו החיצוני' עי\"ז וזהו פי' רוממו'<sup data-n=\"5150\">89</sup> אל בגרונם בתהלה ואז עי\"ז חרב פיפיו' בידם לעשו' נקמה בגוים להרוג יניקו' החיצונים ועד\"מ המלחמה שא\"א לנצח כ\"א בכלי זיין בחרב וחנית כו' והתהלה היא חרב פיפיו' כו' כי הרי ידוע בזוהר<sup data-n=\"5151\">90</sup> דשעת צלותא שעת קרבא כו' וע\"כ תהלה זו היא בהוי' בניקוד אלקים להיו' כי בחי' הדין דאלקי' הוא מעביר החושך דחיצוני' והאור הנגלה הרי הוא העיקר הדוחה החושך והיינו שם הוי' שיש בתהלה מלשון בהלו נרו וגם הוא בניקוד דשם אלקים כדי להעביר רוח הטומא' וד\"ל.\n<b>וכך</b> הוא הענין ביו\"כ שצריך להעביר<sup data-n=\"5152\">91</sup> רוח הטומא' להפוך זדונות כזכיו' להיו' מוחל וסולח לעוונות וחטאי' שבאים מסטרא דקליפה כו' וכדי לאהפכא<sup data-n=\"5153\">92</sup> חשוכא לנהורא צריך להאיר אור אלקי ממקורא דכולא שהוא בחי' כתר שנק' רעוא דכל רעוין בהארת י\"ג מדה\"ר בנעילה דיו\"כ באמרם ויעבור ה' על פניו ויקרא ה' אל רחום כו' ואו' ז\"פ<sup data-n=\"5154\">93</sup> כי הוי' הוא האלקי' כו' והוא ענין התהלה הנ\"ל שהיא בשם הוי' בניקוד שם אלקי' כדי לאהפכא חשוכא לנהורא כי האור הוא דוחה את החושך וזהו ותהלה נגד כל הגוים דוקא נגד כל הגוים צריך בחי' תהלה כי ע\"י בחי' גילוי אור אלקי ממילא יתבטלו כל הגוים כנ\"ל וד\"ל.\n<b>ומה</b> שאמר נגד כל הגוים לשון רבים היינו כמו שאמר לעשו'<sup data-n=\"5155\">94</sup> נקמה בגוים כו' ע\"י התהלה כנ\"ל והכלל הוא רק שני גוים עשו<sup data-n=\"5156\">95</sup> וישמעאל ישמעאל שהוא",[["5144","83","<b>תהלה הוא ביו\"כ. . שם הוי' בניקוד אלקי'</b>: ראה מאמרי אדה\"א הנחות תקע\"ז ע' שדמ."],["5145","84","<b>תהלה לשון הילול</b>: ראה ביהל אור ע' תרסח וע' תקלז."],["5146","85","<b>בהלו נרו</b>: איוב כט, ג."],["5147","86","<b>יהילו אורם</b>: ישעי' יג, י."],["5148","87","<b>כהמס דונג מפני אש</b>: תהלים סח, ג."],["5149","88","<b>פסוקי דזמרה ע\"ש הכריתה</b>: ישעי' כה, ה. ראה זהר וילך רפד, א. לקו\"ת בחוקותי מז, ד. נצבים נא, ד."],["5150","89","<b>רוממות אל בגרונם. . לעשו' נקמה בגוים</b>: תהלים קמט, ו. ז."],["5151","90","<b>בזוהר דשעת צלותא שעת קרבא</b>: ראה זח\"ג רמג, א. וראה לקו\"ת ר\"פ תצא לד, ג. לה, ג."],["5152","91","<b>להעביר רוח הטומא'</b>: לשון הפסוק זכרי' יג, ב."],["5153","92","<b>לאהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["5154","93","<b>ז\"פ כי הוי' הוא האלקי'</b>: תפלת נעילה. ראה סה\"מ תקס\"ה ח\"ב ע' תתקצו. תו\"ח שמות מח, ג. ועוד."],["5155","94","<b>לעשות נקמה בגוים</b>: תהלים קמט, ז."],["5156","95","<b>עשו וישמעאל. . חסד דקליפ'</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תקלח. נביאים ע' צד. לקו\"ש ח\"כ ע' 102 בהערות."]]],[2100990336,"מבחי' חסד דקליפ' הוא בחי' הקרירות לבטל כל מ\"ע שגורמת המניעה מן היגיעה בועשה טוב ועשו שהוא מבחי' גבור' דקליפ' הוא בחי' החמימות לגרום תאו' איסור &lt;שנג&gt;\nבשס\"ה ל\"ת כו' ופרטי הגוים מהם מסתעפים ולכך אמר נגד כל הגוים לכלול הכל כא' שנכרתו ע\"י בחי' התהלה מטעם הנ\"ל וד\"ל, ואחר כל הנ\"ל יובן המשך פשט הפסוק כך כי כארץ תוציא צמחה מצד אתעדל\"ת כל השנה כך יצמיח שם אד' בר\"ה ותהלה ביו\"כ מצד עצמו כו' אך הצמיחה הזאת בר\"ה ויו\"כ הוא ע\"י הזריעה בתחלה מבחי' מלך וכמ\"ש מלך<sup data-n=\"5157\">96</sup> לשדה נעבד וכמ\"ש בזוהר וכמבואר לי\"ח וד\"ל.",[["5157","96","<b>מלך לשדה נעבד וכמ\"ש בזוהר</b>: קהלת ה, ח. זהר ח\"א קכב, ב."]]],[2100990337,"<h3>קיצורים לד\"ה כי כארץ</h3>\n<b></b><b>[קיצורים<sup data-n=\"5158\">1</sup> לד\"ה כי כארץ תוציא צמחה]</b>\n<b>כל</b> הנביאים לא נתנבאו על שכר הרוחני דמצות עין לא ראתה (ע' מזה בלח\"מ סוף ה' תשו') מ\"מ בעבודה ישנו ומתגלה בר\"ה ויוכ\"פ וזהו יצמיח כו', ענין המלך הקדוש בעשי\"ת וגם שייכו' המלך ובחי' קדוש ובברכת אתה, הנה מלאכי' נמשכי' מדיבור הבל הפה עיקרו מהגוף ונעשה נפרד משא\"כ נש\"י ממח' בחי' התפשטו' השכל ולא גופני ואינו נפרד לכן קדמו לשי\"ב.\nב. <b>ירידת</b> הנשמו' ממח' צורך עלי' לבחי' שלמעלה ממח' קדוש ומ\"מ יכול כמוני כו' והענין כי מלאכי' או' ג\"פ קדוש בוי\"ו המשכה מקדש למח' מדו' ודיבור שיהי' צבאות, וישראל ואנשי קדש תהיון (ע' בהעלותך<sup data-n=\"5159\">2</sup> תקס\"ב ומתחלה כי עם קדוש אתה) ע\"י המצות אקב\"ו ולכן יאמרו לפניהם קדוש, וזהו והייתם קדושי' ע\"י המצות לאלקיכ' צרור החיי' וברכת המצות להמשיך גלוי מבחי' קדושה זו ע\"י מלך העולם קעמ\"ש עובר לעשייתן כו' שיוכל להתלבש בעשיי' גשמיות כו', יכול כמוני כו'.\nג. <b>וזהו</b> כארץ תוציא צמח', המצוה עשיי' גשמיו' כנ\"ל ומעוררת קדש העליון (ע'<sup data-n=\"5160\">3</sup> כדכד ושבת<sup data-n=\"5161\">4</sup> שבתון היא לכם תק\"ע) כמו צמחי' ע\"י גרעין עיקרה מכח הצומח שבארץ וזריע' הגרעין משום דלית<sup data-n=\"5162\">5</sup> ברכתא שריא באתר רקני', וענין כח",[["5158","1","<b>קיצורים</b>: מכ\"ק אדמו\"ר הצ\"צ. נעתק מגוכתי\"ק 1025 (קסא, ב). בלקו\"ת נצבים נ, ב נדפס קיצורים על נוסח הלקו\"ת.\nקיצורים אלו נכתבו בשנת תקצ\"א (נמצא בכת\"י 611 רב, א בכותרת: בע\"ה, פ' נצבים תקצ\"א). נדפס ג\"כ באוה\"ת נצבים כרך ו' ע' ב'תכד."],["5159","2","<b>בהעלותך תקס\"ב</b>: לקו\"ת בהעלותך ל, סע\"ג ואילך."],["5160","3","<b>ע' כדכד. . תק\"ע</b>: לקו\"ת ראה כז, ב."],["5161","4","<b>ושבת שבתון היא לכם תק\"ע</b>: לקו\"ת דרושים ליוה\"כ סט, ג. והנחת כ\"ק אדמו\"ר האמצעי בסה\"מ תק\"ע ע' קנא. ע' קסג."],["5162","5","<b>דלית ברכתא שריא באתר ריקני'</b>: ראה זהר ויחי רטז, ב. יתרו פז, ב. תרומה קנה, א. קנז, ב. צו לד, א."]]],[2100990338,"הצומח שבארץ עליונה בחי' כתר תענוג עליון לכן כדאי כל יסורי כו' (וזהו אשר קדשנו ע'<sup data-n=\"5163\">6</sup> שלח תק\"ע הנ\"ל) ומזה<sup data-n=\"5164\">7</sup> אמרו עין לא ראתה כו' (ע'<sup data-n=\"5165\">8</sup> ואתחנן תקס\"ד נת'<sup data-n=\"5166\">9</sup> תקפ\"ח). אולי<sup data-n=\"5167\">10</sup> י\"ל ארץ בחי' גנתא שלמטה מג\"ע זרועיה ב' משמע שמעשה המצוה בגעה\"ת וכוונה לדבקה בו ע\"י מ\"ע ושלא ליפרד ע\"י ל\"ת בגה\"ע (ע' כי<sup data-n=\"5168\">11</sup> תבואו כו' פ' בהר סיני תקס\"ב) עוד יש בחי' ג' והוא כארץ תוציא צמח' מעצמה וכענין ספיחי' אז הפרי אין משובח כגינה שזורעי' כו' וזהו מבחי' מצות אנשי' מלומדה (נ\"ל ביאור זה כי גינה תוציא צמחי' ע\"י מ\"ד הנמשך ע\"י מעשה המצות ע' ד\"ה<sup data-n=\"5169\">12</sup> ע' בע\"ח שמ\"ט כו' והארץ ג\"כ ע\"י מ\"ד רק שהוא בחי' ספיחי' רוחא דשדי כו' כי בזמן הגלו' אין יחוד אמיתי דמ\"ד<sup data-n=\"5170\">13</sup> לפי שאין ג\"כ מ\"ן אמיתי כו', ואז ג\"כ נש\"י נמשלי' לעיבור בוארא<sup data-n=\"5171\">14</sup> תקס\"ב שהוא בחי' מצות אנשי' מלומדה עיניו השע כו' ותומ\"צ ג\"כ רק אוכל ממה שאמו כו' דרך הטבור בלי טעם זהו צמח' דארץ שאין בו טעם כ\"כ, ומ\"מ יש בהם אהבה מסותרת בחי' ספיחי' לכן מעורר כן למעלה, אבל כשהוא בכוונה ממש מ\"ד ומ\"ן מעורר כן למעלה), וכל צמיח' הנ\"ל כח הצומח מבחי' קדש כתר וזהו העלי' לאחר הירידה.\nד. <b>אך</b> כ\"ז כשהאדם סומע\"ט זריע' הנ\"ל (והל\"ת ג\"כ נק' זריעה כמ\"ש בארץ לא זרועה) אבל כשחוטא ח\"ו ליכא זריעה כו' וכ\"ש ל\"ת עון העוה דרכו (ע' בישעי' שירת דודי לכרמו כו'), ע\"כ אין עצה רק לעורר רח\"ר בעשי\"ת כי אז ויעבור מעצמו ובכל השנה ע\"י אתעדל\"ת, וזרקתי, קדוש ה' מובדל מבחי' הוי' לפני הוי' תטהרו קדש שלמעלה מקדש (צ\"ע על\"ק) ארך אפים להתמשך למטה (כמ\"ש בועתה<sup data-n=\"5172\">15</sup> יגדל נא כח כו' תקס\"ו, ונ' המצות מבחי' קדש, ולתקן צ\"ל מבחי' גבוה יותר היינו קדושתי למעלה מקדושתכם, וגילוי זה בעשי\"ת המלך הקדוש, ובכל השנה ע\"י מצות בא\"י מלך כו' קדשנו כו', מלך סתם אבל עכשיו הקדוש<sup data-n=\"5173\">16</sup>.\nה. <b>וזהו</b> כן כו' צדקה ותהלה ר\"ה ויוכ\"פ, כי ר\"ה ביו' ו' שהוא בריאת אדה\"ר גלוי מלוכה לכן השיר גאות לבש ונמשך בחי' אנא אמלוך במחה\"ק שהרי באמת אין על מי למלוך כו' (ע'<sup data-n=\"5174\">17</sup> ואולם חי אני ענין בכה\"מ) ובר\"ה אמרו שתמליכוני כו'",[["5163","6","<b>ע' שלח תק\"ע</b>: לקו\"ת שלח, מו, ד. ובסה\"מ תק\"ע ע' קיח."],["5164","7","<b>ומזה אמרו</b>: ברכות לה, ב."],["5165","8","<b>ע' ואתחנן תקס\"ד</b>: לקו\"ת ר\"פ ואתחנן. והנחת כ\"ק אדמו\"ר האמצעי בסה\"מ תקס\"ד ע' קצו. אוה\"ת ואתחנן ע' מה."],["5166","9","<b>נת' תקפ\"ח</b>: השוה ג\"כ אוה\"ת קרח — בהוספות ע' 132: בואתחנן (דתקס\"ד שביארתי)."],["5167","10","<b>אולי י\"ל. . מג\"ע</b>: נרשם בצד הגליון כאן. ואולי מקומו כאן."],["5168","11","<b>כי תבואו. . תקס\"ב</b>: סה\"מ תקס\"ב ע' קפה, והביאור ע' קפח. ובתוס' הערות וכו' בדרך מצותיך ע' קסז, והביאור ע' קסט. והנחה אחרת [הר\"מ בן כ\"ק אדמו\"ר הזקן ] בסה\"מ תקס\"ב ע' תלב."],["5169","12","<b>ד\"ה ע' בע\"ח שמ\"ט</b>: תו\"א חיי שרה טז, ג. בתו\"א הד\"ה עיין ע\"ח. אבל בהוספות לתו\"א [קה\"ת] שם ע' טז [קמ], ג בע\"ח כבפנים."],["5170","13","<b>דמ\"ד. . כי</b>: נכתב ממעל לשורה."],["5171","14","<b>בוארא תקס\"ב</b>: תו\"א וארא נה, א. והנחת כ\"ק אדמו\"ר האמצעי בסה\"מ תקס\"ב ע' קלד."],["5172","15","<b>בועתה יגדל נא</b>: לקו\"ת שלח לט, ב והנחת כ\"ק אדמו\"ר האמצעי לעיל ע'"],["5173","16","<b>הקדוש</b>: אוצ\"ל הקדוש)."],["5174","17","<b>ע' ואולם חי אני</b>: סה\"מ תקס\"ט ע' קפה."]]],[2100990339,"(בפנים כ' ממילא וצ\"ע ועמשל\"ק<sup data-n=\"5175\">18</sup> לכן אז כל עשי\"ת המלך הקדוש שבחי' מלך זה קדוש ומובדל במחשב' אנא אמלוך כו' (ע' בסידור<sup data-n=\"5176\">19</sup> בנעילה מענין המלך הק'<sup data-n=\"5177\">20</sup>.\nו. <b>וזהו</b> כן אד' בחי' שם זה במל' דינא דמלכותא (בחי' המלך הק' לכאורה הוא בחי' אד' מי הנז'<sup data-n=\"5178\">21</sup> בועתה יגדל דתקס\"ו ויצמיח צדקה כמש\"ש שיגדל כח אד' להיו' נושא עון כו') ויצמיח צדקה בחי' מל' צדק ה' גבו' וחסדי' דמל' להשפיע לכל א' וגם משפט כמה יהי' הגילוי ומ\"מ נק' ג\"כ צדקה (אולי ע\"ד לך אד' החסד כו' כמעשהו, וצ\"ל אד' מל' צדקה מל' א\"כ איך אד' יצמיח צדקה ואולי אד' השם הוא אלקו' שבמל' או אד' מי כנז'.\nז.<sup data-n=\"5179\">22</sup> <b>ותהלה</b> ביוכ\"פ שם ה' בניקוד א' חו\"ג, כי תהלה וגלוי זהו זמור לעריצי' מעט אור דוח', וכן ביוכ\"פ גלוי כתר לכן אז מהפך הרע, וזהו נגד כו' (ועמ\"ש ע\"פ הזהר בהעלותך בנו\"ן נורא תהלות כו' ע\"ש הטיב דשייך לכאן) ישמ' וע' ע' שערי אורה להר\"י גי' וצמיח' זו ממילא אך צ\"ל זריע' מלך לשדה נעבד.\n<b>(ונ\"ל</b><sup data-n=\"5180\">23</sup> דנת' ע\"פ<sup data-n=\"5181\">24</sup> שבת שבתון הו\"א שיש חילוק אם היוכ\"פ ע\"י אתעדל\"ת נמשך ממקום גבוה יותר עד שמכפר על הקדש ואי ליכא אתעדל\"ת מ\"מ יוכ\"פ הוא ומכפר על מקדש הקדש, לכן י\"ל גם כאן אד' אלקי' יצמיח כו' ודאי בר\"ה ויוכ\"פ צדקה ותהלה ע' ע\"פ<sup data-n=\"5182\">25</sup> ויקרא משה כו' עיני' לראו' עד היום הזה פ' תבא שאז נמשך דו\"ר עילאין מלמעלה חשף ד' כו' התהללו וכו' אך מ\"מ כשיש אתעדל\"ת היינו הכנה נמשך ממקום גבוה יותר, וזהו כי כארץ כגנה שבמצות ב' בחי' שונו' צמיח' דגנה שע\"י אתעדל\"ת וצמיח' דארץ ספיחי', כמ\"כ בענין ר\"ה ויוכ\"פ צמיח' דקדושתי יש ב' בחי' שע\"י הכנה עדיף ונמשך ממקום גבוה כו'. יובן שאמר ב' משלי' כארץ וכגנה ולא די במשל א' אלא כי באמת הן ב' בחי' בנמשל ובמשל.\n<b>צריך</b> לעיין בלך<sup data-n=\"5183\">26</sup> ה' הצדקה, לאזני, וי\"ל דאי' ויעש דוד שם מאן דיהיב צדקה כו' עי\"ז עושה שם א\"כ אנו ממשיכי' צדקה אך בר\"ה יצמיח אד' צדקה היותר גבוה בחי' וצדקה תהי' לנו כי נשמור כו' שאחר כל המצו' יומשך לנו צדקה הנ\"ל דלך הצדקה מל' דא\"ס, אד' שפתי תפתח בחי' אד' יצמיח צדקה ופי יגיד תהלתך בחי' תהלה התהללו וכו'.\n<b>ע'</b> תורה בחקתי תקס\"ח ע\"פ<sup data-n=\"5184\">27</sup> רפאני כו' כי תהלתי אתה.",[["5175","18","<b>ועמשל\"ק</b>: אוצ\"ל ועמשל\"ק)."],["5176","19","<b>בסידור בנעילה</b>: ראה שער יום הכפורים רנ, ד."],["5177","20","<b>הק'</b>: אוצ\"ל הק')."],["5178","21","<b>הנז'</b>: אוצ\"ל כנז')."],["5179","22","<b>ז)</b>: סעיף זה מתחיל לעיל ע' תרצג בשורה המתחלת ”פירוש\"."],["5180","23","<b>(ונ\"ל</b>: בגוכי\"ק לא נסמן סיום החצע\"ג."],["5181","24","<b>ע\"פ שבת שבתון</b>: דתק\"ע הנ\"ל."],["5182","25","<b>ע\"פ ויקרא משה</b>: [תקנ\"ו — ז. ראה רשימת הכתבי-יד בלקו\"ת — (קה\"ת — תשד\"מ) קלח, ד]. תבא מג, סע\"ד."],["5183","26","<b>בלך ה' הצדקה, לאזני</b>: אתהלך לאזניא ע' ר."],["5184","27","<b>ע\"פ רפאני</b>: סה\"מ תקס\"ח ע' רטו."]]],[2100990340,"<h3>להבין שרש הדברים</h3>\n<b>בעזר\"ה</b>\n<b>להבין</b><sup data-n=\"5185\">1</sup> שרש הדברים הנ\"ל. הנה תחלה יש להבין כללות ענין ר\"ה ויו\"כ שהוא זמן התיקון לתקן פגם העונות וחטאים ולמלאת<sup data-n=\"5186\">2</sup> כל חסרון ופגם שע\"י החטא שעל ידם נעשה כל השנה הסתלקו' אור הקדוש' כו' ובעי\"ת חוזרין אור השרא' הקדוש' במה שאומרי' המלך<sup data-n=\"5187\">3</sup> הקדוש כו' ולהבין ענין התיקון הזה איך הוא הנה יובן עד\"מ כאשר בית אחד נתקלקל בו באמצעו או בסופו באיזו מקום שיהי' הנה ודאי א\"א לתקן אותו הקלקול אם לא שיחזור ויבנו מחדש כל הבית מיסודו עד גגו שבהתחדשו' הבנין יכולי' לתקן ולעשות קיום חזק באותו מקום המקולקל והנמשל יובן מזה בהיות ידוע שפגם העונות והחטאי' עשו חסרון וקלקול למעלה גם באורו' וכלים דאצי' כי הנה ידוע די\"ס דאצי' נמשכין ומתלבשין בג' מיני כלים פנימיים ואמצעיי' וחיצונים וי' כלים הפנימיי' מתלבשי' בבריא' והאמצעיי' ביצי' והחיצוני' בעשי' ונעשי' בבי\"ע נר\"נ כידוע וא\"כ גם מי שיש לו נפש דעשי' מגיע הפגם מעונו גם באצי' בי' כלים החיצוני' וידוע דהכלים נק' איברי' עד\"מ וזהו שאמרו בזוהר<sup data-n=\"5188\">4</sup> הפושעים בי בי ממש בגופא דמלכא שהן בחי' האורו' שמלובשי' בכלים כו' וד\"ל ויש ב' מיני פגם א' פגם החטא שעושה רק חסרון (שהוא עד\"מ הסתלקו' והעדר הרגשת החיות באיזה אבר שאינו אלא מפני קלקול הדמים באותו אבר) והיינו למעלה ע\"י ביטול מ\"ע כמ\"ש למעלה ויש פגם יותר קשה והוא העון<sup data-n=\"5189\">5</sup> מלשון העוה דרכו כו' ע\"י ל\"ת (שהוא קלקול הדמים כ\"כ עד שנעשה באבר כמו צרעת ונגע ונק' נגעי בני אדם) שמהם מקבלים החיצונים יניקה גדולה כמבואר בזוהר וע\"ח<sup data-n=\"5190\">6</sup> בענין הנגעים וע\"כ נק' עון שנעשה דרך עקלתון ומעוה לחיצוני' כו' וד\"ל.\n<b>אך</b> העצה לתיקון העונות והחטאים הוא עד\"מ לבנות הבנין מחדש כנ\"ל שאז יוכלו לתקן מקום המקולקל כך למעלה זהו כל עיקר ענין ר\"ה להיות שבר\"ה<sup data-n=\"5191\">7</sup> אנו או' זה היום תחלת מעשיך שנבנה<sup data-n=\"5192\">8</sup> בנין הנוקבא דאצי' מחדש כמו שנאצלה מתחלת האצי' בבחי' נסירה כו' וכידוע וכן למעלה מעלה עד רום המעלו' הכל נבנה מחדש לחדש כל ההשתלשלו' מעצמות המאציל וע\"כ יכולי' אז לעשות בחי' תיקון לפגם",[["5185","1","<b>להבין שרש הדברים</b>: הנחת כ\"ק אדמו\"ר האמעצי. נעתק מגוכתי\"ק 1025 (קב, ב). נמצא ג\"כ בכת\"י 611 פט, ב (וחסר סיום).\nנדפס בשינויים והשמטות ותוס' הגהות (משנת תקצ\"א) באוה\"ת דברים כרך ו ע' ב'תטז. ועם הגהות נוספות בלקו\"ת נצבים נב, א."],["5186","2","<b>ולמלאת כל חסרון. . המלך הקדוש כו'</b>: בלקו\"ת שם: וכמארז\"ל [ר\"ה יח, א] ע\"פ דרשו ה' בהמצאו אלו עשרה ימים שבין ראש השנה ליוהכ\"פ. ומפורש בתורה כי ביום הזה יכפר."],["5187","3","<b>המלך הקדוש</b>: ברכות יב, ב. שו\"ע אדה\"ז הל' ר\"ה סתקפ\"ב ס\"א-ב."],["5188","4","<b>הפושעים בי</b>: ישעי' סו, כד. וראה אוה\"ת ואתחנן ע' שב ואילך."],["5189","5","<b>העון מלשון העוה דרכו</b>: ראה ירמי' ג, כא — העוו את דרכם."],["5190","6","<b>וע\"ח בענין הנגעים</b>: ראה ע\"ח של\"ח ש' לאה ורחל פ\"ז. וראה לקו\"ת מצורע כד, ד ואילך."],["5191","7","<b>שבר\"ה אנו או' זה היום תחלת מעשיך</b>: תפלת מוסף."],["5192","8","<b>שנבנה בנין הנוקבא דאצי' מחדש</b>: ראה ביאוה\"ז להצ\"צ כרך א ע' שצו ובמ\"מ לשם."]]],[2100990341,"העונות והחטאי' כי הגם שעשו כבר פגם באורו' וכלים דאבי\"ע אבל &lt;שנד&gt;\nבחידוש האור מעצמו' המאציל באבי\"ע מחדש יתוקן כל פגם ויתמלא כל חסרון וזהו ענין טעם סליחת ומחילת העונות בר\"ה ויו\"כ והיינו שאומרי' המלך הקדוש בעי\"ת להחזיר אור הקדוש' מחדש אע\"פ שכבר נסתלקו ע\"י החטא ימשיכוה מחדש וד\"ל.\n<b>ועתה</b> יש להבין שרש ענין ישראל<sup data-n=\"5193\">9</sup> עלה במחשבה הנ\"ל ומה שאמר קדושי'<sup data-n=\"5194\">10</sup> תהיו יכול כמוני וכו'. דהנה שרש נשמו' ישראל נמשך מבחי' מוח דאבא דאצי' שהרי נק' בנים וכמ\"ש בני<sup data-n=\"5195\">11</sup> בכורי ישראל והבן<sup data-n=\"5196\">12</sup> נמשך מטיפה הרוחניו' שבמוח האב וכמאמר הידוע כי האב<sup data-n=\"5197\">13</sup> מזריע הלובן כו' וזהו בראשית<sup data-n=\"5198\">14</sup> בשביל ישראל שנקרא ראשית כי הם נמשכו מבחי' מוח החכמה שנק' ראשית כידוע וד\"ל.\n<b>ובזה</b> יובן ג\"כ מה שאמר הקדב\"ה שתוק<sup data-n=\"5199\">15</sup> כך עלה במחשבה לפני כי ר\"ע שרש נשמתו מבחי' אור החכמה דאצי' וכמבואר בע\"ח<sup data-n=\"5200\">16</sup> בשרש ענין י' הרוגי מלוכה שהי' בשביל להעלו' מ\"ן לאו\"א כי גלוי וידוע הי' לפני המאציל אריכות גלות בית שני והענין של הגלות ידוע שהוא רק כדי לברר ברורי' דרפ\"ח ניצוצ' שבע' שרים כענין גלו<sup data-n=\"5201\">17</sup> לאדום שכינה עמהם שהוא שם ב\"ן המברר כו' ואין הבירור אלא בחכמה כמאמר בחכמה<sup data-n=\"5202\">18</sup> אתברירו דוקא ואמנם גלוי וידוע הי' לפניו שאין כח בחכמה דכנ\"י בגלות לברר כל הברורי' דרפ\"ח כו' והיו צריכי' להשתקע שם זמן ארוך מאד ע\"כ הקדים עצה טובה בי' הרוגי מלוכה שהיו מבחי' החכמה דוקא שבמס\"נ שלהם הם ביררו מרפ\"ח כו' כל מה שהי' צריך להתברר ע\"י כנ\"י כי הרי נשמתם עלו במס\"נ לאור חכמה העליונה הנק' מחשבה עילא' סתימאה כו' ושם הי' עי\"ז הבירור היותר גדול מכל מה שעתיד להתברר ע\"י חכמה שבכאו\"א מישראל בגלות ולא עוד אלא שבכל דור ובכל זמן לא יש כח לחכמה שבכנ\"י לברר בגלות כ\"א ע\"י כח החכמה עילא' לפי שי' הרוגי מלוכה שמסרו נפשם לחכמה עילא' המה הנותנים כח ועוז תמיד לברר למטה בחכמה כמ\"ש בע\"ח<sup data-n=\"5203\">19</sup> ע\"פ א\"ל נקמות ה' כו' ע\"ש.",[["5193","9","<b>ישראל עלה במחשבה</b>: ראה ב\"ר פ\"א, ד."],["5194","10","<b>קדושים תהיו יכול כמוני</b>: קדושים יט, ב. ויקרא רבא פכ\"ד, ט."],["5195","11","<b>בני בכורי ישראל</b>: שמות ד, כב."],["5196","12","<b>והבן נמשך. . שבמוח האב</b>: ראה תניא פ\"ב, פי\"ח."],["5197","13","<b>האב מזריע הלובן</b>: ראה נדה לא, א."],["5198","14","<b>בראשית בשביל ישראל שנק' ראשית</b>: בראשית א, א. רש\"י בראשית שם."],["5199","15","<b>שתוק כך עלה במחשבה</b>: מנחות כט, ב."],["5200","16","<b>בע\"ח. . י' הרוגי מלוכה. . להעלו' מ\"ן לאו\"א</b>: ראה ע\"ח שער (מ\"ן ומ\"ד) של\"ט דרוש א. מאמרי אדה\"ז תקס\"ה ח\"א ע' קלא ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תרכז. בראשית ע' שנז. שערי תשובה נו, ב."],["5201","17","<b>גלו לאדום שכינה עמהם</b>: ספרי ס\"פ מסעי. וראה מגילה כט, א."],["5202","18","<b>בחכמה אתברירו</b>: ראה זהר פקודי רנד, סע\"ב."],["5203","19","<b>בע\"ח ע\"פ א\"ל נקמות ה'</b>: ראה הנסמן לעיל בהערה 16."]]],[2100990342,"<b>והיינו</b> שאמר על ר\"ע כך עלה במחשבה כלומר שר\"ע עלה במחשבה עילא' סתימא' כדי שיהא על ידו מקור לכל הברורי' לעתיד ולכך אין תימא כלל לומר וכי זו<sup data-n=\"5204\">20</sup> תורה וזו שכרה דאדרבה זהו שכרה של תורתו של ר\"ע שמברר במחשבה עילא' כו' וד\"ל וכל זה מטעם שישראל עלה במחשבה סתימא' לפניו כנ\"ל ואמנם ירדו אח\"כ למטה בעולם הפירוד כדי לברר ברורי' בתשובה ומע\"ט והנה ירידה זו צורך עלי' היא בודאי כידוע וענין העלי' שלהם היינו ודאי למעלה ממקור חוצבם בתחלה דהיינו לבחי' אור הכתר שלמעלה גם מבחי' המחשבה שאור אבא כידוע וסיבת עליי' זאת הוא ע\"י המצות מעשיו' שעושין בעוה\"ז לפי ששרש המצו' הוא בבחי' אור הכתר<sup data-n=\"5205\">21</sup> כידוע שנק' המצו' בכלל תר\"ך עמודי אור והטעם שנק' עמודי\"ם דוקא כי עד\"מ העמוד שרגלו נעוץ בארץ וראשו מגיע השמיימ' ויכולי' לטפס עליו ולעלות עליו מן הארץ עד בגובה השמים כך ע\"י המצו' יכולי' לעלות עד בחי' אור הכתר שנק' גלגלתא דא\"א שלמעלה מן כל &lt;שנה&gt;\nההשתלשלו' גם מבחי' חכמ' סתימא' הנ\"ל שישראל עלה שם וכידוע דהכתר<sup data-n=\"5206\">22</sup> נק' קרקפתא והוא מלשון כותרת ונק' ג\"כ עטרה כי כתר<sup data-n=\"5207\">23</sup> עליון נק' כתר מלכו' והענין הוא כי אין טעם כלל לרצון מפני שהוא למעלה מן הטעם ודעת כו' וד\"ל.\n<b>והנה</b> על המצות אמר ועשיתם<sup data-n=\"5208\">24</sup> כל מצוותי והייתם קדושי' לאלקיכם וע\"ז אמר יכול כמוני ת\"ל כי קדוש אני קדושתי למעלה מקדושתכם פי' כי הגם שע\"י המצות מגיעין ועולין עד בחי' אור הכתר שלמעלה מן החכמ' הנק' קדוש אבל קדושתי למעלה גם מקדושת המצות כי הנה ידוע דבחי' מל' דא\"ס נעשה בחי' כתר לנאצלי' ודרך כלל בחי' הכתר הוא בחי' ממוצע בין עצמו' אור א\"ס לנאצלי' ונחלק לב' פרצופי' ע\"י וא\"א בחי' ע\"י הוא מבחי' מל' דא\"ס או מל' דא\"ק ובחי' א\"א הוא נעשה כתר וראש לנאצלים ונמצא לגבי בחי' א\"ס עצמו הוא נק' בחי' מל' ולגבי הנאצלי' הוא נק' כתר ואין ערוך כלל ביניהם כי בחי' מל' דא\"ס שמאיר בע\"י נק' עתיק<sup data-n=\"5209\">25</sup> יומין מלשון המעתיק הרים כו' שנעתק ומובדל מיומין דאצי' ובחי' א\"א הוא למטה ממנו אחר שבא להיו' מקור לאצי' כו' וכידוע והנה המצות שהן תר\"ך עמודי אור כנ\"ל הרי שרשם בבחי' א\"א והן בחי' תרי\"ג<sup data-n=\"5210\">26</sup> ארחין דגלגלתא כמ\"ש באד\"ר אבל קדושתי היינו בחי' מל' דא\"ס שהוא בחי' ע\"י בכלל שלמעלה גם מקדושת המצות שבכתר להיותו נבדל בערך מן כל ההשתלשלו' כנ\"ל וזהו שאמר יכול כמוני פי' כמו בחי' מל' דא\"ס ת\"ל כי קדוש אני קדושתי למעלה גם מקדושתכם שע\"י המצות מטעם הנ\"ל וזהו ג\"כ ענין המלך הקדוש שאו' בעי\"ת שהוא בחי' מל' דא\"ס",[["5204","20","<b>זו תורה וזו שכרה</b>: מנחות שם. וראה ביאוה\"ז בשלח מז, א. וראה מאמרי אדה\"א ויקרא ח\"ב ע' תתטז. במדבר ח\"ב ע' תקלז."],["5205","21","<b>הכתר. . תר\"ך עמודי אור</b>: ראה פרדס (שער מהות והנהגה) ש\"ח פ\"ג."],["5206","22","<b>דהכתר נק' קרקפתא</b>: ראה תקו\"ז בהקדמה."],["5207","23","<b>כתר עליון נק' כתר מלכות</b>: תקו\"ז שם."],["5208","24","<b>ועשיתם כל מצוותי והייתם קדושים</b>: שלח טו, מ."],["5209","25","<b>עתיק יומין מלשון המעתיק הרים</b>: נסמן לעיל ע' תרעו."],["5210","26","<b>תרי\"ג ארחין דגלגלתא כמ\"ש באד\"ר</b>: ראה זהר (אדרא רבא) נשא קכט, א. קלו, א. ביאוה\"ז וישלח יט, ב ואילך. לקו\"ת ראה כא, ד."]]],[2100990343,"שנק' מלך אבל הוא קדוש למעלה גם מקדוש' המצות שאין המצו' מגיעי' לשם מטעם הנ\"ל וע\"כ ע\"י שאו' בעי\"ת המלך הקדוש מחזירין אור הקדוש' מחדש לגמרי אע\"פ שכבר נפגם האור ע\"י העונות והחטאי' אחר שקדושה זו מקור לקדושת המצו' ולמעלה הרבה ממנה ע\"כ יש ביכולתה להמשיך מקור לקדוש' מחדש ולתקן כל פגם וחסרון כו' וד\"ל.\n<b>ובכל</b> זה מובן פי' הברכה שעל כל המצו' להמשיך מקור לקדושת הכתר מבחי' מל' דא\"ס כנ\"ל כי ברוך ר\"ל מבורך הוא מעצמו' מקור הראשון ומשם מגיע הברכה בכתר ומכתר לבחי' חכמה<sup data-n=\"5211\">27</sup> הנק' אתה כידוע ומאתה לאלקינו מלך שהן זו\"נ כו' אשר קדשנו במצוותיו שקדשנו בקדושת המצו' שנק' אשר<sup data-n=\"5212\">28</sup> לשון עונג והוא בחי' ע\"י שמקבל מבחי' א\"ס עצמו כנ\"ל וזהו כמו נתינת טעם מפני מה יש מקור לקדושה זו ואמר אש\"ר קדשנ\"ו כו' וד\"ל.\n<b>ועתה</b> יש להבין שרש ענין כי כארץ תוציא צמחה הנ\"ל. דהנה מאמר תדשא<sup data-n=\"5213\">29</sup> הארץ המלובש בארץ הוא מבחי' מל' שבמל' דעשי' והוא ענין בחי' כח היולי להצמיח כל מיני עונג וטעם והנה הוא כח כולל בעצמו כל מה שעתיד להצמיח ממנו ונק' כח המצמיח זה שיש בארץ בשם כח היולי כמו עד\"מ כח טפת זכר המוליד שכולל כל מה שעתיד ליגדל בולד מאיברי' רבים ושונים כו' והגרעין הנזרע בארץ אינו אלא סיבה להוציא מכח זה ההיולי ולהגביל איזה דבר מה במציאות פרטי' נגלית מן כח ההעלם שבכח &lt;שנו&gt;\nזה שכולל הכל כאחד בלתי התחלקו' ניכרת בו כלל והדוגמא בזה הנה אותו הכח ההיולי כולל כל מיני טעם שיש במציאו' נגלית בפירות הגדילי' מכח המצמיח הזה כמו טעם הקישואין והדילועין עם טעם מתיקו' התפוחים כוללם יחד בלתי התחלקו' ניכרת ועד\"ז כולל כל פרטי טעמים הנמצאי' כו' יש מהן חמוצים מאד ויש מהן מתוקים מאד והוא כוללם יחד ואינם ב' הפכי' כלל בהיותם נכללים בו כי אינו אלא כח היולי עדיין ולא נגבל אור שפעו עדיין במציאת יש ודבר נגלה במהו' והיינו שלא נגבל אורו בכלים עדיין אך הגרעין הוא הגורם הגבלה זו בזריעתו הגם שאין בו טעם וריח כלל מצד עצמו אבל לפי שהי' בו פ\"א כח הצמיחה בגילוי מאותו כח ההיולי נבדלת במציאו' פרטי אותה המציאו' שבגרעין מאיזה טעם שיהי' אם מטעם חמוץ או מטעם מתוק הנה הוא המעלה מ\"ן לכח ההיולי הנ\"ל להבדיל ממנו בגילוי הצמיחה שמצמיח בהגבלה פרטית במציאת דבר מה כפי ההעלא' מ\"ן שהעלה אם טעם מתוק או חמוץ כפי אותו המין דוקא דהיינו שגרעין החמוץ כקישואין יצמיח קישואי' ומגרעין אחר יצמיח טעם אחר כיוצא בו ממש כו' כמו השומין והבצלים וכן בפירו' האילנות וצמיחת התבואו' הכל עד\"ז הוא וד\"ל.",[["5211","27","<b>חכמה הנק' אתה</b>: ראה לקו\"ת ואתחנן ז, ב."],["5212","28","<b>אשר לשון עונג</b>: ויצא ל, יג. ראה ת\"ז ת\"ל (עד, ב). תל\"ט (עט, א). לקו\"ת בשלח א, ד."],["5213","29","<b>תדשא הארץ</b>: בראשית א, יא."]]],[2100990344,"<b>והנמשל</b> מכל זה יובן למשכיל למעלה בענין המאמר זורע<sup data-n=\"5214\">30</sup> צדקות שצדקה<sup data-n=\"5215\">31</sup> שהיא כוללת כל המצות כנ\"ל נמשלה לזריעה והגם שאין בהם ריח וטעם כלל אחר שמלובשי' המצות בדברים גשמיים כתפילין בקלף גשמי וכיוצא אבל הם מעלין מ\"ן לכח העליון שבבחי' כתר שהוא מקור כל התענוגי' העליוני' הכוללם יחד בלתי התחלקו' ניכרת כמשל כח הצומח שבארץ הכולל כל הטעמי' גשמיים כנ\"ל ומוציאי' מתוכו מן ההעלם לבא העונג האלקי בגילוי במציאו' ניכרת אור בכלי כמו שמתלבש העונג בחכמה שאז העונג מורגש במציאת חכמה<sup data-n=\"5216\">32</sup> ונק' עדן כידוע<sup data-n=\"5217\">33</sup> בפי' ונהר יוצא מעדן כו' אבל בלא התלבשות לא ניכר ונרגש שום עונג במקור התענוגי' אך ורק ע\"י העלא' מ\"ן מן המצות נבדל משם האור לבא בגילוי במציאו' כפי אותה ההעלא' ממש וכמשל זריעת הגרעין שמוציא מן ההעלם כיוצא בו דוקא וד\"ל.\n<b>וזהו</b> שרש ענין כי כארץ תוציא צמחה האר\"ץ הוא בחי' גילוי הרצון בכנ\"י במעשה המצות בגשמיו' שהוא כמשל הזריעה כנ\"ל ולעתיד תוציא צמחה מהעלם מקור כל התענוגי' והיינו שכר מצות בג\"ע העליון מלבד מה שאוכלין<sup data-n=\"5218\">34</sup> פירותיהן בעוה\"ז, דהיינו ענין גילוי זיו העונג העליון שם מה שנהנין מזיו כו' עד שאמרו מוטב<sup data-n=\"5219\">35</sup> דלידייני' כו' כי זיו זה עונג נפלא הוא שאין כמוהו וד\"ל.\n<b>והנה</b> יש בזריעה זו ב' מדרגו' הא' כונות המצות שהצמיחה מזריעה זאת הוא בג\"ע העליון שהיא בבחי' בינה שבמל' דאצי' כי הכונה באה בהשגה והתבוננו' דוקא אך זאת הכונה בהשגה מצומצמת של הנשמה בעודנה מלובשת בחומר גופני היא רק כמו משל גרעין הזרוע שאין בו טעם וריח כלל כו' והצמיחה ממנה הוא השגה האלקי' כשמשגת הנשמה בג\"ע מזיו כו' דהיינו בבחי' בינה שבמל' דאצי' והזריעה הב' גופה של מעשה המצוה שהיא כדוגמת גופו של גרעין שמצמיח גופו של פרי מלבד טעמה והנמשל מזה הוא הארה האלקי' המצומצמת בג\"ע התחתון שצומחת שם &lt;שנז&gt;\nממצות<sup data-n=\"5220\">36</sup> אנשי' מלומדה כו' שהוא בחי' מל' שבמל' כו' וד\"ל.\n<b>וזהו</b> שרש ענין כן יצמיח א\"ד ה' צדקה ותהלה כו' פי' כי בחי' בינה שבמל' ובחי' מל' שבמל' שמאירין בג\"ע התחתון והעליון הן בחי' פנימיו' החיות והאור של ההשפעה האלקי' הנגלית שם בג\"ע עליון ותחתון והן הנקראין ב' שמות שם דאד' מאיר בג\"ע התחתון שהוא בחי' מל' שבמל' ושם דהוי' בניקוד אלקי' מאיר בג\"ע",[["5214","30","<b>זורע צדקות</b>: ברכת יוצר."],["5215","31","<b>שצדקה שהיא כוללת כל המצות</b>: ראה תניא פל\"ז (מח, ב). תו\"א מקץ לח, ג. מב, ג. בשלח סג, ג."],["5216","32","<b>חכמה ונק' עדן</b>: ראה זח\"ב קכג, ב. וראה תו\"א לך יא, ב."],["5217","33","<b>כידוע בפ' ונהר יוצא מעדן</b>: בראשית ב, יו\"ד. ראה זהר אדרא זוטא רצב. וראה תו\"א ט, ב. לקו\"ת מסעי צב, ד. שה\"ש לט, ב."],["5218","34","<b>שאוכלין פירותיהן בעוה\"ז</b>: ראה קדושין לט, ב. וש\"נ."],["5219","35","<b>מוטב דלידייני'</b>: חגיגה טו, ב. וראה הנסמן במאמרי אדה\"א דברים ח\"א ע' נט."],["5220","36","<b>ממצות אנשים מלומדה</b>: ישעי' כט, יג. וראה הנסמן בתו\"ח ויחי רמב, סע\"ג הערה 44."]]],[2100990345,"העליון שהוא בבחי' בינה שבמל' שהוא הוי' בניקוד אלקים דוקא וכידוע דענין בחי' השמות מורים על בחי' הפנימיות להיותם בחי' מקוריו' להשפעה אשר נמשכת מהם כו' והיינו שאמר כן יצמיח אד' הוי' צדקה ותהלה שהן ב' שמו\"ת דאד' והוי' בניקוד אלקי' שמאירי' בב' ג\"ע העליון והתחתון והן הנק' צדקה ותהלה צדקה בג\"ע התחתון ותהלה בג\"ע העליון וכולם הן שכרן של מצות הנזרעות בעוה\"ז וד\"ל.\n<b>ואמנם</b> הנה יש עוד מדרגה שלישית והוא הצמיחה שצומחת מאליה בלתי זריעה כלל והנמשל מזה הוא ענין אתעדל\"ע שהיא בלא אתעדל\"ת כלל בהעלא' מ\"ן של זריעה וכנ\"ל והיינו בזמן ר\"ה ויו\"כ דכתיב אז דרשו<sup data-n=\"5221\">37</sup> ה' בהמצאו שנמצא מצד התעוררו' עצמותו בלתי העלא' מ\"ן כלל מלמטה, וגם מאתעדל\"ע זו שבר\"ה ויו\"כ נמשך על כל השנה להיו' כח בכנ\"י להעלות אתעדל\"ת להיו' עי\"ז אתעדל\"ע כו' וד\"ל.\n<b>ובהקדמה</b> זו יתפרש הפסוק באופן אחר דהיינו כמו שהארץ תוציא צמחה בהעלא' מ\"ן בזריעה כן יצמיח ה' צדקה כו' באתעדל\"ע לבד בלתי העלא' מ\"ן וד\"ל. אך הטעם לזה למה בר\"ה ויו\"כ יש אתעדל\"ע גם בלתי אתעדל\"ת הנה הענין הוא לפי שבר\"ה<sup data-n=\"5222\">38</sup> מתחיל בנין כל ההשתלשלו' דאבי\"ע מחדש וכמו שאומרי' בר\"ה זה היום תחלת מעשיך כו' והיינו שבנין הנוקבא נבנית מחדש ולזה אמרו שביום<sup data-n=\"5223\">39</sup> הששי שבו נברא אדה\"ר אמר מזמור זה ה' מלך גיאו' לבש וזה הי' בר\"ה כידוע דבר\"ה נברא האדם כו' והתחדשו' זאת גורמת מחדש ההתעוררו' הראשונה שהי' במאציל מתחלת ההשתלשלו' כי<sup data-n=\"5224\">40</sup> חפץ חסד הוא כו' וכידוע וע\"כ א\"צ כלל להעלא' מ\"ן בר\"ה אלא אתעדל\"ע מצד עצמו נמשך בעי\"ת מר\"ה ועד יו\"כ להיו' מתחדשת כל ההשתלשלו' די\"ס באורו' וכלים שהן שרש ענין הי' עומקי' כמשי\"ת בסמוך בעזר\"ה וד\"ל.\n<b>ובזה</b> יובן יותר הטעם לסליחת העונות ביו\"כ לתקן כל פגם וחסרון ולמלאת כל מה שנחסר מאור הקדוש' בשנה שעברה כי הרי נתחדש אור המאציל מעיקרו כמו שהי' מתחלת ההשתלשלו' בבחי' אתעדל\"ע שמצד עצמו שאז ביכולת להמשיך אור חדש אשר עדיין לא הי' בתחלת ההשתלשלו' ובזה האור יתמלא כל חסרון כנ\"ל לפי שהחסרון לא בא רק באותו האור שכבר בא בהשתלשלו' כנ\"ל וד\"ל.\n<b>וזהו</b> שרש ענין י\"ג מדה\"ר שנמשכי' בנעילה דיו\"כ באמרם ויעבור<sup data-n=\"5225\">41</sup> ה' על פניו ויקרא ה' אל רחום כו' וידוע שי\"ג מדה\"ר הללו נמשכי' מבחי' אור הכתר אך",[["5221","37","<b>דרשו ה' בהמצאו</b>: ישעי' נה, ו. ר\"ה יח, א."],["5222","38","<b>שבר\"ה. . בנין כל ההשתלשלו' דאבי\"ע מחדש</b>: ראה ביאוה\"ז להצ\"צ כרך א ע' שצו ומ\"מ לשם."],["5223","39","<b>שביום הששי שבו נברא אדה\"ר אמר מזמור זה ה' מלך</b>: תהלים צג, א. ראה פדר\"א פי\"א. מאמרי אדה\"א דברים ח\"ג ע' תשס. וש\"נ. תו\"ח וישלח קפא, ד ובהערה 64."],["5224","40","<b>כי חפץ חסד הוא</b>: מיכה ז, יח."],["5225","41","<b>ויעבור ה' על פניו ויקרא</b>: תשא לד, ו."]]],[2100990346,"מה שנמשכי' בנעילה דיו\"כ דוקא היינו לפי שאור הכתר מקבל הארה חדשה מבחי' פנימי' אור המאציל לחדש כל ההשתלשלות מחדש ולכך ממילא הוא ארך אפים ורב חסד להיו' נושא &lt;שנח&gt;\nעון ועובר על פשע לתקן כל חסרון ופגם מטעם הנ\"ל וד\"ל.\n<b>וזהו</b> פי' ויעבור ה' על פניו, פי' פניו הוא בחי' האורו' והמוחי' שנמשכו כבר באצי' והעברה זו שעובר על פניו היינו שעובר מלמעלה מעלה מבחי' הפנים המאירי' כבר דהיינו שעובר מלמעלה גם מאור הכתר להאיר בכתר באור חדש והוא ענין ההעברה שעובר את עצמו מן בחי' העלם עצמו' המאציל לגילוי להאיר אור חדש בכתר וע\"כ ממילא נמשכי' י\"ג מדה\"ר מאור הכתר מטעם הנ\"ל וד\"ל, וסיבת העברה זאת מצד עצמו היא כי חפץ חסד הוא לפי שבר\"ה דוקא מתחיל זמן אתעדל\"ע שמצד עצמו ונגמר ביו\"כ בנעילה מטעם הנ\"ל והיינו ענין כן יצמיח ה' צדק' ותהלה כו' כנ\"ל וד\"ל.\n<b>ובזה</b> יובן ג\"כ פי' ענין המאמר דכל המצות מברך<sup data-n=\"5226\">42</sup> עליהם עובר לעשייתן פי' עובר הוא ג\"כ ע\"ד הנ\"ל בפי' ויעבור ה' על פניו כו' דר\"ל שעובר<sup data-n=\"5227\">43</sup> מלמעלה למטה דהיינו מבחי' אור המקיף שלמעלה מבחי' א\"פ וזהו עובר לעשייתן כי המעשה של המצוה היא בבחי' א\"פ וע\"י הברכה נמשך בחי' אור מקיף העובר על הא\"פ שמלובש במעשה, וענין העברה זאת היא מלמעלה כמו עד\"מ הלבוש שאדם מלביש ומכסה א\"ע בו שמעטה ומכסה בו את פנימיותו שבזה העיטוף והכיסוי הוא עובר את הלבוש על גופו ושייך בו לשון העברה לפי שהלבוש עובר על הגוף לכסותו מלמעלה כך יובן למעלה בלשון עובר לעשייתן דלישנא דאקדומי הוא כנ\"ל דהיינו מפני שנמשך הא\"מ מלמעלה מאור הכתר ומשם עובר הוא מלמעלה למטה ע\"כ נק' עובר לעשייתן לפי שמלביש את המעשה בדרך העברה מלמעלה בבחי' א\"מ וד\"ל.\n<b>אך</b> הנה זהו העובר מלמעלה ע\"י אתעדל\"ת בברכת המצות שנמשך א\"מ מלמעלה מאור הכתר כנ\"ל אבל בר\"ה ויו\"כ נמשך העברה זאת מצד אתעדל\"ע בלבד בלתי אתעדל\"ת כלל וזהו ויעבור ה' על פניו מצד עצמו וכנ\"ל וע\"כ הוא ממלא אז כל החסרונו' והפגמי' בי\"ג מדה\"ר כמו ארך אפים ורב חסד ואז נא' וזרקתי<sup data-n=\"5228\">44</sup> עליכם מים טהורי' וטהרתם כו' וכידוע וד\"ל.\n<b>ואחר</b> כל הנ\"ל יש להבין שרש ענין המלך הקדוש ומה שאומרי' אותו בעי\"ת דוקא. דהנה פי' קדוש בוי\"ו היינו בחי' המשכת י\"ג תקוני' מאור הכתר רחום וחנון ארך אפים ורב חסד כו' שהן ע\"י בחי' שערות כידוע שהשערו'<sup data-n=\"5229\">45</sup> הן בבחי' יודי\"ן",[["5226","42","<b>מברך עליהם עובר לעשייתן</b>: פסחים ז, ב. וש\"נ."],["5227","43","<b>שעובר. . המקיף</b>: ראה תו\"א ויחי נג, ב. לקו\"ת מסעי צב, ג. ואתחנן ג, ד. ובכ\"מ."],["5228","44","<b>וזרקתי עליכם מים טהורי' וטהרתם</b>: יחזקאל לו, כה."],["5229","45","<b>שהשערו' הן בבחי' יודי\"ן ווי\"ן</b>: ראה תו\"א כב, א ואילך."]]],[2100990347,"ווי\"ן כו' וזהו פי' קדוש<sup data-n=\"5230\">46</sup> יהי' גדל פרע שער ראשו שזהו הקדושה בהמשכת השערו' וכמ\"ש ושער<sup data-n=\"5231\">47</sup> רישי' כעמר נקי וכמ\"ש הפייטן כו'.\n<b>וביאור</b> ענין השערו' ידוע שהוא רק בחי' הצומח שיש בכתר והדוגמא לזה יובן למטה מן הכתר כמו בחכמה שיש בה בחי' צומח להצמיח המדות אוי\"ר כמ\"ש לפי<sup data-n=\"5232\">48</sup> שכלו יהולל איש שבקטן המדו' קטני' לפי ערך קטנו' השכל וכשנגדל השכל נגדלים המדות עמו ונק' גידול המדו' בשכל בבחי' צומח בלבד כי הרי המדו' כלולים בשכל בהעלם במהות אחר מכמו שהן בהתגלות בלב ונק' מדות שבשכל ושם צומחי' מעט מעט כפי ערך גידול השכל אע\"פ שאין להן ערך עם מהות השכל עצמו כו' וכך יובן גם בבחי' חכמה שבכתר הנק' ח\"ס דא\"א שיש מדות כלולי' בו בהעלם ונגדלי' &lt;שנט&gt;\nעמו כפי ערך גידול כח ח\"ס וצומחין בו מעט מעט ואח\"כ בוקעין ויוצאי' בהתגלות והן י\"ג מדות הרחמי' רחום וחנון כו' שיוצאי' בבחי' צומח בשערות די\"ג תקונין כידוע אך שמדות הללו הם מדות גדולים לפי ערך גדלות חכמה שבכתר כידוע וע\"כ נקראו בשם י\"ג מדות הרחמים כו' וכמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> ענין קדוש בוי\"ו ומה שאומרי' המלך הקדוש הוא להמשיך מקדש העליון שלמעלה מקדוש זה והיינו מבחי' פנימי' אור הכתר שבו יאיר אור מל' דא\"ס או בחי' מל' דא\"ק כי הנה ידוע דהכתר<sup data-n=\"5233\">49</sup> נק' בחי' ממוצע בכלל בין עצמו' אור א\"ס לנאצלי' ויש בו מבחי' האחרונה שבמאציל והוא הנק' בחי' מל' דא\"ק כו' וגם הוא ראש ושרש לנאצלי' שלמטה במדרגה מבחי' מל' דא\"ק ואמנם מבחי' מל' דא\"ק הוא שנעשה כתר לאצי' ונחלק לב' פרצופי' אח\"כ בכלל ע\"י וא\"א כנ\"ל ובודאי מה שהוא בחי' מקבל לגבי עצמו' המאציל גבוה הרבה במדרגה ממה שנעשה ראש ומשפיע לנאצלי' כידוע<sup data-n=\"5234\">50</sup> בפי' אמת ואמונה כל זאת וקיים עלינו כו'.\n<b>וזהו</b> ג\"כ ז\"פ<sup data-n=\"5235\">51</sup> כי ה' הוא האלקי' לפי שאלקי' שלמעלה גבוה מהוי' שנעשה למטה כו' והנה ידוע דשרש כללו' נ\"י הוא מבחי' מל' דאצי' כמאמר המשנה כל<sup data-n=\"5236\">52</sup> ישראל בני מלכי\"ם הם פי' מבחי' מלכו' העליונ' והיינו ע\"י קבלת מ\"ש כמ\"ש שום<sup data-n=\"5237\">53</sup> תשים עליך מלך כו' והרי ידוע דנעוץ<sup data-n=\"5238\">54</sup> סופן בתחלתן ותחלתן בסופן כידוע בפי'",[["5230","46","<b>קדש יהי' גדל פרע שער ראשו</b>: במדבר ו, ה."],["5231","47","<b>ושער רישי' כעמר נקי</b>: דניאל ז, ט."],["5232","48","<b>לפי שכלו יהולל איש</b>: משלי יב, ח."],["5233","49","<b>הכתר. . ממוצע</b>: ראה ע\"ח שער דרושי אבי\"ע (שמ\"ב) פ\"א. שער מוחין דצלם (שכ\"ג) פ\"ח. וראה לקו\"ת בחקותי מו, ג. שלח מט, ג. סידור שער הל\"ג בעומר שו, ב."],["5234","50","<b>כידוע בפי' אמת ואמונה כל זאת וקיים עלינו</b>: ברכת אמת ואמונה (תפלת ערבית). וראה סידור שער בהמ\"ז קיב, ב. ביאוה\"ז וילך קיג, ד. קכד, ד."],["5235","51","<b>ז\"פ כי ה' הוא האלקי'</b>: ראה מאמרי אדה\"א בראשית ע' קעג בהערה שם."],["5236","52","<b>כל ישראל בני מלכים</b>: שבת קיא, א."],["5237","53","<b>שום תשים עליך מלך</b>: פ' שופטים יז, טו."],["5238","54","<b>דנעוץ סופן בתחלתן</b>: ס\"י פ\"א, מ\"ז."]]],[2100990348,"המאמר דקרקפתא<sup data-n=\"5239\">55</sup> איהו כתר עליון ואיהו כתר מלכות כו' וא\"כ שרש כנ\"י ע\"י קבלת מ\"ש ממל' דאצי' שנק' סופן מגיע בתחלתן שהוא בחי' מל' דא\"ס שנק' מלכו' ג\"כ אלא שהוא בבחי' הא\"ס כענין הי' הוא ושמו בלבד כו' וכמ\"ש במ\"א וע\"כ יכולים הם להמשיך י\"ג מדה\"ר באור הכתר מבחי' מל' דא\"ס שנעשה כתר לאצי' שהוא בחי' פנימי' אור הכתר כנ\"ל והיינו באמרם המלך הקדוש פי' המלך הוא בחי' מל' דא\"ס כנ\"ל ואח\"כ הקדוש הוא המשכת י\"ג תקוני' שמאירי' בכתר מבחי' פנימיותו דוקא וכמ\"ש ויעבור ה' על פניו דהיינו מבחי' מל' דא\"ס הוא עובר מלמעלה למטה להיו' נק' בשם הקדוש בי\"ג מדה\"ר כנ\"ל וד\"ל.\n<b>ומה</b> שאו' המלך הקדוש בעי\"ת דוקא הענין הוא כי הנה בעי\"ת ממשיכי' י'<sup data-n=\"5240\">56</sup> עומקים באמרם ממעמקי' קראתיך הוי' כו' ב' עומקי' הללו היינו להמשיך עומק לעומק וכמ\"ש במ\"א והענין הוא להמשיך מבחי' מל' דא\"ס שנק' עומק לעומק דכתר שנעשה ראש לנאצלי' וצריך י' עומקים מבחי' מל' דא\"ס לי\"ס דאצי' בעי\"ת<sup data-n=\"5241\">57</sup> בכל יום נמשך עומק א' לספי' א' ובר\"ה נמשך לבחי' ספי' המל' תחלה להיו' כתר למלכו' מבחי' מל' דא\"ס המאיר בעתיקא והיינו ענין תקיעת שופר בכלל שבהבלי' דתקיעו' עלה<sup data-n=\"5242\">58</sup> אלקי' בתרועה כו' ונתגלה בהם מבחי' פנימי' דע\"י דהיינו ממל' דא\"ס שיש בו כנ\"ל ועד\"ז בשאר הימי' עד יו\"כ<sup data-n=\"5243\">59</sup> שהוא בספי' הכתר עצמו והיינו בכתר שבכתר ולכך נק' קדוש הוי' כו' וכמ\"ש במ\"א שאז נא' לפני<sup data-n=\"5244\">60</sup> הוי' תטהרו דהיינו מבחי' מל' דא\"ס שיש בכתר זה הנק' כתר שבכתר כו' וד\"ל וע\"כ אומרי' בכל עי\"ת המלך הקדוש כדי להמשיך מבחי' מל' דא\"ס י' כתרים הנק' עומקי' כנ\"ל לי\"ס דאצי' ואין הפרש בזה בין ר\"ה לשאר עי\"ת כי בכולן צריך לומר המלך הקדוש וממעמקי' כו' מטעם הנ\"ל וד\"ל.\n&lt;שס&gt;\n<b>ובכל</b> זה יתפרש יותר שרש ענין כן יצמיח ה' אלקי' צדק' ותהלה כו', צדקה<sup data-n=\"5245\">61</sup> שם אד' בר\"ה<sup data-n=\"5246\">62</sup> שנק' דינא דמלכותא כו' ותהלה ביו\"כ שהוא הוי' בניקוד אלקי' כו' דהנה יו\"כ נק' קדוש הוי' כו' כמו העוה\"ב<sup data-n=\"5247\">63</sup> שאין בו לא אכילה ולא שתי' כו' כידוע והוא להיו' כי בחי' יו\"כ עיקרו הוא בבחי' בינה<sup data-n=\"5248\">64</sup> שהיא שרש העוה\"ב כידוע וגם נק'<sup data-n=\"5249\">65</sup> יובלא כו' ולכך עיקר טהרת העונות ביו\"כ לפי שכל טהרה ורחיצה הוא",[["5239","55","<b>דקרקפתא איהו כתר</b>: תקו\"ז בהקדמה."],["5240","56","<b>י' עומקים. . ממעמקים קראתיך</b>: תהלים קל, א. סוף שער תפלת ר\"ה בספר ע\"ח."],["5241","57","<b>בעי\"ת בכל יום נמשך. . לספי' א'</b>: ראה פע\"ח שער (כד) ר\"ה פ\"א ואילך. פ\"ו."],["5242","58","<b>עלה אלקי' בתרועה</b>: תהלים מז, ו."],["5243","59","<b>יו\"כ. . קדוש הוי'</b>: ישעי' נח, יג. וע\"ש בפי' הרד\"ק. וראה לקו\"ת דרושים לר\"ה נד, ג."],["5244","60","<b>לפני הוי' תטהרו</b>: אחרי טז, ל."],["5245","61","<b>צדקה שם אד'</b>: ראה זהר אחרי עב, א."],["5246","62","<b>בר\"ה שנק' דינא דמלכותא</b>: נסמן לעיל ע' תשו."],["5247","63","<b>העוה\"ב שאין בו לא אכילה ולא שתי'</b>: ברכות יז, א."],["5248","64","<b>בינה שהיא שרש העוה\"ב</b>: ראה פרדס שער (כג) ערכי הכינויים מערכת עולם. לקו\"ת פקודי ג, ג. מאמרי אדה\"א דברים ח\"ד ע' א'רי. קונטרסים ע' שפ."],["5249","65","<b>נק' יובלא</b>: ראה זהר תצוה קפג, א. מאו\"א מערכת דרור יג."]]],[2100990349,"בבחי' בינה<sup data-n=\"5250\">66</sup> דוקא שנק' אם הבנים כידוע וכמאמר תבא<sup data-n=\"5251\">67</sup> האם ותקנח צואת בנה כו' וכמ\"ש<sup data-n=\"5252\">68</sup> במ\"א ע\"פ אם רחץ ה' צואת כו' א\"ת אם אלא א ם כו' וד\"ל והיינו ענין תהלה שהוא שם הוי' אבל הוא בניקוד אלקי' בינה לברר וללבן כל העונות כו' וע\"ז נא' רוממו'<sup data-n=\"5253\">69</sup> אל בגרונם וחרב פיפיו' לעשו' נקמה בגוים להעביר<sup data-n=\"5254\">70</sup> רוח הטומא' ע\"י התהלה ברוממו' אל כו' כי לזה הטעם הוא בניקוד אלקי' כו' ולכך נק' תהלה כי ע\"י התהלה דוקא ברוממו' אל נעשה חרב פיפיו' לגוים כו' ועיקר הענין הוא כי הנה מבואר למעלה דהכתר הוא בחי' ממוצע ושם אלקי' שבו הוא מבחי' מל' דא\"ס ושם הוי' שבו הוא בחי' הכתר לאצי' ובודאי בחי' האלקי' גבוה והוא עליי' הוי' לאלקי' כשאו' בנעילה כי הוי' הוא האלקי' כנ\"ל ובזה נק' תהלה דקאי על תהלה שבכתר בבחי' הפנימי' שבו דהיינו מבחי' מל' דא\"ס דלית<sup data-n=\"5255\">71</sup> מחשבה תפיס' בי' אפי' מחשבה סתימא' דא\"א משום דלא<sup data-n=\"5256\">72</sup> ידע לי' בר איהו בלחודוהי ולא שייך בו תהלה מצד המקבלי' אלא רק שנמשך מלמעלה התהלה שיוכלו להשיגו ולהללו וכמ\"ש ותהלתי<sup data-n=\"5257\">73</sup> אחטם לך וכמ\"ש במ\"א וע\"כ נק' רוממו' אל דוקא ומשם נעשה חרב פיפיו' להחיצוני' לאהפכא<sup data-n=\"5258\">74</sup> חשוכא לנהורא כו' וזהו כן יצמיח ה' צדקה בר\"ה ותהלה ביו\"כ בשם הוי' בניקוד אלקי' שבכתר שירד ויאיר בבינה ביו\"כ כנ\"ל נגד כל הגוים כמו עשו וכו' דהיינו כו' להפוך הזדונות<sup data-n=\"5259\">75</sup> כזכיות משום דקמיה עצמותו ממש כחשיכה<sup data-n=\"5260\">76</sup> כאורה כו' וע\"כ משם נמשך הסליחה למטה כמ\"ש כי<sup data-n=\"5261\">77</sup> עמך הסליחה למען תורא וכמ\"ש במ\"א וד\"ל.",[["5250","66","<b>בינה. . אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. פרדס שער (כג) ערכי הכינויים מערכת אם הבנים. לקו\"ת דרושים לשמע\"צ פח, ד."],["5251","67","<b>תבא האם ותקנח צואת בנה</b>: ראה תנחומא חוקת ח. במד\"ר פי\"ט, ח."],["5252","68","<b>וכמ\"ש במ\"א ע\"פ אם רחץ ה' צואת</b>: ישעי' ד, ד. פרע\"ח שער (יח) השבת פ\"ג. וראה ביאוה\"ז שמיני סט, א. אמור פב, א. תו\"א מג\"א צו, ד. תו\"ח נח נט, רע\"ד. אוה\"ת ישעי' כרך א ע' קז ס\"ג."],["5253","69","<b>רוממות אל בגרונם. . לעשו' נקמה בגוים</b>: תהלים קמט, ו. ז."],["5254","70","<b>להעביר רוח הטמאה</b>: ראה זכרי' יג, ב."],["5255","71","<b>דלית מחשבה תפיס' בי'</b>: תקו\"ז בהקדמה (יז, א)."],["5256","72","<b>דלא ידע לי' בר איהו בלחודוהי</b>: ראה זהר ויקהל רי, ב. (אד\"ר) נשא קכט, ב. קמ, ב. (אד\"ז) האזינו רפח, א."],["5257","73","<b>ותהלתי אחטם לך וכמ\"ש במ\"א</b>: ישעי' מח, ט. ראה לקו\"ת שלח נא, ד. מסעי צ, ד."],["5258","74","<b>לאהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["5259","75","<b>הזדונות כזכיות</b>: יומא פו, ב."],["5260","76","<b>כחשיכה כאורה</b>: ראה תהלים קלט, יב."],["5261","77","<b>כי עמך הסליחה</b>: תהלים קל, ד. וראה לקו\"ת דרושים לש\"ש סו, ד."]]],[2100990350,"<h3>יסובבנהו יבוננהו</h3>\n<b>בעזר\"ה, שבת שובה</b>\n<b>יסובבנהו</b><sup data-n=\"5262\">1</sup> יבוננהו<sup data-n=\"5263\">2</sup> יצרנו כאישון עינו<sup data-n=\"5264\">3</sup>. הנה כנ\"י<sup data-n=\"5265\">4</sup> נק' אישון עינו שהרי נקראו בבת עינו של הקב\"ה כמארז\"ל כל הנוגע<sup data-n=\"5266\">5</sup> בהם כאילו נוגע בבבת עינו כו' וכתיב עיני<sup data-n=\"5267\">6</sup> ה' אל צדיקי' עין<sup data-n=\"5268\">7</sup> ה' אל יריאיו כו'.\n<b>והענין</b> הוא כי הנה עד\"מ כלי העין באדם התחתון הנה היא בחי' כלי בעלמא לכח הראיה הרוחניות שבמוח שהרי כח הראי' יש בנפש קודם בואה לגוף אלא שבעין עובר ומתלבש כח זה הרוחני להיו' נתפס בו במהות ראיה גשמית שהוא השגחה גשמית והרי כלי העין רק כמו לבוש בעלמא להלביש כח הראי' הרוחניות כמו כאשר יביט האדם בכלי הזכוכית הבהירה וכיוצא וכך &lt;שסא&gt;\nיובן בדוגמא ומשל בבחי' עין ה' למעלה באדם העליון שהוא בחי' כלי ההשגחה שמשגיח ה' בכל העולמות וכמ\"ש משמים<sup data-n=\"5269\">8</sup> הביט ה' כו' וכתיב עיני<sup data-n=\"5270\">9</sup> ה' משוטטו' כו'.\n<b>אך</b> הנה השגחה זאת היא רק בחי' לבוש בעלמא לבחי' כח הראי' האלקי' עצמה כמבואר מתוך משל כלי העין באדם התחתון למטה והנה כתיב השקיפה<sup data-n=\"5271\">10</sup> ממעון קדשך מן השמים כו' והשקפה זאת מבחי' כח הראי' עצמה היא באה והשקפה והשגחה זו באה ע\"י ישראל דוקא שנק' אישו\"ן עינו כי ישראל<sup data-n=\"5272\">11</sup> עלה במחשבה דוקא וזהו יותר גבוה ממדרגת המלאכי' שנבראו מבחי' הדיבור וכמ\"ש בדבר<sup data-n=\"5273\">12</sup> ה' שמים נעשו<sup data-n=\"5274\">13</sup> כו'.",[["5262","1","<b>יסובבנהו יבוננהו יצרנו כאישון עינו</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (קד, א).\nמאמר זה עם הגהות וקיצורים וסעיפים מכ\"ק אדמו\"ר הצ\"צ [בכותרת: מה שאמר בחג הסוכות] יצא לאור בקונטרס בפ\"ע בשנת תשכ\"ב עם הערות ומ\"מ בשולי הגליון מכ\"ק אדמו\"ר זי\"ע.\nבהוצאה הקודמת נדפס מאמר הצ\"צ בסוף הספר בתור הוספה, ואי\"ה יודפס זה באוה\"ת דברים החדש שיצא לאור בקרוב.\nהד\"ה יסובבנהו יבוננהו הנדפס במאמרי אדה\"א הנחות תקע\"ז ע' שלה מיוסד על מאמר זה.\nד\"ה בראשית ברא הנדפס בפלח הרמון בראשית — כד, א מיוסד על ד\"ה זה."],["5263","2","<b>יסובבנהו יבוננהו</b>: האזינו לב, יו\"ד."],["5264","3","<b>עינו</b>: ראה לקו\"ת דברים סג, א. שם ד\"ה כנשר יעיר. — הערת כ\"ק אדמו\"ר זי\"ע."],["5265","4","<b>כנ\"י</b>: שם במאמרי אדמו\"ר הצ\"צ: בנ\"י. ובהערה שם: נ\"א: כנס\"י."],["5266","5","<b>כל הנוגע בהם כאילו נוגע בבבת עינו</b>: גיטין נז, א. מכילתא ותנחומא בשלח טו, ז. ספרי בהעלותך י, לה. שמו\"ר רפי\"ג."],["5267","6","<b>עיני ה' אל צדיקי'</b>: תהלים לד, טז."],["5268","7","<b>עין ה' אל יריאיו</b>: תהלים לג, יח."],["5269","8","<b>משמים הביט ה'</b>: תהלים לג, יג."],["5270","9","<b>עיני ה' משוטטו'</b>: דברי הימים-ב טז, ט. וראה זכרי' ד, י."],["5271","10","<b>השקיפה ממעון קדשך מן השמים</b>: תבוא כו, טו."],["5272","11","<b>ישראל עלה במחשבה</b>: ב\"ר פ\"א, ד. תקו\"ז ת\"ו בסופו. ובכ\"מ."],["5273","12","<b>בדבר ה'</b>: כנראה סמיך אסיפי' דקרא: כל צבאם. — הערת כ\"ק אדמו\"ר זי\"ע."],["5274","13","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."]]],[2100990351,"<b>ומ\"מ</b> יש יתרון מעלה במלאכי' מה שאין בנשמו' ויובן טעם ענין זה בהקדים שרש ענין המלאכי' דהנה כתיב הבן<sup data-n=\"5275\">14</sup> יקיר לי אפרים כו' המו מעי לו וידוע דהמלאכי' נק' מעי כמבואר בזוהר<sup data-n=\"5276\">15</sup> שיש מלאכי' שנק' אצטומכא כו' וכמבואר במ\"א ע\"פ<sup data-n=\"5277\">16</sup> וכל קרביי את שם קדשו<sup data-n=\"5278\">17</sup> כו' קרביי ממש כי הנה עד\"מ המאכל הבא בקרביים גשמיים הוא מתברר שם ובהם ועל ידם תעבור שפע חיו' המאכל להאיברי' כו' ונק' הקרביים כלי ההשפעה להוליך השפע לכל אבר כו'. וכך למעלה יש מלאכי' שנק' קרביים שמהם ועל ידם תעבור אור השפע האלקי' למטה כו'. וכמו שידוע דלכל דבר ודבר יש לו כח ושרש למעלה השופע זה הדבר כמו למציאת החכמה יש כח ושרש השופע חכמה בתמידו' ונק' שר של חכמה וכן שר<sup data-n=\"5279\">18</sup> של מים ושר של אש כו' וכיוצא עד שאמרו אין<sup data-n=\"5280\">19</sup> לך עשב מלמטה שאין לו מזל כו' ועד\"ז גבוה<sup data-n=\"5281\">20</sup> מעל גבוה שומר וגבוהים עליהם עד רום המעלות וכשם שהוא בהשפעה גשמיו' כך הוא ברוחניו' בהשפעת הרוחניו' כמו להשפיע אהבה ויראה שיש להם שרש וכח המשפיע אותם למטה וכידוע דמדת האהבה הנמשכת למטה בכללו' נ\"י הוא בא מכח עליון המשפיע להם התפעלות אהבה זאת בכל יום ויום והיינו ממחנה מיכאל<sup data-n=\"5282\">21</sup> שהוא מקור לכל המלאכי' של חסד ואהבה למעלה וכמו שאמרו מיכאל<sup data-n=\"5283\">22</sup> מקריב נשמו' ע\"ג המזבח כלומר מקריבן בדביקו' האהבה שמשפיע בהן ועד\"ז בהתפעלו' היראה בכנ\"י הנה היא נמשכת לישראל ממחנה גבריאל כו' ומטעם זה יובן מה שאו' קדושת יוצר לפני ק\"ש כדי לעורר שפע מן האוי\"ר שבמלאכי' לכנ\"י באמרם והאופנים כו' ויוכל להיו' עי\"ז התפעלו' אהבה בק\"ש באמרו ואהבת כו' ולהיות כן הרי המלאכי' גבוהי' מן הנשמו' וזהו שנק' מעי וכמ\"ש המו<sup data-n=\"5284\">23</sup> מעי לו רחם ארחמנו כו' שכדי שרחם ארחמנו להשפיע לו רוחניו' וגשמיו' בתחלה צריך להיו' המו מעי לו כנ\"ל.\n<b>אך</b> שרש נשמות ישראל למעלה גבוהי' המה מן המלאכי' כי הנה אמרו ישראל עלו במחשבה שלמעלה מן הדיבור והיינו בבחי' מהות ועצמו' אלקות שנק' גופא דמלכא ולא בבחי' שמו בלבד שהוא הדיבור ולזה הטעם דוקא בנשמו' אמרו בזוהר בהתפעלו' אהבה שלהם דהיינו לאשתאבא<sup data-n=\"5285\">24</sup> בגופא דמלכא דוקא כו' וביאור ענין",[["5275","14","<b>הבן יקיר לי אפרים</b>: ירמי' לא, יט."],["5276","15","<b>בזוהר</b>: ח\"ג רלד, ב ואילך."],["5277","16","<b>ע\"פ וכל קרבי</b>: ראה רשימות הצ\"צ לתהלים (יהל אור) קג, א. — הערת כ\"ק אדמו\"ר זי\"ע."],["5278","17","<b>וכמבואר במ\"א ע\"פ וכל קרביי את שם קדשו</b>: תהלים קג, א. ראה זהר לך פז, סע\"א (רעיא מהימנא) פינחס רלד, ב. סה\"מ תקס\"ה ח\"א ע' ו. מאמרי אדה\"ז ויקרא ח\"ב ע' תרסז. וש\"נ. בראשית ע' קיג. וש\"נ."],["5279","18","<b>שר של מים וכן שר של אש</b>: ראה רע\"מ פ' פינחס רכה, ע\"א. ספר הבהיר (ס\"ט) סי\"א הובא בהשמטות לזהר בראשית (סכ\"ט) רסג, א. במדב\"ר פי\"ב, ח. וש\"נ. מגלה עמוקות אופן קעז."],["5280","19","<b>אין לך עשב</b>: ראה ב\"ר פ\"י, ו. זח\"א רנא, א. מו\"נ ח\"ב פ\"י."],["5281","20","<b>גבוה מעל גבוה</b>: לשון הכתוב קהלת ה, ז."],["5282","21","<b>מיכאל. . של חסד</b>: ראה תקו\"ז ת\"ע קכו, א. קכז, א. שו\"ע אדה\"ז הל' תפלה סק\"כ, ס\"ב."],["5283","22","<b>מיכאל מקריב נשמו' ע\"ג המזבח</b>: זח\"א פ, א. ז\"ח לך כד, ב. וראה תוספות סוף מנחות."],["5284","23","<b>המו מעי לו רחם ארחמנו</b>: ירמי' לא, יט."],["5285","24","<b>לאשתאבא בגופא דמלכא</b>: זח\"א ריז, ב."]]],[2100990352,"גופא דמלכא הנה ידוע דהדיבור נק' מלך וכמ\"ש דבר<sup data-n=\"5286\">25</sup> מלך שלטון כו' והוא רק בחי' אותיו' ושם בלבד כידוע בביאור ענין<sup data-n=\"5287\">26</sup> יחודא תתא' דבשכמל\"ו וז\"ש מלכותך<sup data-n=\"5288\">27</sup> מלכו' כ\"ע וכידוע והנה המלאכי' ששרשם הוא רק מבחי' הדיבור וכמ\"ש בדבר ה' כו' וכנ\"ל א\"כ כשנא' בהם וצבא<sup data-n=\"5289\">28</sup> השמים לך &lt;שסב&gt;\nמשתחווי' אינם בטילי' ונכללי' רק בשרש מקור חוצבם שהוא בחי' הדיבור וע\"כ המה או' בקדוש' שלהם ג\"פ<sup data-n=\"5290\">29</sup> קדוש קדוש הוי' צבאו' כלומר קדוש<sup data-n=\"5291\">30</sup> ומובדל הוא ג' פעמי' בג' צמצומים עד שנעשה הוי' צבאו' כו' כי בחי' עצמותו אינו מושג להם לכך או' קדוש איה<sup data-n=\"5292\">31</sup> מקום כבודו כו' ואינם משיגי' רק שיש מי שהוא קדוש כו' וע\"כ אומרי' ברעש גדול כו' כי אינם משיגי' רק בבחי' שם בלבד וכמאמר וכולם משבחי' ומפארי' את שם כו' אבל ישראל נק' קדושים כמ\"ש והייתם<sup data-n=\"5293\">32</sup> קדושים כו' וכתיב קדש<sup data-n=\"5294\">33</sup> ישראל לה' כו' וכן כי עם<sup data-n=\"5295\">34</sup> קדוש אתה כו' והיינו כי בחי' קדש העליון שהוא בחי' המחשבה העליונ' הוא מקור חוצבם כנ\"ל וכשמתפעלים באהבה המה נכללים ובטילים במקור חוצבם שהוא בחי' עצמו' אלקו' שנק' קדוש ומובדל כו' והיינו לאשתאבא בגופא דמלכא ולא בבחי' שמו בלבד וד\"ל.\n<b>והנה</b> בק\"ש<sup data-n=\"5296\">35</sup> יש רמ\"ח תיבין נגד רמ\"ח איברי' דמלכא והתחלת הק\"ש שמע<sup data-n=\"5297\">36</sup> שם ע' כלומר בחי' שם בלבד שכלול מז' מדו' כאו\"א כלול מי' שמספרם ע' הוא מקור חיות כל העולמות כי רק בחי' שמו בלבד הוא מקור לכל העולמו' כמ\"ש הודו<sup data-n=\"5298\">37</sup> על ארץ ושמים כו' ושמע<sup data-n=\"5299\">38</sup> לשון הבנה כמו הסכת<sup data-n=\"5300\">39</sup> ושמע כו' והוא ענין ההתבוננו' להתבונן איך שהוי'<sup data-n=\"5301\">40</sup> אלקינו הוא הוי' אחד כו' ועי\"ז יבא לאשתאבא בגופא דמלכא ע\"י רמ\"ח תיבין שבק\"ש ברמ\"ח איברי' דמלכא שנק' גופא דמלכא וסופה של ק\"ש מורה ע\"ז באמרו אני<sup data-n=\"5302\">41</sup> ה' אלקיכם אלקיכם ממש אחר שנכללו כללו' נ\"י בגופא דמלכא ממש וד\"ל.\n<b>אך</b> הנה יש להבין מאחר שבק\"ש מגיעי' כללו' נ\"י להתאחד בגופא דמלכא ממש למה צריכי' ישראל לקבל אוי\"ר מן המלאכי' כמו בקדושת יוצר שלפני ק\"ש כנ\"ל הלא המלאכי' אינם מקבלים רק מבחי' שם בלבד שהוא רק בחי' הדיבור כנ\"ל.",[["5286","25","<b>דבר מלך שלטון</b>: קהלת ח, ד."],["5287","26","<b>ענין יחו\"ת</b>: ראה שער היחוה\"א פ\"ז. דרושי ק\"ש בסי' אמרי בינה וכו'. — הערת כ\"ק אדמו\"ר זי\"ע."],["5288","27","<b>מלכותך מלכו' כ\"ע</b>: תהלים קמה, יג."],["5289","28","<b>וצבא השמים לך משתחווי'</b>: נחמי' ט, ו."],["5290","29","<b>ג\"פ קדוש</b>: ישעי' ו, ג."],["5291","30","<b>קדוש ומובדל</b>: ראה תניא פמ\"ו (ע' סו)."],["5292","31","<b>איה מקום כבודו</b>: נוסח קדושת כתר."],["5293","32","<b>והייתם קדושים</b>: שלח טו, מ."],["5294","33","<b>קדש ישראל לה'</b>: ירמי' ב, ג."],["5295","34","<b>כי עם קדוש אתה</b>: ואתחנן ז, ו. פ' ראה יד, ב. כא."],["5296","35","<b>בק\"ש יש רמ\"ח תיבין. . דמלכא</b>: ראה פע\"ח שער הק\"ש פכ\"ה. תנחומא קדושים ו. וראה הנסמן בשערי זהר (לתנחומא שם) קסד, ד."],["5297","36","<b>שמע שם ע'</b>: ראה זהר (רעיא מהימנא) פינחס רלו, ב."],["5298","37","<b>הודו על ארץ ושמים</b>: תהלים קמח, יג."],["5299","38","<b>ושמע לשון הבנה</b>: ואתחנן ו, ד. ראה זהר (אידרא רבא) נשא קלח, ב."],["5300","39","<b>הסכת ושמע</b>: תבוא כז, ט."],["5301","40","<b>שהוי' אלקינו ה' אחד</b>: ואתחנן ו, ד."],["5302","41","<b>אני ה' אלקיכם</b>: שלח טו, מא."]]],[2100990353,"<b>אבל</b> הענין הוא דנשמות ישראל הרי המה מלובשים בגופים גשמיים ששרשם נמשך מנוגה דעשי' שמקבלי' מהמרכבה דפני<sup data-n=\"5303\">42</sup> ארי' פני נשר כו' כידוע דשרש חיות העופו' מפני נשר שבמרכבה דעשי' ושרש חיו' דחיות מבחי' פני ארי' שבמרכבה ושרש חיו' נפש הבהמות מבחי' פני שור כו' והנה נפש הבהמיו' שבגופים הגשמיים כלולה מכל הג' מדרגו' פני ארי' ופני שור ופני נשר כי יש בנפש הבהמיו' מבחי'<sup data-n=\"5304\">43</sup> בהמה ומבחי' חיה ומבחי' עוף אלא שהמה כלולי' בבחי' רוחניו' דנפש המשכלת כו' כי שרש נפש האדם הוא מבחי' פני אדם שבמרכבה דעשי' שכולל הכל וכמ\"ש ופני אדם לארבעתן כו' וד\"ל ולזה הטעם צריך האדם להמשיך על נפשו הבהמיו' אוי\"ר משרש מקור חוצבה במרכבה דעשי' מפני ארי' פני נשר כו' שהן מלאכי' דעשי' שמשפיעי' אוי\"ר למטה כנ\"ל כי נפש הבהמיו' מעכבת ומונעת את נפש האלקי' להיו' לה התפעלו' האהבה וצריך תחלה לעורר אוי\"ר לנפש הבהמיו' משרש מקור חוצבה ולכך עצה היעוצה מאנשי כה\"ג לומר שתים<sup data-n=\"5305\">44</sup> לפניה להזכיר קדושת המלאכי' כו' ואח\"כ בק\"ש תוכל הנפש האלקי' לאשתאבא בגופא דמלכא שהוא מקור חוצבה כי ישראל עלה במחשבה ובזה מתורץ הקושיא הנ\"ל וד\"ל.\n&lt;שסג&gt;\n<b>ובכל</b> זה יובן פי' הפסוק אכלתי<sup data-n=\"5306\">45</sup> יערי עם דבשי וידוע דדבשי<sup data-n=\"5307\">46</sup> הוא ק\"ש ויערי היינו בברכת יוצר שלפני ק\"ש דהנה בברכת יוצר אנו או' תתברך לנצח כו' בורא קדושים שבורא מלאכי' לאין שיעור וקץ וכמ\"ש היש<sup data-n=\"5308\">47</sup> מספר לגדודיו אלף אלפי' ישמשוני' כו' וכולם משבחי' ומפארי' ומקדישי' וממליכי' ברעש גדול וכו' וכל זה נמשל ליער כי המלאכי'<sup data-n=\"5309\">48</sup> נקראו עצי היער כמ\"ש אז<sup data-n=\"5310\">49</sup> ירננו כל עצי היער כו' וכמ\"ש בזוהר<sup data-n=\"5311\">50</sup> שנקראו עצי שטים עומדים כו' והנה עד\"מ עצי היער אשר הדבש נוטף מהם הרי הדבש עיקר והעץ טפל כי הדבש יש בו מתיקו' ותענוג מה שאין בעץ אך מ\"מ הנה הדבש גדל בעץ וממנו נוטף ויש בהכרח גם בעץ ממתיקו' הדבש קצת אלא שהוא בהגשמה מאחר שנק' יער\"ת הדבש וכך יובן הנמשל דההשתאבות בגופא דמלכא בכללו' נ\"י הרי הוא ע\"י בחי' מתיקו' ועונג האלקי כמ\"ש אז<sup data-n=\"5312\">51</sup> תתענג על ה' כו' וכמו הדבש שיש בו מתיקו' ותענוג וזהו בק\"ש דוקא כנ\"ל אך מה שיוכל להיו' אהבה בתענוגי' בק\"ש הוא בא אחר שקיבלו ישראל בנפשם הבהמיו' אוי\"ר מן המלאכי'<sup data-n=\"5313\">52</sup> שנק' עצי היער ועי\"ז תוציא הדבש שהוא המתיקו' בק\"ש וא\"כ יש עליי'",[["5303","42","<b>דפני ארי'. . ופני אדם לארבעתן</b>: ראה יחזקאל א, י."],["5304","43","<b>מבחי' בהמה. . חיה. . עוף</b>: ראה תניא רפל\"ט."],["5305","44","<b>שתים לפניה</b>: ברכות יא במשנה. וראה ירושלמי פ\"ק דברכות."],["5306","45","<b>אכלתי יערי עם דבשי</b>: שה\"ש ה, א."],["5307","46","<b>דדבשי הוא ק\"ש</b>: ראה לקו\"ת מטות פג, ד. צד, ב. ראה יט, ד. לב, א. דרך מצותיך קפח, א."],["5308","47","<b>היש מספר לגדודיו אלף אלפי' ישמשוני'</b>: איוב כה, ג. דניאל ז, יו\"ד."],["5309","48","<b>המלאכים נק' עצי היער</b>: ראה זהר פינחס רכו, סע\"א ואילך. וראה תו\"ח בראשית יט, א. מאמרי אדה\"א דברים ח\"ג ע' א'קיד. וש\"נ."],["5310","49","<b>אז ירננו כל עצי היער</b>: תהלים צו, יב."],["5311","50","<b>בזוהר. . עצי שטים עומדים</b>: זח\"ב קלט, א."],["5312","51","<b>אז תתענג על ה'</b>: ישעי' נח, יד."],["5313","52","<b>המלאכים. . היער. . הדבש. . ישראל</b>: ראה ג\"כ סה\"מ תקס\"ה ח\"ב ע' תשפא. מאמרי אדה\"ז על פרשיות התורה ע' תתמג. מאמרי אדה\"א ויקרא ח\"א ע' קלח. וש\"נ."]]],[2100990354,"למלאכי' ע\"י ישראל כי מסיבת המתיקו' באהבה רבה בתענוגי' בק\"ש גם המלאכי' מתעלי' ונכללי' בגופא דמלכא עד\"מ העצים שביער שמהם נוטף הדבש שנאכל גם העץ מפני מתיקו' הדבש כו' וזהו אכלתי יערי עם דבשי כלומר בשביל דבשי אכלתי גם יערי שהן המלאכי' כו' וד\"ל.\n<b>וזהו</b> שהתפלה נקראת סולם<sup data-n=\"5314\">53</sup> כמ\"ש בזוהר משום דכתיב וסולם<sup data-n=\"5315\">54</sup> מוצב ארצה וראשו מגיע השמיימה כו' כך התפלה מתחלת מתכלית וסוף המדרג' למטה כמו ברכת שלא עשני גוי כו' ומסתיימת בתכלית עליי' המדרגה בק\"ש לאשתאבא בגופא דמלכא כנ\"ל והיינו כמו הסולם שרגליו בארץ וראשו מגיע השמיימה וד\"ל ומלאכי אלקי' עולים ויורדים בו היינו שעולי' בסולם זה דתפלה ג\"כ השמיימ' לאשתאבא בגופא דמלכא עם כללו' נ\"י וגם יורדים בו אחר עלי' זו והיינו בתפלת י\"ח שמביאי' ירידת אור ושפע למטה בכללו' נ\"י כמו רפאינו ברך עלינו וכיוצא וכמו שידוע דכל מלאך יש לו שליחו' בפ\"ע ואין<sup data-n=\"5316\">55</sup> מלאך א' עושה ב' שליחו' כמו במלאכי' דאברהם רפאל<sup data-n=\"5317\">56</sup> לרפאו' את אברהם ומיכאל<sup data-n=\"5318\">57</sup> לבשר את שרה בלידת יצחק כי פקידת הבנים הוא ע\"י מיכאל כו' וא\"כ הרי ההתחלה ע\"י המלאכי' כמו בקדוש' יוצר לשבר חומריו' נפש הבהמיו' וגם תכלית הדבר הוא ע\"י המלאכי' להביא השפע למטה וז\"ש עולים ויורדים בו והכל בסולם דתפלה לפי שמוצב ארצה וראשו מגיע השמיימה כו' וד\"ל.\n<b>וזהו</b> יסובבנהו כו' יצרנו כאישון עינו. פי' אישון עינו הוא בחי' בת עין ונק' ג\"כ בבת עינו והוא השחור<sup data-n=\"5319\">58</sup> שבעין שהיא רק כנקודה א' והלובן הוא סביבה והנה ידוע שהראיה אשר בעין הוא דוקא בשחור שבעין ולא בלובן אשר סביבה כו' והנמשל יובן מזה למעלה דכנ\"י נק' אישון עינו מצד בחי' בירור הנפש הבהמיו' שמלביש ומחשיך אור הנפש האלקי' וכשמתהפך רע לטוב וחשוכא לנהורא ע\"י אוי\"ר בברכת יוצר כנ\"ל אזי גורמי' עיקר הארת גילוי אלקות כח הראי' הרוחניו' האלקית כמו עד\"מ שאור המאיר בעין הוא &lt;שסד&gt;\nבשחור שבעין דוקא להיותו המסתיר האור כו' וד\"ל.\n<b>וז\"ש</b> השקיפה ממעון קדשך כו' והשקפה והבטה זו היא ע\"י ישראל דוקא שעלו במחשבה כנ\"ל שהמוח ממשיך כח הראי' בעין אבל באישון עין דוקא כנ\"ל עיקר אור גילוי השקפה זאת וזהו יצרנו כאישון עינו והיינו ע\"י סדר התפלה כנ\"ל וד\"ל.",[["5314","53","<b>סולם כמ\"ש בזהר</b>: ח\"א רסו, ב."],["5315","54","<b>וסולם מוצב ארצה</b>: ויצא כח, יב."],["5316","55","<b>ואין מלאך</b>: ב\"ר רפ\"כ."],["5317","56","<b>רפאל לרפאו' את אברהם</b>: רש\"י וירא יח, ב. וראה ב\"מ פו, ב."],["5318","57","<b>ומיכאל לבשר את שרה</b>: שם."],["5319","58","<b>השחור שבעין</b>: ראה ויק\"ר פל\"א, ח. לקו\"ת האזינו עח, ג. לקו\"ש ח\"ט ע' 64 בהערות שם."]]],[2100990355,"<b>והנה</b> בגלות<sup data-n=\"5320\">59</sup> נאמר עורה<sup data-n=\"5321\">60</sup> למה תישן כו' וכידוע המאמר בזוהר<sup data-n=\"5322\">61</sup> דאית גבינין דמכסיין על עיינין כו' והענין הוא שא\"א להיו' גילוי אור בכלי העין לפי שהחיצוני' מסתירי' וע\"כ מסלק בחי' ההשגחה הפנימי' כו' ולכך הגבינין הם מכסיין על עיינין כו' וה\"ז כמשל השינה שהעינים סגורים כו' משא\"כ בזמן בהמ\"ק דכתיב עיני<sup data-n=\"5323\">62</sup> ה' אלקיך ב\"ה כו' וגם בזמן הגלות אנו מבקשים פקח<sup data-n=\"5324\">63</sup> עיניך וראה כו' פקיחה זו הוא פתיחת כלי העין להביט באור כח ההשגחה הפנימי' כו' משום שנא' הנה<sup data-n=\"5325\">64</sup> לא ינום ולא ישן שומר ישראל כו' דהיינו כאשר צריך להיו' שומר לישראל מן החיצונים אזי לא ינום ולא ישן וכתיב אז עיני ה' אל צדיקי' וכן עין ה' אל יריאיו כו' והיינו יצרנו כאישון עינו וד\"ל.\n<b>והנה</b> פסוק זה דיסובבנהו<sup data-n=\"5326\">65</sup> כו' על חג הסוכות הוא אומר שהקדב\"ה סובב לכנ\"י בבחי' אור מקיף שבסכך כמ\"ש ה'<sup data-n=\"5327\">66</sup> צילך כו' ומקיפי' הללו דז' ימי הסוכות הן הנק' שומרים לשמור לכנ\"י והיינו יסובבנהו יבוננהו יצרנו כאישון עינו אך הנה כדי לבא לבחי' מקיפי' הללו דסוכות צריך להיות תחלה עי\"ת מר\"ה עד יו\"כ וכידוע דההתחלה הוא בר\"ה והגמר נעשה בסוכו' וכמ\"ש שמאלו<sup data-n=\"5328\">67</sup> תחת לראשי בר\"ה נאמר וימינו תחבקיני היינו בסוכות כו' וכמ\"ש<sup data-n=\"5329\">68</sup> במ\"א והנה מטעם זה קדם לומר בפסוק שלפני זה הפסוק באמרו ימצאהו<sup data-n=\"5330\">69</sup> בארץ מדבר ובתוהו יילל ישימון פי' בחי' מדבר היינו מה שהאדם משפיל א\"ע בתבירו דלבא בעי\"ת ובפרט באמרו הוידויים ביו\"כ אשמנו בגדנו גזלנו כו' תעבנו תעינו כו' וכיוצא בזה שהוא מבזה ומשפיל א\"ע במאד עד שהוא נמשל למדבר ושממה וארץ ציה כו' אחר שמרשיע א\"ע בכל החטאי' והעוונו' ששרש אחיזתם בהיכלות הקליפו' שמשכנם במדבר כידוע.\n<b>וזהו</b> ימצאהו בארץ מדבר בעי\"ת וביו\"כ לכללו' נ\"י כי הגם שאין<sup data-n=\"5331\">70</sup> באדם כל החטאי' המפורשי' בוידוי מ\"מ הרי כל<sup data-n=\"5332\">71</sup> ישראל ערבים זה בזה וצריך להתוודו' מפני אותו חלק שיש בו מכללו' נ\"י אחר שכללו' נ\"י<sup data-n=\"5333\">72</sup> הם כמו קומה",[["5320","59","<b>בגלות</b>: כ\"ה ג\"כ בהמאמר של הצ\"צ. והערה שם מכ\"ק אדמו\"ר זי\"ע: נ\"א: והנה בזמן שאין ביהמ\"ק קיים — כנראה השינוי בא מפני יראת הממשלה, וע\"ד הנמצא בכמה כתבים שבמקום גלות כתוב ”ג\", כו'. וכיו\"ב."],["5321","60","<b>עורה למה תישן</b>: תהלים מד, כד."],["5322","61","<b>בזהר דאית גבינין דמכסיין</b>: ראה בכ\"ז זח\"ג קכט, ב. שם רפט, א."],["5323","62","<b>עיני ה' אלקיך בה</b>: עקב יא, יב."],["5324","63","<b>פקח עיניך. . פקיחה</b>: ראה דניאל ט, יח. וראה זהר (אדרא רבא) נשא קכט, ב."],["5325","64","<b>הנה לא ינום ולא ישן</b>: תהלים קכא, ד."],["5326","65","<b>דיסובבנהו. . חג הסוכות</b>: ראה לקו\"ת ד\"ה שיר המעלות ממעמקים ספ\"ב."],["5327","66","<b>ה' צלך</b>: תהלים קכא, ה."],["5328","67","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו."],["5329","68","<b>וכמ\"ש במ\"א</b>: לקו\"ת דברים מח, ג. ועוד. — הערת כ\"ק אדמו\"ר זי\"ע."],["5330","69","<b>ימצאהו בארץ מדבר</b>: האזינו לב, יו\"ד."],["5331","70","<b>שאין באדם כל החטאי'</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקצא-ב. מאמרי אדה\"א קונטרסים ע' תח."],["5332","71","<b>כל ישראל ערבים זה בזה</b>: ראה תו\"כ בחוקותי כו, לז, שבועות לט, סע\"א."],["5333","72","<b>נ\"י הם כמו קומה שלימה</b>: ראה מאמרי אדמו\"ר האמצעי ויקרא ח\"ב ע' א'תערה. וש\"נ."]]],[2100990356,"שלימה כידוע הרי כלולי' כל או\"א מחבירו כמו שכלולי' כל האיברי' באדם זה מזה עד שמרגיש הראש כאב ומכה שברגל כידוע ואדרבה אותן הנשמו' שהן מבחי' הראש והמוחין שבכנ\"י הנקיים ביותר מכל נדנוד חטא ועון יש להרגיש ביותר מן החטאי' שיש בעקביי' כמו שהראש מרגיש ביותר כאב הרגל משאר האיברי' כו' ויש להם להתוודות ולהתמרמר ביותר באמרם אשמנו כו' על הכאב ומכה מפגימת העון ועי\"ז הוידוי מעוררי' רחמי' רבים העליונים וכמ\"ש כרוב<sup data-n=\"5334\">73</sup> רחמיך מחה פשעי כו' וכתיב רחמיך<sup data-n=\"5335\">74</sup> רבים ה' כמשפטך חייני פי' מפני בחי' רחמיך הרבים העליוני' הנק' רחמי' הגדולי' שמתפשטי' גם על עולמו' היותר עליונים כמו על התחתוני' משום דכולא<sup data-n=\"5336\">75</sup> &lt;שסה&gt;\nקמי' כלא בהשווא' א' כו' ועל כולם נמשך הרחמי' בהשווא' א' כו' וע\"כ גם במקום הצמצום והדין למטה מטה הנק' משפטיך גם שם חייני תוכל להחיות שם ולהציל מן הדין ע\"י בחי' רחמי' רבים שהן בחי' מקיף וסובב להקטן כגדול כו' וזהו ובתוהו ילל כו' דהיינו ע\"י הוידוי כנ\"ל מעורר המקיף דרחמי' רבים ואזי יסובבנהו להיות ימינו תחבקיני בסוכו' שנמשך הרחמי' למטה להיו' ה' צילך ממש כו' וד\"ל והיינו יצרנו כאישון עינו שהוא בחי' השגחה והשקפה לטוב גם במקום הצמצום והדין כמו ע\"י הרחמי' רבי' שנמשך האור גם במקום החושך של החיצוני' והוא בחי' השחור שבעין הנק' אישון בת עין כנ\"ל ובה הוא עיקר כח הראי' לפי שע\"י האישון מתפשטת כח הראי' למרחוק להיותה מצמצמת האור כמשל כלי ההבטה כו' (וזהו שאמר במשה וראיתה אותה כו' כי<sup data-n=\"5337\">76</sup> מנגד תראה את הארץ כו' כי משה<sup data-n=\"5338\">77</sup> רעיא מהימנא הי' משגיח בארץ מרחוק בבחי' הבטה דראיה בלבד לפי שראי' שבעין נמשכת למרחוק ולהיו' מעלת משה גבוה הרבה מא\"י ע\"כ רק בבחי' ראי' השגיח עלי' ובראי' המשיך כי שרש משה מבחי' הראי' דחכמה וכמ\"ש וירא<sup data-n=\"5339\">78</sup> ראשית לו כו' וכידוע וד\"ל).\n<b>וזהו</b> עיקר ענין תשובה שבעי\"ת וכמ\"ש שובה<sup data-n=\"5340\">79</sup> ישראל עד ה' אלקיך כו' פי' כדי שיהי' הוי' אלקיך ע\"י בחי' רחמי' רבים הנ\"ל שע\"י הוידוי' כנ\"ל וכמ\"ש ומודה<sup data-n=\"5341\">80</sup> ועוזב ירוחם ופי' ירוחם היינו כמ\"ש בך<sup data-n=\"5342\">81</sup> ירוחם יתום דהנה היתום בגשמיות היינו מי שאין לו אב וגם<sup data-n=\"5343\">82</sup> ברוחניות ע\"י העוונו' וחטאי' נפסק ניצוץ אור האלקי מלהאיר על הנפש ונק' הנפש יתום שאין לו אב כי נסתלק הארת אבא ממנו כמ\"ש כי<sup data-n=\"5344\">83</sup> אתה אבינו כו' וע\"כ אנו מבקשי' אבינו מלכינו שיחזור לנו להיו' לאב כו' וזהו בך ירוחם יתום בך דוקא ירוחם ממילא היתום שאין לו אב כו' ולא כתיב אתה מרחם",[["5334","73","<b>כרוב רחמיך מחה פשעי</b>: תהלים נא, ג."],["5335","74","<b>רחמיך רבים ה' כמשפטיך חייני</b>: תהלים קיט, קנו."],["5336","75","<b>כולא קמי' כלא</b>: נסמן לעיל ע' תרסט."],["5337","76","<b>כי מנגד תראה את הארץ</b>: האזינו לב, נב."],["5338","77","<b>משה רעי' מהימנא</b>: ראה זהר וירא קו, א. שמות ח, ב. ועוד. פתיחתא דאיכ\"ר כד. יל\"ש סוף רמז תתקצז. תניא פמ\"ב."],["5339","78","<b>וירא ראשית לו</b>: ברכה לג, כא."],["5340","79","<b>שובה ישראל עד הוי' אלקיך</b>: הושע יד, ב."],["5341","80","<b>ומודה ועוזב ירוחם</b>: משלי כח, יג."],["5342","81","<b>בך ירוחם יתום</b>: הושע יד, ד. וראה גם מאמרי אדה\"א דברים ח\"ד ס\"ע א'קסח ואילך."],["5343","82","<b>וגם ברוחניות</b>: ראה לקו\"ת דברים פג, ב. — הערת כ\"ק אדמו\"ר זי\"ע."],["5344","83","<b>כי אתה אבינו</b>: ישעי' סג, טז."]]],[2100990357,"יתום כו' אלא ירוחם לפי שנעשה לו לאב באמרו אבינו מלכינו אחר הוידוי שמעורר הרחמי' כנ\"ל וזהו דוקא ע\"י התשובה בלב לאשתאבא בגופא דמלכא וזהו פי' ב\"ך כו' וזהו שביוה\"כ אין בו אכילה ושתי' כו' אלא לאשתאבא בגופא דמלכא ע\"י התשובה בלב כו' ועי\"ז יבא אור המקיף בסוכו' כנ\"ל וד\"ל.\n<b>ואחר</b> כל הנ\"ל יובן המשך סדר הפסוק הזה דיסובבנהו כו'. דהנה כתיב כי<sup data-n=\"5345\">84</sup> נער ישראל ואוהבהו כו' וכתיב הבן<sup data-n=\"5346\">85</sup> יקיר לי אפרים כו' ילד שעשועי' כו' והנה עד\"מ הנער והילד הקטן שאין בו דעת ושכל עדיין שיוכל אביו לקבל עונג ושעשועים מטיב שכלו ודעתו הנה האב עושה עמו שחוק והיתול ומשחק עמו ובאותו השחוק שהתינוק משחק עמו משתעשע האב בו ומקבל מזה עונג גדול וזה נק' ילד שעשועי' שמפני הילדו' אין לאב בו אלא שעשועי' בשחוק שמשחק עמו אבל אחר שיגדל הנער אין האב משחק עמו אלא מדבר עמו ומשתעשע מטוב שכלו ודיבורו וכיוצא וזה אינו נק' ילד שעשועי' כו' כידוע והנמשל יובן למעלה בכללו' נ\"י שנק' ילד שעשועי' בבחי' הקטנו' המוחי' בר\"ה ויו\"כ כשמשפילין א\"ע בעי\"ת בוידוי אשמנו כו' עד שאין בהם שום בחי' טוב מצד עצמם כלל ואז הם בתכלית הקטנו' כמשל הילד והנער שאין בו דעת עדיין כלל וא\"כ אין אתעדל\"ת שלהם מעוררת &lt;שסו&gt;\nאתעדל\"ע כלל אחר שאין בהן כלום ממעשה הטוב אלא במה הם מעוררי' אתעדל\"ע במה שנמשך עי\"ז בחי' שעשועי' העליונים שלא מצד הדעת וההשגה אלא כמשל האב שמשתעשע בבנו הילד בשחוק בלבד כנ\"ל אחר שהן נעשי' כמו הילד הקטן עד\"מ אז ממילא נק' ילד שעשועי' וכמ\"ש הבן יקיר לי כו' ילד שעשועי' המו מעי לו רחם ארחמנו ברחמי' הרבי' כנ\"ל.\n<b>והיינו</b> בחג הסוכות שנמשכו המקיפין וכמ\"ש כי נער ישראל ואוהבהו שהאהבה באה בבחי' מקיף בלתי הכנת כלי המקבלי' כי אין אתעדל\"ת מגיע לשם כלל והוא שרש ענין התגלות השמחה הגדולה בחג<sup data-n=\"5347\">86</sup> הסוכות שנק' זמן שמחתינו כידוע לפי שנמשכי' השעשועי' הגדולי' עד\"מ התגלו' שמחת האב כשמשתעשע ומשחק עם בנו הילד כו' כנ\"ל וד\"ל.\n<b>וזהו</b> ימצאהו בארץ מדבר שנק' שם ילד כמ\"ש זכרתי<sup data-n=\"5348\">87</sup> לך חסד נעורייך לכתך אחרי במדבר כו' ואזי נמשך בחי' השעשועי' בבחי' מקיף והיינו יסובננהו במקיפי' דסכך ודפנו' הסוכה בסוכו' וכמ\"ש וימינו<sup data-n=\"5349\">88</sup> תחבקיני כנ\"ל וד\"ל, ופי' יבוננהו היינו לשון בינה ג\"כ כי הנה בנין ובינה הכל ענין א' דהנה ידוע פי' בינה<sup data-n=\"5350\">89</sup> בן י\"ה שהוא ענין תולדות המדו' אוי\"ר שנק' בן ובת שנולדו מי\"ה שהן",[["5345","84","<b>כי נער ישראל ואוהבהו</b>: הושע יא, א."],["5346","85","<b>הבן יקיר לי אפרים</b>: ירמי' לא, יט."],["5347","86","<b>בחג הסוכות שנק' זמן שמחתינו</b>: בנוסח הקידוש והתפלה."],["5348","87","<b>זכרתי לך חסד נעורייך</b>: ירמי' ב, ב."],["5349","88","<b>וימינו תחבקני</b>: שה\"ש ב, ו."],["5350","89","<b>בינה בן י\"ה</b>: זהר (רעיא מהימנא) נשא קכג, סע\"א. מאמרי אדה\"א דברים ח\"א ע' קלא."]]],[2100990358,"חו\"ב ועיקר המוליד היינו בינה<sup data-n=\"5351\">90</sup> הנק' אם הבנים כידוע ויש לך אדם שגם שיתבונן בבינה לא יוליד אהבה והתפעלו' וע\"ז אמר יבוננהו שיוכל להוליד מבינתו אהבה כל השנה וזה נק' ג\"כ בנין כי הבן נק'<sup data-n=\"5352\">91</sup> בנין האב המוליד כו' וכל זה מפני שיסובבנהו ויחבקנו בבחי' מקיף וכמשל החובק לחבירו שאינו מניחו ליפרד לעולם כו' כך המקיפי' דבינה בסכך ודפנו' גורמי' שיוכל להוליד מבינתו כל השנה ולא יפרד לעולם כו' וזהו יסובבנהו ואח\"כ יבוננהו להיו' נק' ב\"ן י\"ה כו' וד\"ל.\n<b>ואח\"כ</b> יצרנו כאישון עינו פי' כי עד\"מ הנ\"ל בבן<sup data-n=\"5353\">92</sup> הקטן שמשתעשע בו האב הנה עיקר השעשועי' הוא כשלוקחו מעל הארץ ונותנו על זרועותיו להיות סמוך לפני האב ומשחק ומשתעשע בו כך כתיב קחם<sup data-n=\"5354\">93</sup> על זרועתי כו' והיינו בשמיני עצרת שאחר החיבוק בז' ימי החג שמגביהו לכנ\"י על זרועותיו ומשתעשע בו והוא ענין שמחת תורה כו' ואזי נא' יצרנו כאישון עינו לפי שמדבקו לתינוק ומקרבו לפני האב לעוצם החביבו' עד שנעשה יקר וחביב כבבת עינו ממש וע\"כ אמרו כל הנוגע בהם כאילו נוגע בבבת עינו כו' עד שכל השגחה והשקפה מן השמים הוא ע\"י ישראל לפי שישראל עלה במחשבה במוח האב כמ\"ש בני בכורי כו' הבן יקיר לי כו' ולכך יצרנו כאישון עינו וד\"ל.\n<b>ומה</b> שאמר כאישון דוקא הכוונה הוא ע\"י המצו' שמלובשי' בעניני' גשמיי' כמו המזוזה על הקלף כו' לפי שנמשך קדוש' העליונה גם במקום נמוך וזה נק' אישון מטעם שהוא החושך ובה דוקא עיקר התפשטות כח הראי' כנ\"ל הטעם והיינו יצרנו כאישון עינו ע\"י המצו' דוקא שהרי נא' בהן ג\"כ בחי' מקיף כמ\"ש כצנה<sup data-n=\"5355\">94</sup> רצון תעטרנו ואזי נא' כי<sup data-n=\"5356\">95</sup> אתה ה' מחסי כו' על כפים ישאונך כו' וד\"ל.",[["5351","90","<b>בינה הנק' אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. פרדס שער (כג) ערכי הכינויים מערכת אם הבנים. לקו\"ת דרושים לשמע\"צ פח, ד."],["5352","91","<b>נק' בנין</b>: ראה אבן עזרא (לך טז, ב). ב\"ר שם. — הערת כ\"ק אדמו\"ר זי\"ע."],["5353","92","<b>בבן הקטן</b>: ראה ג\"כ לקו\"ת צו טו, ד. ועוד."],["5354","93","<b>קחם על זרועתי</b>: הושע יא, ג."],["5355","94","<b>כצנה רצון תעטרנו</b>: תהלים ה, יג."],["5356","95","<b>כי אתה ה' מחסי כו' על כפים ישאונך</b>: תהלים צא, ח. יא."]]],[2100990359,"<h3>תורה צוה לנו משה</h3>\n<b>בעזר\"ה שמחת תורה</b>\n&lt;שסז&gt;\n\nתורה<sup data-n=\"5357\">1</sup> צוה לנו משה מורשה קהלת יעקב ויהי בישורון מלך וכו'<sup data-n=\"5358\">2</sup>. ויש להבין מהו מורשה וכי התורה ירושה היא לנו מאבותינו והלא כתיב לא<sup data-n=\"5359\">3</sup> את אבותינו בלבד כו' כי אותנו כו'<sup data-n=\"5360\">4</sup> כי את אשר ישנו פה ואת אשר איננו פה כו'. וגם מהו סמיכת הפסוק ויהי בישורון כו'.\n<b>אך</b> הנה ידוע דכל המצות<sup data-n=\"5361\">5</sup> מעשיות נתלבשו בענינים גשמיים מדצ\"ח דנוגה דעשי' כמו מצות ציצית בצמר החי דכבשי' והקרבנות מבהמות ובע\"ח ותרומות ומעשרו' מן התבוא' הצומח וכיוצא באלה כל המצות הרי המה נעשות בדברים הגשמיים שהן תחת ממשלת בחי' נוגה וידוע בספרי<sup data-n=\"5362\">6</sup> הקבלה שבנוגה נפלו ז' מלכים שמלכו בארץ אדום דכתיב בהו וימלוך<sup data-n=\"5363\">7</sup> וימת ומיתה זו היינו בחי' נפילה ממדרגה כמ\"ש בע\"ח לפי שנפלו ז' המלכים ממדרגתם כמו שהיו בבחי' הקדוש' האלקי' וירדו למטה ונתהווה מהם ז'<sup data-n=\"5364\">8</sup> מדות רעות שהן ז' האומו' הכנעני והחתי כו' ומהם נתהוו' שרש מציאת בחי' הרע שבנוגה וע\"כ יש בחי' רע בכל הדברי' שתחת ממשלת קליפ' נוגה מחמת נפילת ז' מלכי' דתוהו בז' מדות רעות כמו התאוה והכעס והגאוה כו' ולזה הטעם כדי לתקן הז' מלכי' הללו ולברר אותם ניתן לישראל ז' האומו' הכנעני והחתי כו' בבחי' ירושה כמ\"ש<sup data-n=\"5365\">9</sup> בכל התורה על ארץ הכנעני וירשתם<sup data-n=\"5366\">10</sup> אותה לרשת אותה וכתיב וירשתם<sup data-n=\"5367\">11</sup> גוים כו' לפי שישראל<sup data-n=\"5368\">12</sup> עלה במחשבה בבחי' התיקון המברר כידוע ויש ביכולתם לברר ולתקן ז' המלכי' ע\"כ ניתנו להם לירושה להוציא מהם חלקי הטוב כו'.",[["5357","1","<b>תורה צוה לנו משה</b>: הנחת כ\"ק אדמו\"ר האמצעי. נעתק מגוכתי\"ק 1025 (קז, א).\nמאמר זה נדפס ג\"כ באוה\"ת ברכה כרך ד ע' א'תתנה. ושם ע' א'תתמח נדפס הגהות (ומחולק לסעיפים) מכ\"ק אדמו\"ר הצ\"צ על מאמר זה. ובכרך ו ע' ב'תקמח נדפס עוד הגהות מכ\"ק אדמו\"ר הצ\"צ [מגוכתי\"ק 1122].\nהנחת ר\"מ בן כ\"ק אדמו\"ר הזקן נדפס לקמן ע' תשנג.\nהנחה אחרת מהביאור נדפס לקמן ע' תשסו."],["5358","2","<b>תורה צוה לנו משה. . ויהי בישורון מלך</b>: ברכה לג, ד. ה."],["5359","3","<b>לא את אבותינו בלבד</b>: ראה דברים ה, ג — לא את אבותינו כרת ה' את הברית הזאת כי אתנו אנחנו אלה פה היום. וראה נצבים כט, יג — ולא אתכם לבדכם אנכי כרת את הברית הזאת."],["5360","4","<b>כי את אשר ישנו פה</b>: ראה נצבים כט, יד."],["5361","5","<b>המצות מעשיות. . דעשי'</b>: ראה לקו\"ת בלק סז, א ואילך."],["5362","6","<b>בספרי הקבלה שבנוגה נפלו ז' מלכים. . כמ\"ש בע\"ח</b>: ראה זהר (אדרא רבא) נשא קכח, א. ע\"ח שער הכללים פ\"א. שם (שער דרושי הנקודות) ש\"ח פי\"ד."],["5363","7","<b>וימלוך וימת</b>: וישלח לו, לב ואילך."],["5364","8","<b>ז' מדות רעות. . ז' האומות</b>: ראה גם ביאוה\"ז תשא נג, ג. שערי תשובה קג, ד. ד\"ה אל תצר את מואב במאמרי אדה\"א דברים."],["5365","9","<b>כמ\"ש בכל התורה. . וירשתם אותה לרשת אותה. . וירשתם גוים</b>: באוה\"ת שם ע' א'תתמט: ז' עממין בבחי' ירושה כמ\"ש בפ' לך ט\"ו ז', לתת לך את הארץ הזאת לרשתה, וס\"פ תולדות לרשתך את ארץ מגוריך אשר נתן אלקים לאברהם, וירשתם גוים גדולים."],["5366","10","<b>וירשתם אותה לרשת</b>: ראה מסעי לג, נג."],["5367","11","<b>וירשתם גוים</b>: עקב יא, כג."],["5368","12","<b>שישראל עלה במחשבה</b>: ראה ב\"ר פ\"א, ד."]]],[2100990360,"<b>וזהו</b><sup data-n=\"5369\">13</sup> ענין המלך השמיני שנק' הדר<sup data-n=\"5370\">14</sup> מלשון פרי<sup data-n=\"5371\">15</sup> עץ הדר רומז לישראל שנק' פרי עץ הדר משום שנא' הוד<sup data-n=\"5372\">16</sup> והדר לפניו וכתיב הדר<sup data-n=\"5373\">17</sup> הוא לכל חסידיו דוקא וכמ\"ש ישראל<sup data-n=\"5374\">18</sup> אשר בך אתפאר כו' וז' המלכי' הנ\"ל ניתנו לירושה למלך השמיני הנק' הדר המתקן אותם ומברר אותם שהרי בכל המלכי' נא' וימלוך וימת ובמלך השמיני לא נא' וימלוך וימת כו' וכך ישראל למטה הם היורשים לארץ אדום מטעם הנ\"ל וירושה זו מצד הדין היא שהרי ישראל נקראי' אחים לאדום כמ\"ש במלאכים ששלח משה לאדום כה<sup data-n=\"5375\">19</sup> אמר אחיך ישראל כו' (אלא שעשו<sup data-n=\"5376\">20</sup> יצא ראשון לפי שהקליפ' קדמה לפרי כו' וכמ\"ש במ\"א וד\"ל).\n<b>והנה</b> להבין בתוספת ביאור ענין ז' המלכי' הנ\"ל יש להקדים תחלה ע\"ד ענין מאמר רז\"ל אין<sup data-n=\"5377\">21</sup> לך עשב מלמטה שאין לו מזל כו' וכתיב גבוה<sup data-n=\"5378\">22</sup> מעל גבוה שומר וגבוהים עליהם דהנה ידוע שיש לכל דבר מחלקי דצח\"ם שרש ומקור ברוחניות הנק' בשם שרים כמו שר של מים שר של אש וכן יש שר של חכמה ושר של פרנסה וכיוצא ונמצא שכל חיות הגשמיות שבארץ וכל אשר בה על כולם יש שרים למעלה ואותן השרים יש גבוהים עליהם שנחשבי' לגביהם רק כחומר לגבי הצורה ונק' שמרי האופני' כו' ועד\"ז גבוה מעל גבוה שומר כו' עד רום המעלות אך הנה שרש ומקור הראשון לע' שרים דנוגה הן בחי' ז' מלכי' הנ\"ל שמלכו בארץ אדום ומתו שנפלו ממעמדם ומדרגתם בבחי' האצי' שהיו עומדים מו' ימי בראשית בבחי' &lt;שסח&gt;\nהנצחיות דא\"ס כי אורם נאצל מעצמו' אור המאציל כידוע וירדו למטה מטה להיו' מקור לע' שרים בכלל להיו' מהם קיום וחיות לדצח\"ם הגשמיים בתערובו' טו\"ר ע\"י ז' המדות הרעות כנ\"ל וזהו שנא' בהם וימלוך וימת לפי שהמיתה נסתעפה מהם והוא ענין בחי' הכליון וההפסד שיש בכל הנבראי' שהן הווים ונפסדים כמ\"ש<sup data-n=\"5379\">23</sup> בזוהר ע\"פ קץ כל בשר לפני כו' וד\"ל.\n<b>והנה</b> שרש המרכבה דפני<sup data-n=\"5380\">24</sup> אריה כו' הנושאות את הכסא הכבוד שהוא בחי' מלכו' דאצי' הוא מז' המלכי' הנ\"ל שנקראו בשם בהמות וחיות כידוע וידוע המאמר והחיות<sup data-n=\"5381\">25</sup> נושאות ומנושאות עם כסא וזעות מחיל כסא לפי שהאימה והפחד שנמשך",[["5369","13","<b>וזהו ענין המלך השמיני</b>: ראה ג\"כ לקו\"ת תזריע כ, ד. תו\"ח בראשית ח, א."],["5370","14","<b>הדר מלשון פרי עץ הדר</b>: באוה\"ת שם: ועיין מד\"ר פ' אמור פ\"ל ע\"פ ולקחתם לכם פרי עץ הדר."],["5371","15","<b>פרי עץ הדר</b>: אמור כג, א."],["5372","16","<b>הוד והדר לפניו</b>: דברי הימים-א טז, כז."],["5373","17","<b>הדר הוא לכל חסידיו</b>: תהלים קמט, ט."],["5374","18","<b>ישראל אשר בך אתפאר</b>: ישעי' מט, ג."],["5375","19","<b>כה אמר אחיך ישראל</b>: חקת כ, יד."],["5376","20","<b>שעשו יצא ראשון לפי שהקליפה קדמה לפרי וכמ\"ש במ\"א</b>: ראה תולדות כה, כה. ראה זהר (סבא) משפטים קח, ע\"ב. תו\"ח וישלח קסא, ב. קפה, א. קפט, ב."],["5377","21","<b>אין לך עשב מלמטה</b>: ראה ב\"ר פ\"י, ו. השמטות לזח\"א רנא, א. זהר תרומה קעא, ב. ועוד."],["5378","22","<b>גבוה מעל גבוה שומר</b>: קהלת ה, ז."],["5379","23","<b>כמ\"ש בזוהר ע\"פ קץ כל בשר לפני</b>: ראה זהר בראשית נד, א. ויצא קמח, א. תרומה קלד, סע\"א ואילך."],["5380","24","<b>דפני אריה כו'</b>: יחזקאל א, י."],["5381","25","<b>והחיות נושאות ומנושאות עם כסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד."]]],[2100990361,"עליהם מבחי' מלכותו ית' כמ\"ש מלכותך<sup data-n=\"5382\">26</sup> מלכו' כ\"ע לא יכיל הכלי שלהם כלל להיותו בא עליהם בבחי' גילוי גדול יותר מבתחתונים לכך אין בכחם להכיל ולעצור כח מפני פחד הגדול והנורא הזה עד שהם זעות מחיל כסא וכמארז\"ל מזיעתן<sup data-n=\"5383\">27</sup> של חיות כו' כי הזיעה נופלת דוקא כאשר כח האדם לא יוכל שאת את הפחד כו'.\n<b>וזהו</b> מאמר ומוראך<sup data-n=\"5384\">28</sup> עליהם בבחי' מקיף כי לא יכילוהו בהשגה כו' ואמנם הנה אע\"פ שבחיות הקדש נמשך האימה והפחד בגילוי גדול מ\"מ עיקר אור גילוי מדת מלכותו ית' על ישראל למטה אע\"פ שלא נמשך עליהם האימה כ\"כ, כי הנה במלך ב\"ו עד\"מ יש ב' ענינים במלכותו הא' התפשטו' אימתו ופחדו והב' ענין הדר כבוד מלכותו ותפארת גדולתו דהיינו כשהמלך במסיבו יושב בבגדי הוד מלכות המהדרים ומייפים את כבוד מלכותו לפני השרים והעם שזהו עיקר ענין המלכות אבל התפשטו' אימתו הוא דבר טפל וממילא בא כו'.\n<b>וכך</b> יובן במלכותא דרקיע דהנה הגם שנא' מלכותך מלכו' כ\"ע ונתפשט בחי' האימה ופחד על כל הנבראי' דבי\"ע שמקבלי' עליהם עול מלכותו באימה וכמאמר וכולם<sup data-n=\"5385\">29</sup> משבחי' כו' באימה וביראה אבל עכ\"ז לא נקרא עליהם בחי' מדת מלכות כמו שהיא בעצם באמתת שם התואר כי מאחר שמציאת התהוותם הוא רק מבחי' מל' וכמ\"ש ומלכותו<sup data-n=\"5386\">30</sup> בכל משלה והיא חיותם וקיומם א\"כ אין זה מעיקר בחי' המל' אלא רק מבחי' התפשטו' המדה אבל ישראל המה המקבלי' בחי' עצמו' מדת מל' והוא בחי' הדר והוד כבוד מלכותו וכמ\"ש וכבוד<sup data-n=\"5387\">31</sup> הדר מלכותו לפי שישראל מקיימי' המצות שנק' לבושי מלכות וכענין הוד<sup data-n=\"5388\">32</sup> והדר לבשת, עוז והדר לבושה כו' ועד\"מ לבושי המלך שמייפים ומהדרים את המלך היינו כשלובש בגדי כבוד ותפארת בגדי מלכות דוקא שבהם נגלה כבודו ותפארת גדולתו וגם בעצמו מתייפה על ידם כמ\"ש מלך<sup data-n=\"5389\">33</sup> ביופיו כו' כך ע\"י המצות<sup data-n=\"5390\">34</sup> שנק' לבוש מלכות כידוע הרי הן בחי' בגדי כבוד ותפארת למדת מלכותו ית' עד שנק' הדר וכמ\"ש וכבוד הדר מלכותו ונמצא על ישראל דוקא נמשך עיקר עצם מדת המל' שהוא בחי' הוד והדר מלכותו וזהו שנק' המלך השמיני הדר<sup data-n=\"5391\">35</sup> ושם עירו פעו בחי' עולם הדיבור שהוא שרש כנ\"י כו' וד\"ל.\n<b>וביאור</b> הדברים הנה נודע שמן המצות נעשו לבושי' לנשמה בג\"ע<sup data-n=\"5392\">36</sup> שנהנין מזיו השכינה וענין הזיו הזה הוא בחי' לבוש של הוד לנשמה אשר &lt;שסט&gt;\nהוא נעשה",[["5382","26","<b>מלכותך מלכו' כ\"ע</b>: תהלים קמח, יג."],["5383","27","<b>מזיעתן של חיות</b>: ראה חגיגה יג, סע\"ב. ס' הליקוטים [דא\"ח להצ\"צ] ערך זיעה."],["5384","28","<b>ומוראך עליהם</b>: פיוט אשר אימתך (מוסף ליו\"כ)."],["5385","29","<b>וכולם משבחי' כו' באימה וביראה</b>: ברכת יוצר."],["5386","30","<b>ומלכותו בכל משלה</b>: תהלים קג, יט."],["5387","31","<b>וכבוד הדר מלכותו</b>: תהלים קמה, יב."],["5388","32","<b>הוד והדר לבשת, עוז והדר לבושה</b>: תהלים קד, א. משלי לא, כה."],["5389","33","<b>מלך ביופיו</b>: ישעי' לג, יז."],["5390","34","<b>המצות שנק' לבוש מלכות</b>: ראה שערי אורה נו, א. ובכ\"מ."],["5391","35","<b>הדר ושם עירו</b>: וישלח לו, לט."],["5392","36","<b>בג\"ע שנהנין מזיו השכינה</b>: ראה ברכות יז, א."]]],[2100990362,"ע\"י המצוה שעסק בה בעוה\"ז אך אין זה אלא זיו המצוה והארתה בלבד אבל גופה של המצוה עצמה הוא למעלה מבחי' זיו השכינה דהנה ארז\"ל יפה<sup data-n=\"5393\">37</sup> שעה א' בתשובה ומע\"ט מכל חיי העוה\"ב כו' והטעם הוא לפי שהמצוה עצמה ומהותה הנה היא בחי' רצון העליון הגנוז באור חכמתו ית' המלובשת בתורה כידוע דאוריי'<sup data-n=\"5394\">38</sup> מחכמה עילאה נפקת כו' והנה על התורה נא' ואהי'<sup data-n=\"5395\">39</sup> אצלו אמון שעשועי' יום יום וכן ותורתך<sup data-n=\"5396\">40</sup> שעשעתי כו' ונקרא בחי' שעשוע<sup data-n=\"5397\">41</sup> המלך בעצמותו דהנה עד\"מ מלך ב\"ו כשמדבר דברי חכמה להנהגות שהן עפ\"י דרכי חכמה והשכל הנה הוא מתענג בהן מאד כמו שנרא' בחוש שהאדם מתענג כשנופל לו איזה שכל וחכמה במוחו לפי שהתענוג מתלבש בחכמה כנודע משא\"כ כשהמלך מצווה לעשו' דבר עבודה שהעבדים צריכין לקיים גזרתו בלתי ידיעת טעם ושכל לגזרה זו שאין בציווי זה תענוג כלל אבל המצות שמצוה המלך ע\"ד החכמה והטעם יש בהן תענוג בגילוי כך המצות שבתורה הן מצות מלכותו ית' שמלובש בהן עונג האלקי לפי שבמצות הללו עפ\"י החכמה הן ובחכמה מלובש התענוג כנ\"ל משא\"כ שאר ציווי מדת מלכותו כמו י'<sup data-n=\"5398\">42</sup> מאמרו' שנבראו בהן כל העולמו' שאינם רק גזרות המלך בלתי נגלה בהן החכמה והעונג כו'.\n<b>וזהו</b> שבתורה דוקא נא' ואהי' אצלו אמון קודם שנברא העולם בי' מאמרו' שעשועי' יום יום כו' פי' שעשועי' הללו הן בחי' שעשועי המלך בעצמותו מחמת התענגו בחכמתו כאדם שמתענג מטוב שכלו כו' וד\"ל וזהו ואהי' אצלו דוקא לפי שאין שעשועי' הללו יכולי' לבא להשגה גם בנשמו' שבג\"ע שנהנין מזיו כו' כי זהו למעלה הרבה מבחי' זיו זה מטעם הנ\"ל וזהו כי<sup data-n=\"5399\">43</sup> עמך מקור חיים פי' מקור התענוגי' הנק' שעשועי המלך בעצמותו אבל זיו השכינה אינו אלא רק בחי' הארה וזיו בעלמא כו' וד\"ל.\n<b>והנה</b> מבחי' שעשועי' הנ\"ל המלובש בגופן של מצות שבתורה כנ\"ל נמשך להיות מזה בחי' לבושי כבוד והוד מלכות עד\"מ המלך שמצווה דבר חכמה שתפארת היא לו מה שמצוותיו הן דברי חכמה כנ\"ל כך ע\"י המצות שבתורה נמשך בחי' היופי והתפארת במדת מלכותו ית' וכמ\"ש הוד והדר לבשת כו' וד\"ל וזהו ענין ברכת המצות ברוך אתה מלך העולם פי' שברוך ונמשך בהשתלשלות עד שנק' מלך העולם וכל זה מפני שקדשנו במצוותיו פי' בלבושי הוד מלכו' שנעשה ע\"י המצות כנ\"ל וזהו אשר קדשנו במצוותיו קדשנו בקדש העליון הנק' הדרת קדש וכמ\"ש וכבוד הדר מלכותו וכנ\"ל וד\"ל.",[["5393","37","<b>יפה שעה א' בתשובה ומע\"ט</b>: אבות פ\"ד, מי\"ז."],["5394","38","<b>דאוריי' מחכמה עילאה נפקת</b>: זח\"ב פה, א. ועוד."],["5395","39","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["5396","40","<b>ותורתך שעשעתי</b>: תהלים קיט, ע."],["5397","41","<b>שעשועי המלך בעצמותו</b>: נת' בעמק המלך שער א. וראה לקו\"ת שה\"ש כז, סע\"א."],["5398","42","<b>י' מאמרו' שנבראו בהן כל העולמו'</b>: ראה אבות פ\"ה מ\"א."],["5399","43","<b>כי עמך מקור חיים</b>: תהלים לו, י."]]],[2100990363,"<b>והנה</b> כתיב תחת<sup data-n=\"5400\">44</sup> אשר לא עבדת ה' אלקיך בשמחה וטוב לבב מרוב כל פי' רוב כל הוא חיי<sup data-n=\"5401\">45</sup> העוה\"ב שנק' רוב כל כידוע כי בעוה\"ב נמשך העונג האלקי שהוא בחי' זיו השכינה שהצדיקי' יושבין ונהנין כו' ותענוג זה נק' נועם ה' וכמ\"ש לחזות<sup data-n=\"5402\">46</sup> בנועם ה' כו' והוא תענוג נפלא שאין כמוהו בערך בכל מיני תענוג הנמצאי' בעולמות כי העונג הזה הוא עונג אלקי שאינו &lt;שע&gt;\nבגדר וסוג עונג נברא ב\"ג כו' ולכך אמרו באחר מוטב<sup data-n=\"5403\">47</sup> דלידייני' וליתי לעלמא דאתי כי כדאי לסבול כל יסורי גיהנם עד אשר תטהר הנפש ותוכל לקבל אור אותו העונג האלקי כו' והנה בחי' גילוי זיו עונג זה הוא בא בבחי' אור ושפע האלקי' מבחי' מל' דאצי' הנק' ממלא כ\"ע אבל בעוה\"ז אע\"פ שאין בו גילוי אור עונג זה אבל יש בו יתרון מעלה מצד אחר והוא לפי שבעוה\"ז מאיר אור המקיף הנק' סובב כ\"ע השוה<sup data-n=\"5404\">48</sup> ומשוה קטן וגדול כו' וכמ\"ש המגביהי<sup data-n=\"5405\">49</sup> לשבת המשפילי לראו' כו' משום דקמיה ממש כחשיכה<sup data-n=\"5406\">50</sup> כאורה כו', ומטעם זה בעוה\"ז יותר קרוב האדם לבא לידי תשובה להפוך רע לטוב מן הקצה לקצה ויש<sup data-n=\"5407\">51</sup> קונה עולמו בשעה א' כר\"א בן דרודיא שזהו היפך ההשתלשלו' משא\"כ בעוה\"ב שאין מועיל שם התשובה וכמ\"ש<sup data-n=\"5408\">52</sup> במ\"א וד\"ל.\n<b>וזהו</b> שאמר בשמחה וטוב לבב מרוב כל שהשמחה וטוב לבב במעשה המצוה בעוה\"ז יותר טוב מרוב כל שבעוה\"ב אך בתנאי שיהא שמח ומתענג במעשה המצוה וכמ\"ש תחת אשר לא עבדת בשמחה וטוב לבב כו' והטעם הוא לפי שהשמחה של מצוה גורמת למעלה בחי' שעשועי המלך בעצמותו שהן יופי לבושי המלך שלא ניתן להשגת הנבראי' כלל כנ\"ל שהוא למעלה הרבה מבחי' הזיו כו' וע\"כ יפה שעה א' בתשובה ומע\"ט בעוה\"ז דוקא מכל חיי העוה\"ב כו' לפי ששעשועי המלך בעצמותו גבוה הרבה מהארת זיו אותו העונג שמשתעשע בעוה\"ב כו' וכמ\"ש כי עמך מקור חיים כלומר שהוא מקור התענוגי' כו' וכנ\"ל וד\"ל.\n<b>ובזה</b> יובן מ\"ש ובלילה<sup data-n=\"5409\">53</sup> שירה עמי ושירו קרי כו' דהנה פסוק הזה בעוסק בתורה בלילה נאמר כידוע בדברי רז\"ל והוא הנקרא רינה של תורה שאין<sup data-n=\"5410\">54</sup> רינה של תורה אלא בלילה דוקא כמ\"ש ובלילה שירה עמי כו' והענין הוא כמבואר בזוהר<sup data-n=\"5411\">55</sup>",[["5400","44","<b>תחת אשר לא עבדת</b>: תבוא כח, מז."],["5401","45","<b>חיי העוה\"ב שנק' רוב כל</b>: ראה ג\"כ תו\"א הוספות מג\"א קכב, ב. תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] נ, ג. מאמרי אדה\"א נצבים ע' תתמח."],["5402","46","<b>לחזות בנועם ה'</b>: תהלים כז, ד."],["5403","47","<b>מוטב דלידייני'</b>: חגיגה טו, ב."],["5404","48","<b>השוה ומשוה קטן וגדול</b>: לשון פיוט (לימים נוראים) האוחז ביד מדת משפט."],["5405","49","<b>המגביהי לשבת המשפילי לראות</b>: תהלים קיג, ו."],["5406","50","<b>כחשיכה כאורה</b>: שם קלט, יב."],["5407","51","<b>ויש קונה עולמו בשעה א'</b>: ראה ע\"ז יו\"ד, ב."],["5408","52","<b>וכמ\"ש במ\"א</b>: ראה לקו\"ת דרושים ליוהכ\"פ ע, א. ובכ\"מ."],["5409","53","<b>ובלילה שירה עמי ושירו קרי</b>: תהלים מב, ט. וראה תו\"ח בראשית לד, ד. בהערה 50."],["5410","54","<b>שאין רינה של תורה אלא בלילה</b>: ויק\"ר רפכ\"ט. זהר ויקרא כג, ב."],["5411","55","<b>בזוהר. . רננה דאוריי'</b>: ראה זהר בהקדמה ח, א. תו\"ח בראשית ד, א. לו, ב. לז, ג. מאמרי אדה\"א דברים ח\"ג ע' תשפא."]]],[2100990364,"שיש בחי' רננה דאוריי' והן הניגונים והטעמים שבתורה וידוע שבנגינות וטעמי' בהם יש מתיקות ותענוג ערב לנפש כמו שיש תענוג בכל ניגון כידוע ולזה נקראו טעמי תורה כלומר בחי' הטעם והמתיקו' שיש בתורה שמלובש בנגינות וטעמי' דאוריי' וזהו הנקרא ג\"כ רננה דאוריי' רינה של תורה כו' והיינו בחי' התענוג העליון הנק' שעשועי<sup data-n=\"5412\">56</sup> המלך בעצמותו שמתלבש בנגינות וטעמים והוא גבוה מבחי' החכמה שבתורה הגנוזה באותיו' שבתורה אחר שהנגינות הן למעלה מן האותיות והענין הוא לפי שהתענוג הוא למעלה מן החכמה כידוע שבחי' הטעמי' הוא בכתר כו' וד\"ל.\n<b>וזהו</b> ואהי' אצלו שעשועי' שהתורה<sup data-n=\"5413\">57</sup> קדמה לעולם והי' הקדב\"ה<sup data-n=\"5414\">58</sup> משתעשע בחכמה שבתורה קודם שנברא העולם ושעשועים הללו נקרא שעשועי הקדב\"ה בעצמו וכמ\"ש<sup data-n=\"5415\">59</sup> ואהי' אצלו אצלו דוקא אך אח\"כ נמשך מבחי' שעשועים הללו ונתלבש בטעמי ונגינות שבתורה וכל העוסק בתורה בלילה ממשיך מבחי' שעשועי המלך בעצמו שיתענג בטעמי' שבתורה והוא ענין רינה של תורה בלילה הנק' רננה דאוריי' שלמעלה מבחי' חכמה שבתורה.\n<b>וזהו</b> ובלילה שירה עמי ושירו קרי פי' שרננה דאוריי' בטעמי' ונגינות הוא הנק' שירו דהיינו שירו של הקדב\"ה עצמו וכמ\"ש ואהי' אצלו שעשועים כו' וכנ\"ל והכתיב &lt;שעא&gt;\nשירה לפי שנתפשט מהארת עונג העליון הזה למטה בגילוי בטעמי' הנגלים בשיר וניגון כו' ומה שאמר שירה עמי ר\"ל שאע\"פ שנתגלו בחי' הטעמים למטה מ\"מ השיר עמי בבחי' ההעלם דעצמות השעשועים הנ\"ל שלא ניתן להשגת בנ\"א כנ\"ל שלמעלה הוא גם מהנאת הזיו בג\"ע כו' וזהו ובלילה שירה עמי דוקא (ומה שאמר ובלילה דוקא מבואר בזוהר<sup data-n=\"5416\">60</sup> הטעם ע\"פ השמיעני את קולך כו' דהוא קלא דמשתדלי באוריית' בליליא דוקא לפי שבלילה יותר ערב התגלו' שעשועי' העליונים מביום כדי להכניע את צמצום החושך כו' אבל ביום שרגא<sup data-n=\"5417\">61</sup> בטיהרא מאי מהני וכמ\"ש במ\"א באריכו').\n<b>ובזה</b> יובן הטעם שנענש<sup data-n=\"5418\">62</sup> דוד הע\"ה על שקרא לד\"ת שם זמירות כמ\"ש זמירות<sup data-n=\"5419\">63</sup> היו לי חוקיך קרית להו זמירות כו' לפי שהזמרה בשיר וניגון הוא בחי' גילוי העונג העליון למטה כנ\"ל ובאמת שרש זה העונג והטעם הרי הוא בבחי' שעשועי המלך בעצמותו כנ\"ל בפי' ואהי' אצלו שעשועי' ואמנם דוד הוצרך לכך לפי שעה",[["5412","56","<b>שעשועי המלך בעצמותו</b>: נסמן לעיל ע' תשלד."],["5413","57","<b>שהתורה קדמה לעולם</b>: ראה מדרש תהלים צ, ד. ב\"ר פ\"ח, ב. תנחומא וישב ד, וש\"נ. זח\"ב מט, א."],["5414","58","<b>הקדב\"ה משתעשע בחכמה שבתורה</b>: ראה תו\"א מקץ לב, א. שלח מח, ד."],["5415","59","<b>ואהי' אצלו</b>: משלי ח, ל."],["5416","60","<b>בזוהר. . קלא דמשתדלי באוריי' בליליא</b>: ראה במדבר ריג, א."],["5417","61","<b>שרגא בטהרא מאי מהני</b>: לשון חז\"ל — חולין ס, ב."],["5418","62","<b>שנענש דוד הע\"ה</b>: ראה סוטה לה, א. אגה\"ק (ד\"ה דוד זמירות ע' תקס ואילך). מאמרי אדה\"א במדבר ח\"ב ע' תתקכו, וע' תקמב, ובהנסמן לשם."],["5419","63","<b>זמירות היו לי חוקיך</b>: תהלים קיט, נד."]]],[2100990365,"להיות שהיה נמסר ביד אויביו והי' מתיירא מן הדין כו' וכדי להכניע החיצונים מועיל המשכת גילוי עונג עליון להאיר פני מלך בשעשועי המלך כשמשתעשע ברננה דאוריית' כמאמר כד<sup data-n=\"5420\">64</sup> אנפוהי דמלכא נהירין כו' כל דינין אתכפיין כמו במלכותא דארעא כשהמלך בהארת הפנים כשמשתעשע נמתקו כל הדינין והקטרוגי' כו' וכמ\"ש<sup data-n=\"5421\">65</sup> במ\"א וד\"ל.\n<b>וזהו</b> שאמר דוד זמירות היו לי חוקיך בבית מגורי מפני אויבי' דוקא, אך מ\"מ נענש ע\"ז לפי ששיבח את התורה במעלה זו דזמרה בלבד שהיא רק בחי' הארה בעלמא מעצמות השעשועי' ובאמת יש לה מעלה יתירה ונפלאה הרבה מזו שהיא בחי' עצמו' השעשועי' ונקרא' שירו של הקדב\"ה בעצמו כנ\"ל וד\"ל.\n<b>וזהו</b> תחת אשר לא עבדת ה' אלקיך בשמחה וטוב לבב כו' שהוא שמחה של מצוה שנק' לבוש והדר מלכותו כנ\"ל עד\"מ המלך שמצווה דברי חכמה שמתפאר בה וכן ע\"י רננה דאוריי' נמשך בחי' שמחה ושעשועי' שכל זה נק' שמחה וטוב לבב בעבודה שבתורה ומצות כו' והנה בכל עבודה צריך להיו' התכללות מאהבה ויראה הנקראי' בזוהר<sup data-n=\"5422\">66</sup> בשם דחילו ורחימו והנה האהבה נמשך מן השמחה והתענוג הנ\"ל והיינו בחי' אהבה שיש בעבודת העובד במצות ועסק התורה וכמ\"ש תחת אשר לא עבדת בשמחה וטוב לבב שצ\"ל העבודה מאהבה הבאה מן השמחה וטוב לבב כנ\"ל וזה נק' רחימו אבל בחי' העובד ביראה הנק' דחילו הוא למעלה במדרגה גם מעבודה באהבה ושמחה הנ\"ל כי הנה עד\"מ עבד העובד מיראה הנה איננו משגיח כלל בטעמה של מצוה שנצטווה מן המלך כלומר מאיזה טעם ירצה המלך ובזה הטעם תתענג נפשו למלאו' חפץ ותענוג המלך כו' אלא עליו מוטל לעשות מצות המלך סתם מפני שציוה כך וזהו גזרת המלך ותפקידו בלי טעם ודעת והוא מחוייב לשמוע ולקיים דבר המלך אפי' אם אינו יודע בה טעם כלל וכלל כמו כאשר<sup data-n=\"5423\">67</sup> יצווה לחטוב עצים שאין בגזרה זו שום הבנת טעם ועונג למלך כי אינו &lt;שעב&gt;\nעושה הדבר מחמת אהבתו למלך למלאו' התענוג והחפץ אלא רק מצד בחי' היראה שהוא בא ע\"י בחי' הביטול שכבר ביטל עצמותו מכל וכל בכל אשר יגזור אומר עליו וביטול זה גורם שיעשה המצוה סתם גם שאיננו יודע בה טעם כלל כו' וד\"ל.\n<b>והדוגמא</b> מזה במצות מעשיו' ידוע שהמצות<sup data-n=\"5424\">68</sup> הצריכות כוונה היינו לכוין אל בחי' הטעם והעונג העליון המלובש בה וכנ\"ל בענין שמחה וטוב לבב שבמעשה המצוה כו' אבל מצות הנעשו' ביראה היינו גם בלתי ידע טעם המצוה בעונג העליון אלא בלי טעם ודעת רק מפני שאמר ונעשה רצונו בלבד כי גזרת מלך היא שזה בא מבחי' הביטול בתכלית כנ\"ל וזה יותר גבוה מעובד מאהבה ושמחה הנ\"ל.",[["5420","64","<b>כד אנפוהי דמלכא נהירין</b>: ראה זהר (אד\"ר) נשא קלג, ב."],["5421","65","<b>וכמ\"ש במ\"א</b>: ראה ג\"כ תו\"ח שמות [הוצאת קה\"ת — תשס\"ג] קט, ד. מאמרי אדה\"א נ\"ך ע' לז. ובכ\"מ."],["5422","66","<b>בזוהר. . דחילו ורחימו</b>: תקו\"ז ת\"י (כה, ב). וראה תניא פט\"ז ואילך."],["5423","67","<b>כאשר יצוה לחטוב עצים</b>: ראה לקו\"ת שלח מ, א. המשך תרס\"ו ע' נד. ועוד."],["5424","68","<b>שהמצות הצריכות כוונה</b>: עירובין צה, ב."]]],[2100990366,"<b>והמופת</b> לזה הנה מצינו כדוגמא זו בתוכחה שהוכיח שמואל הנביא את שאול באמרו לו החפץ<sup data-n=\"5425\">69</sup> לה' בעולות וזבחים כו' הלא שמוע מזבח טוב כו'. פי' כי הנה שאול רצה לקיים המצוה בשמחה וטוב לבב מצד הטעם והעונג העליון המלובש בה ומפני שהוא השיג בטעם של מצוה שנצטווה והכית<sup data-n=\"5426\">70</sup> את עמלק כו' לכך עלה בדעתו שיביא ראשית<sup data-n=\"5427\">71</sup> החרם לזבוח לה' כו' ואח\"כ לא ישאיר כל נשמה אבל לא שיחרימם סתם בלתי שיזבח תחלה ראשית החרם מהם לה' כי כך הי' מכוין בכוונה וטעמה של מצוה למעלה ולזה אמר לפי תומו הקימותי<sup data-n=\"5428\">72</sup> את דבר ה' שלדעתו יפה כיון ויפה קיים דבר ה' אבל שמואל הוכיחו שלא היה צריך לעבוד המצוה מאהבה בלבד אלא בצירוף היראה שהוא בבחי' הביטול מעצמותו רק לקיים גזרת המלך גם שלא ידע טעם המצוה וזהו שאמר לו החפץ לה' בעולו' וזבחים כלומר מה לך להשגיח בבחי' חפץ וטעם האלקי במצות שמצווה כו' הלא<sup data-n=\"5429\">73</sup> שמוע מזבח טוב כו' שצריך לשמוע בקול ה' סתם בלי טעם וכונה וזה יקר בעיני ה' יותר מצד בחי' הביטול לפי שביטול זה גורם המשכת השעשועי' העליוני' הנק' שעשועי המלך בעצמו להיות חפץ ומתענג במעשה המצוה כו' ולכך אמר הלא שמוע מזבח טוב כו' שמיעה זו בבחי' ביטול טוב יותר מגופה של מצוה בזבח כו' מטעם זה וד\"ל.\n<b>וזהו</b> ענין התפלה, דהנה ארז\"ל דיש<sup data-n=\"5430\">74</sup> מלאך סנד\"ל שקושר כתרי\"ם מן התפלות ומבואר זה בזוהר ג\"כ בכמה דוכתי וכתר כזה זכו ישראל במ\"ת כשאמרו נעשה<sup data-n=\"5431\">75</sup> ונשמע שניתן<sup data-n=\"5432\">76</sup> לכאו\"א מהם ב' כתרים והיינו מ\"ש ויתנצלו<sup data-n=\"5433\">77</sup> בנ\"י את עדים מהר חורב כידוע שע\"י<sup data-n=\"5434\">78</sup> החטא העגל נסתלק מהם ב' כתרים הללו וע\"י התפלה נעשה כתר כזה אך לא מצד כחם של כנ\"י בתפלתם בלבד אלא בסיוע של מעלה דהיינו ע\"י המלאך הנ\"ל הממונה ע\"ז לעשות הכתר מתפלות ישראל.\n<b>וביאור</b> הענין הוא לפי שהתפלה<sup data-n=\"5435\">79</sup> נק' סולם שמוצב<sup data-n=\"5436\">80</sup> ארצה וראשו מגיע כו' להיות כי העיקר בתפלה הוא בחי' הביטול מלמטה למעלה בשפיכת הנפש",[["5425","69","<b>החפץ לה' בעולות וזבחים</b>: שמואל-א טו, כב."],["5426","70","<b>והכית את עמלק</b>: שמואל-א טו, ג — והכיתה את עמלק."],["5427","71","<b>ראשית החרם לזבוח לה'</b>: שם כא — מראשית החרם."],["5428","72","<b>הקימותי את דבר ה'</b>: שמואל-א טו, יג."],["5429","73","<b>הלא שמוע מזבח טוב</b>: שם טו, כב — הנה שמוע."],["5430","74","<b>דיש מלאך סנד\"ל שקושר כתרים. . בזוהר</b>: ראה זהר וישלח קסז, ב. סה\"מ ה'תש\"ח ע' 202 בהערה. מאמרי אדה\"א נ\"ך ע' שיג. וש\"נ."],["5431","75","<b>נעשה ונשמע</b>: משפטים כד, ז."],["5432","76","<b>שניתן לכאו\"א מהם ב' כתרים</b>: שבת פח, א."],["5433","77","<b>ויתנצלו בנ\"י את עדים מהר חורב</b>: תשא לג, ו."],["5434","78","<b>שע\"י החטא העגל נסתלק מהם ב' כתרים</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שלד. שערי אורה קמב, א."],["5435","79","<b>שהתפלה נק' סולם</b>: זהר (רעיא מהימנא) ח\"א בהשמטות רסו, ב. ח\"ג (הוספות) שו, ב. תקו\"ז תמ\"ה (פג, א)."],["5436","80","<b>שמוצב ארצה וראשו מגיע</b>: ויצא כח, יב."]]],[2100990367,"לצעוק אל ה' בכל לבב וכמ\"ש צעק<sup data-n=\"5437\">81</sup> לבם כו' עד שמגיע לק\"ש שאומר ואהבת<sup data-n=\"5438\">82</sup> בכל לבבך כו' ועי\"ז בתפלת<sup data-n=\"5439\">83</sup> י\"ח נמשך בחי' אור מלמעלה למטה כמ\"ש אם<sup data-n=\"5440\">84</sup> ישים אליו לבו כו' דרוח<sup data-n=\"5441\">85</sup> אייתי רוח ואמשיך רוח כידוע והמשכה זו בתפלת י\"ח היינו המשכת בחי' הכתר שהמלאך קושר כנ\"ל והיינו להיו' המשכת רצון העליון של המאציל למטה בתורה ומצות &lt;שעג&gt;\nהנק' כתר תורה כנ\"ל והן ג\"כ ענין הכתרים שקיבלו כנ\"י במ\"ת כי באמרם נעשה ונשמע הרי הגיעו לבחי' ביטול עצמותם כענין פי' הלא שמוע מזבח טוב כנ\"ל והוא בחי' ביטול אשר ביראה שגורמת למעלה שיומשך השעשועי' העליונים בתורה ומצות כנ\"ל.\n<b>וזהו</b> הכתרים שנמשך להם וכך הוא בתפלה שבבחי' הביטול שעד ש\"ע גורמת להיו' נמשך בחי' הכתר ע\"י המלאך הנ\"ל והיינו הטעם שהתפלה קודמת לתורה וכמאמר אבא<sup data-n=\"5442\">86</sup> בנימין שהי' מצטער שתפלתו תהא סמוכה למטתו והגם שהתלמוד<sup data-n=\"5443\">87</sup> גדול שמביא לידי מעשה ות\"ת<sup data-n=\"5444\">88</sup> כנגד כולם מ\"מ ניתקנה התפלה להתפלל קודם הלימוד משום שע\"י התפלה נמשך בחי' כתר תורה דהיינו להיו' חפץ ה' להשתעשע בתורה ומצות וכתר זה הוא תר\"ך<sup data-n=\"5445\">89</sup> עמודי אור שהן תרי\"ג מצו' דאוריי' וז' דרבנן כנודע וד\"ל.\n<b>והנה</b> ידוע שהמלאכי' ביקשו תנה<sup data-n=\"5446\">90</sup> הודך על השמים והשיב להם משה כלום יצה\"ר יש בכם כו' ולכאורה אדרבה אם אין יצה\"ר בהם יותר יתקיים בהם התורה. אך הענין הוא דכתיב כי<sup data-n=\"5447\">91</sup> שרית עם אלקים וידוע דאלקים<sup data-n=\"5448\">92</sup> בגי' הטבע ופי' עם היינו בסיוע דאלקים זה דהיינו שגם בחי' הטבע מסייע להפוך הרע לטוב כי הנה כאשר חפץ ה' ביד האדם מצליח להפוך הרע לטוב להיו' אתכפיא סט\"א ואתהפכא כו' אזי מלאך<sup data-n=\"5449\">93</sup> הרע בע\"כ יענה אמן וגם הוא מסייע להפוך הרע לטוב כי בהודאתו והסכמתו גם הוא נותן כח ועוז בהיפוך זה והראי' לזה ממשל<sup data-n=\"5450\">94</sup> הידוע בזונה עם בן",[["5437","81","<b>צעק לבם</b>: איכה ב, יח. תו\"א ויחי נא, א. לקו\"ת אחרי כז, ג. נשא כח, ב. ובכ\"מ."],["5438","82","<b>ואהבת בכל לבבך</b>: ואתחנן ו, ה."],["5439","83","<b>בתפלת י\"ח נמשך בחי' אור מלמעלה למטה</b>: ראה לקו\"ת פינחס עו, א. דרושים לש\"ש סו, א."],["5440","84","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["5441","85","<b>דרוח אייתי רוח</b>: ראה זהר תרומה ריש ע\"ב. סידור ערב שבת קסג, ד. אמרי בינה שער התפילין פל\"א."],["5442","86","<b>אבא בנימין. . שתפלתו תהא סמוכה למטתו</b>: ברכות ה, ב. וראה לקו\"ת ברכה צו, ב."],["5443","87","<b>שהתלמוד גדול שמביא לידי מעשה</b>: ראה קידושין מ, ב. ב\"ק יז, א."],["5444","88","<b>ות\"ת כנגד כולם</b>: פאה רפ\"א."],["5445","89","<b>מצות. . תר\"ך עמודי אור. . תרי\"ג מצות</b>: נסמן לעיל ע' תשב."],["5446","90","<b>תנה הודך על השמים. . כלום יצה\"ר יש בכם</b>: תהלים ח, ב. שבת פח, סע\"ב ואילך."],["5447","91","<b>כי שרית עם אלקים</b>: וישלח לב, כט."],["5448","92","<b>אלקים בגי' הטבע</b>: פרדס שער יב (שער הנתיבות) פ\"ב. ראשית חכמה שער התשובה פ\"ו ד\"ה והמרגיל (קנא, ב). של\"ה פט, א (דאיתא בזהר). קפט, א (ומרומז בזוהר). שח, ב. שו\"ת חכם צבי סי\"ח. שעהיוה\"א רפ\"ו."],["5449","93","<b>מלאך הרע בע\"כ יענה אמן</b>: ראה עמק המלך שער (יד) קרית ארבע פק\"ו. שבת קיט, ב."],["5450","94","<b>ממשל הידוע בזונה עם בן המלך</b>: זהר תרומה קסג, א. ראה תניא ספ\"ט וספכ\"ט. מאמרי אדה\"ז אתהלך לאזניא ע' קנה. תו\"ח תולדות קנד, ב. מקץ רטז, ד. אוה\"ת חוקת — הוספות ע' סז."]]],[2100990368,"המלד המבואר בזוהר כי הזונה גם היא אין כונה שלה רק רצון המלך אשר לפ\"ז אם נגמר הרצון באדם להתגבר על הרע ולכבשו גם מלאך הממונה על אותו הרע שהוא מבחי' הטבע גם הוא מסייע כו'. וזהו שאמר כי<sup data-n=\"5451\">95</sup> שרית עם אלקים בסיוע שלו ולא נא' על אלקי' וד\"ל.\n<b>והנה</b> אמרו בזוהר כד<sup data-n=\"5452\">96</sup> אתכפיא סט\"א אסתלק יקרא דקדב\"ה ופי' יקרא הוא הוד כתר מלכו' שנעשה מהיפוך הרע לטוב ע\"ד הנ\"ל לפי שיתרון<sup data-n=\"5453\">97</sup> האור בא מתוך החושך דוקא כידוע וזה גורם בחי' שעשועי' העליוני' שמהם נמשך כתר תורה לפי שבהיפוך הרע אסתלק יקרא דקדב\"ה לעילא ונעשה מזה שעשועי' כו' ומשם נמשך הכתר לתורה והוא הנקרא שמחת תורה פי' שמחת התורה עצמה שהתורה משתעשעת בקדב\"ה מבחי' שעשועי המלך בעצמותו כו' וד\"ל, והיינו שהשיב להם משה כלום יצה\"ר יש בכם לאכפייא לסט\"א כו' וא\"כ מהיכן יומשך לכם בחי' כתר תורה הנק' הודך שאין כתר תורה בא אלא ע\"י בחי' הביטול כנ\"ל ולאכפייא לסט\"א משום דעי\"ז אסתלק יקרא דקדב\"ה לעילא כנ\"ל וד\"ל.\n<b>וזהו</b> תורה ציוה לנו משה מורשה קהלת יעקב. פי' משה<sup data-n=\"5454\">98</sup> הוא בחי' חכמה ותורה ציוה לנו משה היינו משום דאוריית'<sup data-n=\"5455\">99</sup> מחכמה עילא' נפקת וע\"כ כל התורה כולה ע\"י משה נאמרה וכמ\"ש בכל פרשה ויאמר ה'<sup data-n=\"5456\">100</sup> אל משה וה\"ז כמו שציוה לנו משה מאחר שחכמה שבתורה הוא שרש נשמת משה וכמ\"ש בו כי<sup data-n=\"5457\">101</sup> מן המים משיתהו מים דאוריי' כו' ופי' מורש\"ה היינו טעם לנתינת התורה והמצות שהוא כדי לברר ברורי נוגה לאהפכא<sup data-n=\"5458\">102</sup> חשוכא לנהורא כו' אם לאתהפכא מן הקצה לקצה או לאכפייא כו' הכל הוא היפוך ובירור הרע &lt;שעד&gt;\nלטוב וזה נעשה ע\"י מעשה המצות שמלובשים בעניני' גשמיי' דדצ\"ח דנוגה דעשי' כמבואר למעלה באריכות שעל ידן מתבררי' ז' מלכי' דתוהו להיות למורשה לפי שזהו הנק' מורשה כמ\"ש בכל התורה על ארץ הכנעני וכו' לרשתה כו'.\n<b>וזהו</b> תורה ציוה לנו משה כדי להיו' מורשה כל הדברים שנפלו בנוגה בהתהפכם לקדוש' העליונה ע\"י מעשה המצות ואז נקראו קהלת יעקב פי' יעקב הן נשמות ישראל המלובשים בגופים חומריים בעוה\"ז והיינו יעקב יו\"ד עקב כו' משא\"כ שרש נשמו' כללו' ישראל למעלה לא נק' יעקב אלא ישראל כידוע להיות כי נשמות",[["5451","95","<b>כי שרית עם אלקים</b>: וישלח לב, כט."],["5452","96","<b>בזוהר כד אתכפיא סט\"א</b>: זח\"ב קכח, ב. תניא פכ\"ז."],["5453","97","<b>שיתרון האור בא מתוך החושך</b>: ראה קהלת ב, יג."],["5454","98","<b>משה הוא בחי' חכמה</b>: ראה לקו\"ש ח\"ו ע' 244 ואילך."],["5455","99","<b>דאוריית' מחכמה עילא' נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. ח\"ג פא, א. קפב, א. רסא, א."],["5456","100","<b>ויאמר ה' אל משה</b>: תשא לא, יב."],["5457","101","<b>כי מן המים משיתהו</b>: שמות ב, י."],["5458","102","<b>לאהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."]]],[2100990369,"המלובשי' בגופים דוקא בהן ועל ידן יתקיימו כל המצות בעניני' הגשמיים שתחת ממשלת נוגה ויהי' עי\"ז אתהפכא ואתכפיא מנוגה דז' מלכי' להיות למורשה כנ\"ל משא\"כ בלתי התלבשו' הנשמו' בגופים וע\"כ נק' קהלת יעקב לפי שנקהלו ונתאספו כל הברורי' דנוגה ביעקב<sup data-n=\"5459\">103</sup> יו\"ד עקב ע\"י קיום המצות בגשמיו' דוקא. והנה אחר שאמר בענין טעם לנתינת התורה והמצות לנשמו' ישראל המלובשי' בגופים כנ\"ל אמר אח\"כ שעי\"ז ויהי<sup data-n=\"5460\">104</sup> בישורון מלך דהיינו שנעשה בחי' מלך לבוש בלבוש הוד בגדי מלכות וכנ\"ל לפי שבחי' שעשועי המלך בעצמותו מאיר במעשה המצות כד אתכפיא כו' דאסתלק יקרא דקודב\"ה כו' כנ\"ל באריכו' וד\"ל.\n<b>אך</b> הנה יש להבין מהו פי' בישורו\"ן להיות כי בפי' ישורו\"ן<sup data-n=\"5461\">105</sup> יש ג\"כ לפרש לשון שיר\"ה כי פי' ענין היושר שבתיבת ישורון יש לפרשו ג\"כ בענין השירה כי הרי לזה הטעם נקרא הניגון בשם שיר לפי שהשיר<sup data-n=\"5462\">106</sup> הוא דבר העגול כטבעת כענין כל<sup data-n=\"5463\">107</sup> בעלי השיר יוצאין בשיר בשבת שהוא אצעדה מברזל או מדבר אחר המסבב לצואר החיה כידוע וכן כל דבר עגול נקרא שיר בלה\"ק כידוע וגם השירה בניגון הוא בא בבחי' עיגול ממש כעיגול הגשמי של השיר הגשמי דהנה אנו רואי' בחוש וידוע לכל יודעי נגן בקולות התנועות של הניגון המורכבים שכל אחד מהם מתקשר אל חבירו ומשתלשלי' מתנועה לתנועה עד שיש קשר וחיבור גם לסופו של הניגון עם התחלתו שהרי מיד כשמסיים הניגון מכריחו לחזור לראש הניגון וכאילו סופו עם תחלתו נמשכין בהמשך אחד וענין אחד ובאם שלא יחזור לראש הניגון מיד שסיים את סופו ה\"ז כאילו נשאר באמצע הענין והכונה כי קולו' הניגון כולם הם מורכבים יחד בהתכללות כ\"כ עד שבלתי נמצא בהן ראש וסוף כלל כמו העיגול גשמי שאין בו מעלה ומטה ולא ראש וסוף כך בניגון בכל פרקיו הוא מתאחד כא' שתחלתו נעוץ בסופו וסופו נעוץ בתחלתו וע\"כ כאשר מסיים הניגון מיד חוזר לראשו משא\"כ מניגון לניגון אחר יש הפסק בקול בהכרח כידוע וד\"ל.\n<b>והדוגמא</b> מעיגול זה בקול הניגון יש להבין בעונג ומתיקות שבניגון שבהכרח גם הוא בא בבחי' עיגול רוחני כי שרש הניגון הוא העונג המופלא שהוא בבחי' מקיף דוקא ולכך לא יוכל לבא לידי גילוי בדיבור רק בקול הניגון היוצא מהבל הלב בלבד לפי שלא יתיישב העונג בבחי' א\"פ בכלי הדיבור כו' וכמ\"ש במ\"א ולפ\"ז יובן הנמשל למעלה ג\"כ בבחי' עונג העליון האלקי המלובש בשיר וניגון הטעמי' שבתורה וכמ\"ש ואהי' אצלו שעשועי' וכנ\"ל בפי' ובלילה שירו עמי ג\"כ הוא בא בבחי' מקיף כמו העיגול והיינו בחי' &lt;שעה&gt;\nסובב כ\"ע שאין שם בחי' מעלה ומטה ולא",[["5459","103","<b>עקב יו\"ד עקב</b>: ע\"ח שער ג (שער סדר האצילות) פ\"ב. תו\"א ויצא כא, א."],["5460","104","<b>ויהי בישורון מלך. . בפי' ישורון</b>: ברכה לג, ה. ראה סה\"מ תרכ\"ו ע' רצב. תרכ\"ט ע' שכו."],["5461","105","<b>ישורון. . לשון שירה</b>: ראה לקו\"ת נצבים מה, א. אוה\"ת ברכה ע' א'תתנג. א'תתסט."],["5462","106","<b>שהשיר הוא דבר העגול</b>: ראה ג\"כ לקו\"ת שה\"ש א, ג. מאמרי אדה\"א דברים ח\"ד ע' א'שנג."],["5463","107","<b>כל בעלי השיר יוצאין בשיר</b>: שבת נא, ב. וראה תו\"ח פקודי ע' תרסט. סה\"מ תקס\"ח ח\"א ע' תקנג-ד."]]],[2100990370,"ראש וסוף כמאמר נעוץ<sup data-n=\"5464\">108</sup> תחלתן בסופן וסופן בתחלתן כו' וכמ\"ש ומתחת<sup data-n=\"5465\">109</sup> זרועו' עולם וכן המגביהי<sup data-n=\"5466\">110</sup> לשבת המשפילי<sup data-n=\"5467\">111</sup> לראות כו' כמו העיגול הגשמי למעלה הוא גבוה ביותר ולמטה הוא נמוך ביותר שלפי שאין בו מעלה ומטה מטה ומעלה שוין עד שנמצא למטה כמו למעלה בהשווא' א' ממש וכמ\"ש במ\"א.\n<b>וזהו</b> ויהי בישורן מלך פי' ישורון מלשון שיר שהוא עגול כנ\"ל כך בחי' שעשועי המלך בעצמותו שמאיר בשיר וניגון בטעמי' שבתורה וכיוצא עונג העליון הזה הוא בא בבחי' מקיף כעגול השיר והטבעת ונק' ישורון ומהארה זו נמשך למטה ונעשה בחי' כתר מלכו' כנ\"ל שמבחי' השעשועי' הללו נמשך הוד לבושי מלכות כנ\"ל אך אין מקיף זה מתעורר למעלה כ\"א ע\"י הברורי' ממעשה המצות דוקא והיינו שסמך לומר ויהי בישורון מלך אחר שאמר תורה ציוה לנו משה כו' כי הא בהא תליא כמבואר עפ\"י כל הנ\"ל וד\"ל.\n<b>בהתאסף</b> ראשי עם יחד שבטי ישראל. פי' כל הנ\"ל בהמשכת אור מקיף בבחי' שעשועי' שבניגון ושיר כו' אין זה אלא בהתאסף כל הראשי\"ם יחד כלומר שלא יהי' התחלקות כמה ראשים אלא יתכללו כללו' נ\"י כאיש אחד ולא יהי' להם רק ראש אחד ולא כמה ראשים וכענין מה שנא' לעתיד ולא<sup data-n=\"5468\">112</sup> ילמדו עוד איש את רעהו כי כולם ידעו אותי כו' לפי שיתכללו ויתאחד<sup data-n=\"5469\">*112</sup> כנ\"י כאיש אחד שאין בו אלא ראש אחד ואז דוקא שורה עליהם בחי' אור מקיף הנ\"ל לפי שאין אור מקיף שורה כ\"א בבחי' היחוד והאחדו' כשכלולים יחד מראש לרגל כו' ואין בהן מעלה ומטה כו' אז ישכון עליהם ג\"כ בחי' אור מקיף להאיר על כללותם יחד לראש ורגל בהשווא' א' כו' וכעין זה הי' בשעת מ\"ת דכתיב ויחן<sup data-n=\"5470\">113</sup> ישראל לשון יחיד שהיו כולם כאיש אחד לכך זכו לבחי' כתר תורה שהוא בחי' מקיף הנ\"ל משעשועי המלך בעצמו הנק' ישורון כנ\"ל וכן אנו אומרי' ברכינו<sup data-n=\"5471\">114</sup> אבינו כולנו כאחד דוקא באור פניך וכמ\"ש יאר<sup data-n=\"5472\">115</sup> ה' פניו אליך אליך לשון יחיד כשהם כלולים כאיש א' אזי יאר ה' פניו מהארת השעשועי' הנ\"ל והיינו שאמר ויהי בישורון מלך בהתאסף ראשי עם יחד פי' אין בישורון מלך אלא דוקא בהתאסף ראשי עם יחד מטעם הנ\"ל וד\"ל.\n&lt;שעו&gt;\n<b>ומה</b> שאמר שבטי ישראל היינו מטעם הנ\"ל בפי' ישראל כי שרית עם אלקים דהיינו להפוך הרע לטוב והשתררו' זאת ע\"י בחי' ישראל דוקא והוא שרש הנשמה שעלה במחשבה ומצד התלבשות' בגוף נק' יעקב יו\"ד עקב כנ\"ל. ונמצא יש כאן ג' מדרגות יעקב וישראל וישורון, ומתחלה צ\"ל בחי' יעקב ואח\"כ ישראל ואח\"כ עולה",[["5464","108","<b>נעוץ תחלתן בסופן</b>: ס\"י פ\"א מ\"ז."],["5465","109","<b>ומתחת זרועו' עולם</b>: ברכה לג, כז."],["5466","110","<b>המגביהי לשבת</b>: תהלים קיג, ה."],["5467","111","<b>המשפילי לראות</b>: שם ו."],["5468","112","<b>ולא ילמדו עוד איש את רעהו</b>: ירמי' לא, לג."],["5469","*112","<b>ויתאחד</b>: באוה\"ת שם: ויתערבו."],["5470","113","<b>ויחן ישראל לשון יחיד</b>: יתרו יט, ב. פירוש רש\"י שם."],["5471","114","<b>ברכינו אבינו כולנו באחד. . באור פניך</b>: בברכת שים שלום בתפלת העמידה."],["5472","115","<b>יאר ה' פניו אליך</b>: נשא ו, כה."]]],[2100990371,"למעלה העליונה מכולם לבחי' ישורון שהוא בחי' עונג העליון הבא למטה בבחי' מקיף הנק' שעשועי המלך בעצמותו כו' וזהו בהתאסף ראשי עם מכל בחי' שבטי ישראל בכלות הבירור על ידן אזי דוקא ויהי בישורון מלך והיינו כמו לימות המשיח דכתיב ולא ילמדו עוד איש את רעהו כו' ואז כתיב ושמו<sup data-n=\"5473\">116</sup> להם ראש אחד כו' ראש אחד דוקא והיינו בחי' מקיף הנ\"ל הנק' ישורון וזהו ויהי בישורון מלך בהתאסף ראשי עם יחד שבטי ישראל וד\"ל.",[["5473","116","<b>ושמו להם ראש אחד</b>: הושע ב, ב."]]],[2100990372,"<h3>להבין שרש הדברים</h3>\n<b>בעזר\"ה</b>\n<b>להבין</b><sup data-n=\"5474\">1</sup> שרש הדברים הנ\"ל. הנה להבין שרש ענין תורה ציוה לנו משה כו' הנה יש להקדים תחלה בענין הברורי' כו' דהנה ידוע דבחכמה<sup data-n=\"5475\">2</sup> אתברירו וסדר הברורי' תחלה הי' הבירור לפני האצי' והמובחר שנתברר נעשה בחי' אצי' והן ז'<sup data-n=\"5476\">3</sup> מלכי' דתוהו שהי' בהן השבירה כנודע שנתבררו לפני האצי' והיינו מבחי' נקודי' שהי' בהם השבירה נעשה בחי' ברודים שהוא בחי' התיקון דאדם דאצי' כידוע ואח\"כ נתברר באצי' עצמו כו' והיינו מה שיוכל להיו' בבחי' ביטול בערך האצי' נתברר והוא בחי' המובחר והפסולת נפל לבריא' וגם שם מתברר עד\"ז אך שבבריא' בחי' הביטול אינו בערך בחי' הביטול שבאצי' כו'.\n<b>ויובן</b> ביאור דבר זה בהקדים ענין הידוע בענין ע\"ס<sup data-n=\"5477\">4</sup> בלי מה להיות כי אור א\"ס בעצמו הוא אור פשוט בתכלית הפשיטות ומופשט ומושלל לגמרי מבחי' מציאת דבר מה כי הוא בחי' אין המוחלט כו' וידוע הכלל שמאחדות הפשוטה לא יסתעף בשפע אור כ\"א ג\"כ בחי' אחדות פשוטה ולא בחי' מציאת יש ודבר מה ואמנם הנה אנו רואים שנאצלו מעצמו' אור א\"ס ע\"ס דאצי' שהן עכ\"פ בבחי' איזה מציאו' דבר מה אבל הענין הוא דע\"ס דאצי' נק' ע\"ס בלי מה בלי מהות דהיינו שאע\"פ שנאצלו מן המאציל בבחי' איזה מציאות עכ\"פ אבל הן דבוקים תמיד בבחי' הביטול בתכלית בעצמו' המאציל עד שהן מופשטי' מבחי' מהו' והיינו בלי מה כו' ועד\"ז הולך ומשתלשל האור והשפע מאצי' לבי\"ע וכל שהאור ושפע נמשך למטה יותר יותר נראה לבחי' יש כי בחי' הביטול אשר יש בו אינו בערך בחי' הביטול הקרוב יותר אל המאציל כו'.",[["5474","1","<b>להבין שרש הדברים הנ\"ל</b>: הנחת כ\"ק אדה\"א. נעתק מגוכתי\"ק 1025 (קט, א).\nמאמר זה נדפס ג\"כ באוה\"ת ברכה כרך ד ע' א'תתסג."],["5475","2","<b>דבחכמה אתברירו</b>: ראה זהר (היכלות) פקודי רנד, סע\"ב. וראה הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא."],["5476","3","<b>ז' מלכי' דתוהו</b>: ראה וישלח לו, לב. ראה זהר (אדרא רבא) נשא קכח, א. ע\"ח שער הכללים פ\"א. שם (שער דרושי הנקודות) ש\"ח פ\"ד."],["5477","4","<b>ע\"ס בלי מה</b>: ס\"י פ\"א, מ\"ב ובמפרשים שם."]]],[2100990373,"<b>ויובן</b> ביותר דבר זה בקדוש' האלקי' מהיפכו בסט\"א דאת<sup data-n=\"5478\">5</sup> זלע\"ז עשה האלקי' כו' והנה אנו רואי' דפעם אמרו<sup data-n=\"5479\">*5</sup> ז\"ל שטן<sup data-n=\"5480\">6</sup> ופנינה לש\"ש נתכוונו ופעם אמרו נתן<sup data-n=\"5481\">7</sup> עיניו במקדש ראשון כו' הרי יש בשטן כוונה לש\"ש לפעמי' ולפעמי' כוונתו לרע ג\"כ כמו נתן עיניו כו' אך הענין הוא דשרש בחי' הנחש הקדמוני שהי' בג\"ע הנה ישנו בכל עולם ועולם לפי אותו העולם ואם הוא בעולם הבריא' ימצא בו קצת ביטול לקדוש' כי בעולם הבריא'<sup data-n=\"5482\">8</sup> רובו טוב ומיעוטו רע כו' והיינו נתן עיניו כו' וכן קנא' של נחש שהי' בג\"ע דבריא' כו' ושרש הנחש כמו שהוא בבחי' האצי' דאין שם רע כלל כי לא<sup data-n=\"5483\">9</sup> יגורך רע כתיב שם אמרו דכוונתו לש\"ש בלבד אך ענין הנחש והשטן איך שיוכל להיו' בבחי' האצי' הנה ידוע שהוא רק בחי' הרגשת עצמותו ליש ודבר גדול ולא ענין רע כלל כו' וכמ\"ש ופלגשו<sup data-n=\"5484\">10</sup> ושמה ראומה פי' ראו<sup data-n=\"5485\">11</sup> שאני מה שמרגיש במעלת עבודתו כו' וכמ\"ש<sup data-n=\"5486\">12</sup> במ\"א וד\"ל ועד\"ז יובן איך שיש כמה מדרגו' באופן בחי' הביטול בסטרא דקדושה וכל הגבוה גבוה יותר יש בו בחי' הביטול וכמ\"ש הן<sup data-n=\"5487\">13</sup> שמים לא זכו בעיניו משום דלפי ערך הרוממו' בחי' הביטול שלהם לבחי' יש יחשב כו' וד\"ל.\n<b>והנה</b> ע\"י בחי' הברורי' הנ\"ל בכל עולם לפי ערכו נמצא בחי' הביטול יותר מכפי המדה הראשונה באבי\"ע כו' ולזה ניתן בחי' קו המדה איך וכמה יתברר כו' וקו המדה הזה הוא בחכמה דבחכמה אתברירו דוקא אבל אין הכוונה על בחי' חכמה דאצי' אחר &lt;שעז&gt;\nשגם היא באה להתברר כנ\"ל שהאצי' כולו ג\"כ מתברר כו' אלא הכונה על בחי' חכמה דא\"ק שמשם נמשך שרש כל הברורי' של כל ההשתלשלו' דאבי\"ע כו' ודרך כלל הנה ידוע דיש ד' מדרגו' טנת\"א וידוע שהשבירה היתה בבחי' נקודי' דבינה דאורו' דז' מלכי' דתוהו מבחי' ז\"ת דבינה הן והבירור הוא בבחי' טעמים שבחכמה כי בחי' הטעמי' בחכמה הן כמו השכל וסברא שנק' בשם טע\"ם דוקא כמו מאי<sup data-n=\"5488\">14</sup> טעמ\"א דר' מאיר קסבר כו' הרי הסברא נק' טעם לפי שהטעם והמתיקו' הוא בתענוג כידוע וכאשר בחי' התענוג מלובש ומאיר בחכמה אז נק' החכמה והשכל הזה בשם טעם כמו טוב<sup data-n=\"5489\">15</sup> טעם ודעת למדני כו' והוא בחי' אור המקיף לחכמה זו כו'",[["5478","5","<b>דאת זלע\"ז עשה האלקי'</b>: לשון הכתוב קהלת ז, יד."],["5479","*5","<b>דפעם אמרו</b>: ראה לקו\"ת חקת סב, א. מסעי צב, א. סה\"מ תרל\"ב ח\"א ע' רסט."],["5480","6","<b>שטן ופנינה לש\"ש נתכוונו</b>: ב\"ב טז, א. ראה מאמרי אדה\"ז אתהלך לאזניא ע' קנה. וראה לעיל בהביאור ד\"ה החלצו."],["5481","7","<b>נתן עיניו במקדש ראשון</b>: סוכה נב, א. וראה מאמרי אדה\"א דברים ח\"ב ע' תקנז וע' תרצב."],["5482","8","<b>הבריא' רובו טוב ומיעוטו רע</b>: ע\"ח שער מב פ\"ד. שם שער מז, פ\"ד. אמת ליעקב מערכת א' אות רמג. סה\"מ תקס\"ג ח\"ב ע' תצא. לקו\"ת במדבר ג, ד. דרך מצותיך לא, ב. ובכ\"מ."],["5483","9","<b>לא יגורך רע</b>: תהלים ה, ה."],["5484","10","<b>ופלגשו ושמה ראומה</b>: וירא כב, ד."],["5485","11","<b>ראו. . מה</b>: ראה לקו\"ת ויקרא ג, א. ראה מאמרי אדה\"א דברים כרך ד ע' א'תצג ובהנסמן שם."],["5486","12","<b>וכמ\"ש במ\"א</b>: ראה לקו\"ת תזריע כג, ד. בהר מג, א."],["5487","13","<b>הן שמים לא זכו בעיניו</b>: איוב טו, טו."],["5488","14","<b>מאי טעמ\"א דר' מאיר קסבר</b>: ראה ב\"ק ה, ב. נדה יח, ב."],["5489","15","<b>טוב טעם ודעת למדני</b>: תהלים קיט, סו."]]],[2100990374,"והנה דרך כלל יש בחי' טנת\"א בא\"ק עצמו ובחי' הנקודי' הוא באורו' העיני' דא\"ק כו' ובחי' הטעמים הוא במצחא דא\"ק והוא הארת שם מ\"ה<sup data-n=\"5490\">16</sup> החדש שמאיר במצחא דא\"ק למטה כדי לברר כל הברורי' שהי' בהן השבירה מבחי' נקודי' דאורו' עיני' כו' כי בחכמה אתברירו דוקא והיינו בבחי' חכמה דא\"ק שמלובש בו אור המקיף דבחי' הטעמי' דא\"ק והוא בחי' המקיף היותר כללי שכולל להקיף כל ההשתלשלו' כו' עד עיגולי א\"א דעשי' שמקיף מתחת רגלי העשי' כו' וד\"ל.\n<b>ואחר</b> הקדמה זו יובן שרש ענין תורה ציוה לנו משה כו' דמשה<sup data-n=\"5491\">17</sup> הוא בחי' יסוד אבא וזהו תורה ציוה לנו משה משום דאוריי'<sup data-n=\"5492\">18</sup> מחכמה עילא' דאבא נפק' כידוע אך להיות כי שרש החכמה שבתורה הוא מבחי' החכמה דא\"ק כי שרש החכמה שבתורה הוא כדי לברר ברורי נוגה ע\"י המצות הנעשו' בדצ\"ח דנוגה כנ\"ל והיינו בחי' הטעמי' שבחכמה דא\"ק כנ\"ל שהוא שרש כל הברורי' דתוהו כנ\"ל ע\"כ אמר תורה ציוה לנו משה מורשה פי' מורשה לפי שע\"י הבירור הזה בשם מ\"ה דא\"ק הנה בחי' התיקון הוא יורש יור\"ש את בחי' התוהו כמ\"ש למכה<sup data-n=\"5493\">19</sup> מלכים גדולים כו' ונתן<sup data-n=\"5494\">20</sup> ארצם לנחלה נחלה לישראל עבדו כו' כי השבירה דז' מלכי' כאשר באו לידי בירור ותיקון ניתנו למורשה למי שמתקן אותם כו' וד\"ל.\n<b>וזהו</b> ג\"כ פי' קהלת יעקב דהנה ידוע<sup data-n=\"5495\">21</sup> דהקליפה<sup data-n=\"5496\">22</sup> קדמה לפרי כמו עד\"מ<sup data-n=\"5497\">23</sup> שהשליא יוצאת קודם לולד וידוע שהשליא גם היא נעשית מן ההשפעה שממנה נוצר הולד אך שהשליא נעשית מבחי' החיצוניו' כדי להיו' שומר ומקיף להלביש לולד בהיותו בבטן אמו כל ט\"ח אבל הולד הוא נוצר מבחי' הפנימי' כו' ומ\"מ ביציאה לאויר העולם השליא קודמת לצאת ואח\"כ הולד כי הקליפה קודמת לפרי כו' וכך הי' בעשו ויעקב דכתיב ויצא<sup data-n=\"5498\">24</sup> הראשון אדמוני כולו כאדרת שער כי עשו<sup data-n=\"5499\">25</sup> איש שעיר מבחי' הפסולת דז' מלכי אדום שמלכו לפני מלוך מלך לבני ישראל כו' בבחי' שליא פסולת השפע שקדמה לפרי ואח\"כ יצא יעקב<sup data-n=\"5500\">26</sup> שהוא בחי'",[["5490","16","<b>מ\"ה החדש שמאיר במצחא</b>: ראה ע\"ח (שער התיקון) ש\"י, פ\"ב."],["5491","17","<b>דמשה הוא בחי' יסוד אבא</b>: ראה לקו\"ש ח\"ו ע' 244 ואילך."],["5492","18","<b>אורייתא מחכמה עילא'</b>: זח\"ב פה, א. ועוד."],["5493","19","<b>למכה מלכים גדולים</b>: תהלים קלו, יז."],["5494","20","<b>ונתן ארצם לנחלה נחלה לישראל עבדו</b>: תהלים קלו, כא. כב. וראה גם מאמרי אדה\"א שמות ח\"ב ע' תקנד. דברים ח\"א ס\"ע ד ואילך. וש\"נ."],["5495","21","<b>דהנה ידוע</b>: בהבא לקמן ראה ג\"כ תו\"ח וישלח קפה, א ואילך."],["5496","22","<b>דהקליפה קדמה לפרי</b>: ראה זהר (סבא) משפטים קח, רע\"ב. פרדס סוף שער (כה) התמורות. לקו\"ת וספר הליקוטים (להאריז\"ל) וישלח לו, לא. ביאוה\"ז פנחס קיז סע\"ב ואילך. שער היחוד פנ\"ד."],["5497","23","<b>עד\"מ שהשליא יוצאת</b>: ראה תו\"ח שם: וכמשל השפופרת הסתומה מצד אחד שהנכנס ראשון יוצא אחרון [ראה ב\"ר פס\"ח, ח. הובא ברש\"י תולדות כה, כו. סה\"מ תקס\"ה ח\"ב ע' תשי. מאמרי אדה\"א בראשית ע' קמט. וראה תו\"ח שם קסא, א. קפט, א]."],["5498","24","<b>ויצא הראשון אדמוני כולו כאדרת שער</b>: תולדות כה, כה."],["5499","25","<b>עשו. . הפסולת דז' מלכי אדום</b>: וישלח לו, לא. וראה תו\"ח בראשית ח, א."],["5500","26","<b>יעקב. . בחי' התיקון</b>: ראה ג\"כ תו\"ח נח סד, ד. קסב, ב. דרך מצותיך קנב, א."]]],[2100990375,"התיקון כי שרשו מבחי' חכמה דא\"ק כמאמר ישראל<sup data-n=\"5501\">27</sup> עלה במחשבה דא\"ק כו' ולכך יעקב ירש את ז' אומו' דתוהו הכנעני כו' כי בחי' התוהו ניתן למורשה לבחי' התיקון כנ\"ל וד\"ל.\n<b>וזהו</b> מורשה קהלת יעקב שהירושה של ז' מלכי' שיורש אותם יעקב בעל התיקון הנה הן כולם מתקבצים ונאספים כולם כאחד ונכללי' ע\"י &lt;שעח&gt;\nבבחי' התיקון דיעקב ונקראי' קהלת יעקב דהיינו קהל הגדול של ריבוי<sup data-n=\"5502\">28</sup> הניצוצי' דרפ\"ח שנקהלו אל יעקב לבררם עד שנקראו על שמו קהלת יעקב כידוע דיעקב<sup data-n=\"5503\">29</sup> הוא יו\"ד עקב דהיינו מה שבחכמה נתברר בחי' העקביים כו' ואח\"כ נקראו שבטי ישראל כי<sup data-n=\"5504\">30</sup> שרית עם אלקים דהיינו שבירר שם ב\"ן דתוהו שנק' אלקי' ופי' עם אלקים שגם הטבע מסייע כנ\"ל לפי שהטבע נמשך מבחי' התוהו שרוצה מצד עצמו להתתקן וכענין קהלת יעקב שנקהלו אל יעקב לבררם וכמ\"ש ונהרו<sup data-n=\"5505\">31</sup> אליו כל הגוים כו' וכן ובאו<sup data-n=\"5506\">32</sup> גוים רבים ואמרו לכו ונעלה אל הר ה' אל בית אלקי יעקב כו' וד\"ל.\n<b>ועתה</b> יש להבין שרש ענין ויהי בישורון מלך כו'. דהנה שרש ענין ובלילה<sup data-n=\"5507\">33</sup> שירה עמי ושירו קרי כמ\"ש ואהי'<sup data-n=\"5508\">34</sup> אצלו שעשועים כו' שהוא ענין רננה דאוריי' כו' כנ\"ל הנה ביאור הדברים לפי שיש בתורה ג\"כ ד'<sup data-n=\"5509\">35</sup> מדרגות טנת\"א<sup data-n=\"5510\">36</sup> והמדרגה היותר עליונה הן הנק' טעמי תורה כלומר בחי' התענוג שבחכמה שבתורה ושרשו הוא בחי' טעמי' דחכמה דא\"ק כנ\"ל שהוא בחי' מקיף היותר כללי כו' שהוא כמו ענין השיר והניגון שאנו רואים שיש בשיר וניגון בחי' עיגול כי נעוץ בו התחלה בסוף כמבואר למעלה והיינו ג\"כ כמו השיר והוא טבעת העגול הסביב לצואר החיו' שנקראו בעלי השיר וכו' וכל זה לפי שבניגון יש הארת התענוג אשר בחכמה שהוא בחי' מקיף לחכמה כנראה בחוש שכל כונה אשר לא יוכל שאת בהשגה והבנה יוכל לכוון אותה הכוונה בניגון ושיר כו' כי העונג הבלתי מתיישב בשכל והשגה מתלבש בניגון וע\"כ הניגון עגול כטבעת ע\"ש בחי' המקיף דעונג שהוא כמו עגול להקיף לחכמה כו' וד\"ל.",[["5501","27","<b>ישראל עלה במחשבה</b>: ראה ב\"ר פ\"א, ד."],["5502","28","<b>ריבוי הניצוצי' דרפ\"ח. . שם ב\"ן</b>: ראה ע\"ח שער (יח) רפ\"ח ניצוצין פ\"ב. הגהת מהרנ\"ש לאוצרות חיים שער הנקודים בסופו סק\"ב [מבוא שערים תל-אביב תשכ\"א שס, סע\"ב ואילך]."],["5503","29","<b>דיעקב הוא יו\"ד עקב</b>: ע\"ח שער ג (שער סדר האצילות) פ\"ב. תו\"א ויצא כא, א."],["5504","30","<b>כי שרית עם אלקים</b>: וישלח לב, כט."],["5505","31","<b>ונהרו אליו כל הגוים</b>: ישעי' ב, ב."],["5506","32","<b>ובאו גוים רבים</b>: שם ג — והלכו עמים רבים ואמרו לכו ונעלה אל הר ה' אל בית אלקי יעקב."],["5507","33","<b>ובלילה שירה עמי</b>: תהלים מב, ט."],["5508","34","<b>ואהי' אצלו שעשועים</b>: משלי ח, ל."],["5509","35","<b>ד' מדריגות טנת\"א</b>: ראה ע\"ח שער דרושי אבי\"ע פ\"א. וראה תו\"א ויחי מח, ב. לקו\"ת חקת נז, ד."],["5510","36","<b>טנת\"א. . טעמי' דחכמה</b>: ראה בפרדס שער כז, פ\"ג. ובשער הטעמים פ\"ה. וראה באוה\"ת שמות כרך ז ע' ב'תקעה. ביאוה\"ז להצ\"צ כרך א ע' שיט. אוה\"ת דברים כרך ה ע' ב'מח. דרך מצותיך קלג, א."]]],[2100990376,"<b>וזהו</b> ובלילה שירו עמי פי' שירו היינו רננה דאוריית' שהוא הנגינות והטעמים דאותיו' התורה שנק' טעמי תורה ובחי' הטעמי' הוא נמשך מבחי' המקיף הכללי שהוא בחי' טעמי' שבחכמה דא\"ק וכנ\"ל לכך נק' שירו ולא שירה דהיינו בחי' שעשועי המלך בעצמו הנ\"ל להיות כי איננו מתיישב אותו העונג העליון בחכמה רק בבחי' מקיף והוא הניגון שבטעמי' ונגינו'<sup data-n=\"5511\">37</sup> כמו זרקא מקף כו' שהוא על האותיות שבתורה וזהו ואהי' אצלו כו' שעשועי' שעשועי עצמו' המאציל ומעונג זה נמשך בחכמה דא\"ק שהוא שם מ\"ה במצחא דא\"ק שרש המברר כל הברורי' כנ\"ל ולכך נק' שירו של הקדב\"ה בעצמו כו' וד\"ל.\n<b>וזהו</b> ויהי בישורון מלך. פי' ישורון<sup data-n=\"5512\">38</sup> מלשון שיר וניגון שהוא עגול כטבעת כי אחר שאמר תורה ציוה לנו משה בבחי' הברורי' שע\"י החכמה דא\"ק כנ\"ל אח\"כ אמר על בחי' המקיף הכללי דהיינו טעמי' שבחכמה הנשאר בבחי' מקיף על החכמה דא\"ק שהוא כמשל עיגול שאין בו מעלה ומטה כלל ולמעלה הוא כמו למטה כי נעוץ<sup data-n=\"5513\">39</sup> בו סופן בתחלתן ותחלתן בסופן כמו הניגון כו' וכמ\"ש ומתחת<sup data-n=\"5514\">40</sup> זרועות עולם כו' והיינו כמו ענין עגולי א\"א שמקיפי' רגלי העשי' עם חכמה דאצי' בהשווא' א' ולכך נק' ישורון מלשון ישר לפי שהוא שוה<sup data-n=\"5515\">41</sup> ומשוה קטן וגדול מעלה ומטה כו' וזהו ויהי בישורון &lt;שעט&gt;\nמלך לפי שמבחי' אור מקיף זה נמשך בחי' כתר לתורה ונק' כתר תורה והרי ידוע דג'<sup data-n=\"5516\">42</sup> כתרים הן כתר תורה וכתר כהונה וכתר מלכו' ולהיו' כי נעוץ סופן בתחלתן דוקא ע\"כ מבחי' כתר דתורה נמשך בחי' כתר מלכות כו'.\n<b>וזהו</b> ובלילה שירה שיר ה' כו' והוא ג\"כ שרש ענין המשכת י\"ג מדה\"ר במלכות כמ\"ש יאר<sup data-n=\"5517\">43</sup> ה' פניו אליך דוקא כי להיות בחי' המל' סופא דכל דרגין באצי' כידוע והנה מלבד זה הנה היא מסתתרת למטה מטה להיות ראש לשועלי' בבי\"ע עד רגלי העשי' כו' ע\"כ צריכה שמירה ביותר מן החיצוני' דנוגה דבי\"ע שלא יחשיכו אורה ודוקא השומר היותר עליון והוא המקיף היותר עליון דהיינו בחי' הארת הפנים די\"ג תקונין דא\"א במל' וזהו שאמרו שאין<sup data-n=\"5518\">44</sup> אשה אלא ליופי לפי שצריך שיאירו פניה מהארה היותר עליונה מטעם הנ\"ל וכמ\"ש<sup data-n=\"5519\">45</sup> במ\"א והיינו ג\"כ הטעם שמבחי' כתר תורה הנ\"ל שנמשך ממנו כתר מלכו' וכמ\"ש וכבוד<sup data-n=\"5520\">46</sup> הדר מלכותו בחי' הוד והדר דמדת מל' דאצי' שמקבלת מכתר תורה הנ\"ל משעשועי המלך בעצמותו הנ\"ל בטעמי תורה שהוא רננה דאוריי' ולפ\"ז הקרי שירו והכתיב שירה שניהם אמת והיינו ויהי בישורון מלך לפי שמבחי' כתר תורה נמשך מקיף להדר ולייפו' לבחי' מלך",[["5511","37","<b>ונגינו'. . זרקא מקף</b>: ראה ג\"כ דרך מצותיך מג, ב. ועוד."],["5512","38","<b>ישורון מלשון שיר</b>: ראה לקו\"ת נצבים מה, א. ועוד."],["5513","39","<b>נעוץ בו סופן בתחלתן</b>: ס\"י פ\"א מ\"ז."],["5514","40","<b>ומתחת זרועות עולם</b>: ברכה לג, כז."],["5515","41","<b>שוה ומשוה קטן וגדול</b>: לשון פיוט ”וכל מאמינים\"."],["5516","42","<b>דג' כתרים הן</b>: אבות פ\"ד מי\"ג."],["5517","43","<b>יאר ה' פניו</b>: נשא ו, כה."],["5518","44","<b>שאין אשה אלא ליופי</b>: כתובות נט, ב. וראה פירוש המלות קיא, ג."],["5519","45","<b>וכמ\"ש במ\"א</b>: ראה לקו\"ת שה\"ש מ, א."],["5520","46","<b>וכבוד הדר מלכותו</b>: תהלים קמה, יב."]]],[2100990377,"להיו' כבוד הדר מלכותו כו' אך אם לא הברורי' שקדמו בחכמה לא הי' נמשך המקיף בטעמי תורה כו' לכך אמר תחלה תורה ציוה לנו משה כו' ואח\"כ ויהי בישורון מלך וד\"ל.\n<b>בהתאסף</b> ראשי עם יחד שבטי ישראל. פי' ראשי עם היינו בחי' המוחין שנק' ראש כידוע ויש כמה ראשים דהיינו כמה מיני מוחין ודרך פרט בכל ר\"ח הוא הראש לאותו החדש ודרך כלל כל החדשים נכללי' בחדש<sup data-n=\"5521\">47</sup> תשרי שהוא הראש הכללי לכולם ונק' החדש הזה בכללו ראש השנה והמופת לזה הוא ממה שבחדש הזה יש ימים שהן שרשיים ומקוריים לכל חדשי השנה ליראה דהיינו שיוכללו כללו' נ\"י להתפעל בכל חדשי השנה ביראה ויש ימים בחדש זה שהן שרשיים ומקוריים שיוכלו כנ\"י להתפעל באהבה ושמחה כל השנה ויש ימים שהן שרשיים ומקוריים להתשובה והמחילה והסליחה כמו יום ר\"ה<sup data-n=\"5522\">48</sup> עצמו הוא בחי' מקור ליראה שמקבלי' ישראל יראה באותו היום על כל השנה ויו\"כ מקור לתשובה ומחילה וסליחה על כל השנה וז' ימי הסוכו' מקוריים לאהבה ושמחה על כל השנה לפי שכל חדש הזה נקרא ראש וכמו שהראש הוא מקור לכל האיברי' כך חדש תשרי נק' ראש להיו' מקור לכל הדברים המסתעפי' בכנ\"י כל השנה כו' וד\"ל.\n<b>והנה</b> ז'<sup data-n=\"5523\">49</sup> ימי הסוכו' ע\"י השמחה נעשה בחי' אור מקיף וכידוע שז' ימי החג נמשך בכל יום מקיף א' וכללותם הן ז' מקיפי' דאימא כו' כי המצות<sup data-n=\"5524\">50</sup> כללותם ז' ספי' דז\"א בלבד כי הרי הן נק' רמ\"ח איברי' דמלכא וכללו' כל האיברי' הוא הנק' גופא דמלכא שהן ז' המדות דז\"א כידוע ומקיפי' שלהם מאימא נמשך כל ז' ימי החג אך הנה ביום שמחת<sup data-n=\"5525\">51</sup> תורה נמשך בחי' מקיף העליון הכללי שכולל כולם יחד שהרי נק' שמחת תורה ולא שמחה של מצוה כו' והענין של זאת השמחה הוא בחי' אור המקיף של התורה עצמה והרי היא כללות כל המצות &lt;שפ&gt;\nדהיינו כללות כל המוחין שבמדו' דגופא דמלכא נכללי' בחכמה שבתורה כידוע וא\"כ גם בחי' אור המקיף של התורה דהיינו מה שלא יוכל להתלבש גם בחכמה שבתורה ונשאר בבחי' מקיף שהוא בחי' שעשועי<sup data-n=\"5526\">52</sup> המלך בעצמו הנק' כתר תורה כנ\"ל הרי הוא מקיף היותר כללי שמקיף כללו' המוחין שבראש דהיינו כללו' המוחין שבראש זה הכולל כל החדשי' והוא כל חדש תשרי כו' וד\"ל.",[["5521","47","<b>בחדש תשרי שהוא הראש הכללי לכולם. . ראש השנה</b>: ראה סד\"ה צהר תעשה תש\"ב (סה\"מ תש\"ב ע' 49) הועתק בהקדמת קונטרס שמע\"צ — שמח\"ת (סה\"מ תשי\"א ע' 78)."],["5522","48","<b>ר\"ה. . יראה. . ויו\"כ מקור לתשובה</b>: ראה סה\"מ תרל\"ב ח\"ב ע' תקפט — כי ר\"ה ויוהכ\"פ הוא מקור על יראה על כל השנה כמ\"ש במד\"ר כי עמך הסליחה למען תורא הסליחה מופקדת אצלך מר\"ה עד יוהכ\"פ שיבא לשלימות היראה."],["5523","49","<b>ז' ימי הסוכו'. . מקיפי' דאימא</b>: ראה מאו\"א ס, טו. (סוכה הוא אור המקיף בבינה) — מזוהר ותקו\"ז."],["5524","50","<b>המצות. . רמ\"ח איברין דמלכא</b>: ראה תקו\"ז ת\"ל (עד, סע\"א)."],["5525","51","<b>שמחת תורה. . מקיף העליון</b>: ראה סה\"מ תרנ\"ד ע' לו. תש\"ב ע' 49. ועוד."],["5526","52","<b>שעשועי המלך בעצמו</b>: נתבאר בעמק המלך שער א. וראה לקו\"ת שה\"ש כז, סע\"א."]]],[2100990378,"<b>וזהו</b> בהתאסף ראשי עם פי' בהתאסף כל הראשים יחד כמשל המוחין שבראש שיש בהן ג' מדרגו' דהיינו בג'<sup data-n=\"5527\">53</sup> חללי' דגלגלתא מוח החכמה מיוחד בפ\"ע ומוח הבינה מיוחד בפ\"ע ומוח הדעת בפ\"ע ולכולם יש בחי' מקיף אחד הכוללם יחד דהיינו שחופף עליהם להקיפם כאחד ולא להקיף לכאו\"א בפ\"ע והוא בחי' מקיף הכללי מהארת הגלגלתא עצמה שחופף על ג' החללי' דחב\"ד כאחד כו' כך בחי' מקיף דשמחת תורה הנק' כתר תורה כנ\"ל הוא בחי' מקיף הכללי מבחי' הארת הגלגלתא שנק' כתר כידוע שתחתיו מתאספים כל הראשים מג' חללי' דחב\"ד יחד והוא כל חדש תשרי שהוא כללו' כל המוחין כו' ונמצא אע\"פ שכל החדש הזה נק' ראש היינו רק בבחי' כללות המוחין דחב\"ד שבראש אבל בחי' גוף הראש עצמו שהוא בחי' כתר שבגלגלתא עצמה הנק' כתר תורה היינו דוקא בשמחת תורה ועליו אומר בהתאסף ראשי עם יחד ופי' שבטי ישראל כי י\"ב השבטי' הם י\"ב החדשי' ונכללי' ונאספים יחד בחדש תשרי שהוא כללו' המוחי' שבראש ועליהם חופף בחי' הארת הכתר כנ\"ל ומבואר למעלה שמבחי' כתר תורה נמשך כתר מלכו' לפי שנעוץ תחלתן בסופן לפי שכל<sup data-n=\"5528\">54</sup> ישראל בני מלכים הן כידוע וד\"ל.\n<b>והנה</b> לימות המשיח כתיב ולא<sup data-n=\"5529\">55</sup> ילמדו עוד איש את רעהו כו' כי כולם ידעו אותי מקטנם עד גדולם כו'. ויש להבין למה דוקא לימות המשיח לא ילמדו איש את רעהו כו' ולמה לא הי' דבר זה בזמן הקודם כמו בזמן שהיו ישראל במדבר וגם לא בזמן בנין בהמ\"ק ראשון ושני כו'.\n<b>אך</b> הנה הענין הוא לפי שזה הדבר שלא ילמדו איש את רעהו כו' שכולם יהיו בהשווא' א' מקטנם עד גדולם זה מורה על הגלות נגלות על כללו' נ\"י מבחי' מקיף הכללי הנ\"ל דהנה בשעת מ\"ת כתיב ויחן<sup data-n=\"5530\">56</sup> שם ישראל כו' מה שאמר לשון יחיד ויחן לפי שכולם היו כאיש<sup data-n=\"5531\">57</sup> אחד ממש וכן מ\"ש ברכנו<sup data-n=\"5532\">58</sup> אבינו כולנו כאחד כו' כולנו כאחד דוקא להיות כי כאשר אין בכנ\"י בחי' האחדות להתאחד ממש כולם כאיש אחד הרי יש כמה ראשים פרטיים מיוחדי' לכל שבט ומשפחה בפ\"ע וידוע שכנ\"י<sup data-n=\"5533\">59</sup> הן בציור קומה שלימה ויש הרבה נשמות שהן מבחי' מוח החכמה ויש מבחי' מוח הבינה כמו חכמים ונבונים כו' ויש מבחי' המדות כו' ובכאו\"א מהן יש בחי' פנימי' ומקיפי' ונמצא יש מקיפי' פרטיים ונקראו ראשים בפרט ודרך כלל נחלקו לג' מדרגו' חב\"ד ופרטיהם לי\"ב שבטי' שכאו\"א כולל ד' כו' אך בחי' המקיף כללי הנ\"ל היינו שחופף על המוחי' שבגלגלתא דרך כללות להקיף את כולם יחד עד מבלי שימצא בהם ראש וסוף לגבי מקיף הזה כי כולם מקבלי' מראש אחד והוא בחי'",[["5527","53","<b>בג' חללי' דגלגלתא</b>: ראה זהר (אדרא רבא) נשא קמ, א. ואתחנן רסב, א."],["5528","54","<b>שכל ישראל בני מלכים הן</b>: שבת סז, א. וש\"נ."],["5529","55","<b>ולא ילמדו עוד איש את רעהו</b>: ירמי' לא, לג."],["5530","56","<b>ויחן שם ישראל</b>: יתרו יט, ב."],["5531","57","<b>כאיש אחד</b>: פרש\"י שם."],["5532","58","<b>ברכנו אבינו כולנו כאחד</b>: בברכת ”שים שלום\" בתפלת העמידה."],["5533","59","<b>שכנ\"י הן בציור קומה שלימה</b>: ראה יבמות סא, א. לקו\"ת נצבים מד, א. סידור שער האלול רלא, ב. סה\"מ תקס\"ב ח\"ב ע' תקכה."]]],[2100990379,"מקיף הכללי הזה שבגלגלתא דמל' דאצי' הכוללם יחד כו' ואז נאמר ולא ילמדו &lt;שפא&gt;\nעוד איש את רעהו כו' כי הלימוד הזה בא מבחי' התחלקות המדרגו' בציור קומה כנ\"ל ונמצא בחי' המוחי' נק' ראש לגבי בחי' המדו' וכן בדרך פרט יש הרבה ראשים פרטיי' בכל מדרגה עד שימצא ראש בכל פרט והיינו מה שילמדו איש את רעהו כו' אבל כאשר כולם ידעו אותי מקטנם עד גדולם בהשווא' א' ממש זה הדבר מורה על היות שכל הראשים נכללו ונתאחדו כאחד ממש מבלי שימצא בהם כלל בחי' משפיע ומקבל כי כולם מקבלי' ממקור וראש אחד והוא הראש האמיתי בחי' גלגלתא שכוללם יחד בהשווא' א' ממש מכל צד מגדולם עד קטנם כו' וכמשל העיגול שמקיף מכל צד ואין בו מעלה ומטה כלל כו' וזה הדבר יהי' לימות המשיח דוקא שלא יהי' אז כמה ראשים אלא יהי' רק ראש אחד כללי וכמ\"ש ושמו<sup data-n=\"5534\">60</sup> להם ראש אחד כו' והוא בחי' מקיף הכללי הנ\"ל משום שיתגלה אז בחי' כתר הכללי הנ\"ל והוא בחי' כתר דא\"א כי נעוץ סופן בתחלתן וע\"י התכללו' נשמו' ישראל שהן בבחי' מל' דאצי' שעי\"ז נמשך בחי' כתר מלכו' נמשך גם בחי' כתר הכללי שהוא בחי' גלגלתא דא\"א הנק' כתר תורה כנ\"ל וד\"ל.\n<b>אמנם</b><sup data-n=\"5535\">61</sup> גם בשעת מ\"ת היה ג\"כ אפס קצה מאותה ההארה מבחי' מקיף דכתר הכללי הנ\"ל בשעה שעמדו בהר סיני בבחי' ההתכללו' והאחדות כאיש אחד וכמ\"ש ויחן לשון יחיד כנ\"ל שהאחדות הזאת גרמה שנכללו כל הראשים יחד ונעשו כולם בחי' מקבלי' מראש אחד והוא בחי' מקיף דכתר הכללי כנ\"ל לפי שבהתכללות והתאחדו' דכל הראשי' יחד אזי ממילא נמשך אור המקיף הכללי משא\"כ בהפרדם כו' ומה שלעתיד נתגלה המקיף הכללי הזה מצד עצמו בשעת מ\"ת נתגלה מצד התכללו' ואחדו' דכנ\"י ובפרט כשאמרו נעשה<sup data-n=\"5536\">62</sup> ונשמע ברעותא דלבא וכולם כאיש אחד כו' ולכך זכו גם כאו\"א בפרט לב'<sup data-n=\"5537\">63</sup> כתרים וכללות הכתרים האלה האיר בהם מבחי' כתר הכללי הנ\"ל וד\"ל.\n<b>והנה</b> מאז והלאה לא נמצא בחי' התכללו' בכנ\"י כ\"כ ולא נמשך עליהם בחי' מקיף הכללי כי בחטא<sup data-n=\"5538\">64</sup> העגל נסתלק מהם הארת הכתר הכללי הזה כמ\"ש ויתנצלו<sup data-n=\"5539\">65</sup> בנ\"י את עדיים כו' ולא זכו להארתו בכל משך זמן השנים שהלכו במדבר עד לפני הסתלקו' משה כשבירכם ואמר תורה ציוה לנו משה כו' אמר בהתאסף ראשי עם יחד שבטי ישראל כו' ואזי החזיר קצת עטרת הכתר כללי הנ\"ל להאיר בכנ\"י אבל היא הארה מועטת מאד ואפס קצה מן אותה ההארה נמשך בג' רגלים בעולי רגל כשעומדי' כולם בעזרה וכמ\"ש יראה<sup data-n=\"5540\">66</sup> כל זכורך את פני ה' כו' אבל זהו בחי' הארת הכתר בפרט דהיינו השייך לג' מדות חג\"ת חסד בפסח כו' אך בשבועות",[["5534","60","<b>ושמו להם ראש אחד</b>: הושע ב, ב."],["5535","61","<b>אמנם גם בשעת מ\"ת</b>: ראה ג\"כ לעיל ח\"א ע' שצד."],["5536","62","<b>נעשה ונשמע</b>: משפטים כד, ז."],["5537","63","<b>לב' כתרים</b>: שבת פח, א."],["5538","64","<b>בחטא העגל נסתלק מהם הארת הכתר</b>: נסמן לעיל ע' תשלח."],["5539","65","<b>ויתנצלו בנ\"י את עדיים</b>: תשא לג, ו."],["5540","66","<b>יראה כל זכורך את פני ה'</b>: משפטים כג, יח. תשא לד, כג. ראה טז, טז."]]],[2100990380,"יש קצת מעין הארת הכתר הכללי והיינו בבחי' ת\"ת<sup data-n=\"5541\">67</sup> דאימא שנעשה כתר לזו\"נ בכלל כו' וזה נעשה ע\"י שניעורים<sup data-n=\"5542\">68</sup> כל הלילה בליל שבועות כידוע וד\"ל אבל בבחי' הכתר הכללי ממש אין בנו כח להמשיך עד ימות המשיח כנ\"ל אבל מ\"מ אפס קצהו אנו ממשיכי' בתפלה ע\"י המלאך סנד\"ל<sup data-n=\"5543\">69</sup> שקושר הכתרים מן התפלות כי הוא מעלה את התפלה כו' וכידוע וכתר זה שנעשה מן התפלות עכשיו הוא אשר יהי' בחי' כלי לשכון בו אור כתר הכללי לעתיד בימות המשיח דכתיב ולא ילמדו עוד כו' כנ\"ל וז\"ש הנה<sup data-n=\"5544\">70</sup> ישכיל עבדי כו' וגבה מאד כו' וד\"ל (והיינו ברכינו אבינו &lt;שפב&gt;\nכולנו כאחד באור פניך כו' כולנו כאחד דוקא כי אין אור הכתר שנק' אור פניך שורה על כנ\"י כ\"א דוקא כשהם כולם כאיש מטעם הנ\"ל וד\"ל).\n<b>וזהו</b> בהתאסף ראשי עם יחד שבטי ישראל אז דוקא ויהי בישורון מלך כו'. וסדר הפסוקים כך הם, תורה ציוה לנו משה כו' להיו' נק' קהלת יעקב ע\"י הברורי' דרפ\"ח כו' דבחכמה אתברירו כנ\"ל ואח\"כ ויהי בישורון מלך בהתאסף ראשי עם כו' שנמשך עליהם בחי' כתר הכללי הנ\"ל הנק' כתר תורה כנ\"ל והוא הנק' ישורון<sup data-n=\"5545\">71</sup> ויש בו ב' פרושי' א' מלשון שיר כנ\"ל וגם מלשון ישר כי בחי' הכתר הכללי הנ\"ל בוקע אורו דרך קו האמצעי הנק' ישורון אך אינו מאיר רק בהתאסף ראשי עם יחד שבטי ישראל דהיינו כשמתקבצים כל הראשים ועולין ונכללי' בבחי' קו האמצעי הנק' ישראל שאז ע\"י ההתכללו' הזאת מאיר עליהם מאור הכתר הכללי כנ\"ל והארה זו מאירה מלמעלה למטה בקו<sup data-n=\"5546\">72</sup> האמצעי שנק' ישראל הנקרא עמודא דאמציעותא אך בתנאי בהתאסף כל ראשי עם יחד כנ\"ל הטעם וד\"ל.\n<b>ושרש</b> ענין השיר הנ\"ל הנה אמרו במשנה כל<sup data-n=\"5547\">73</sup> בעלי השיר יוצאין בשיר וכו' וקאי על המלאכי' שנקראו בעלי השיר וכידוע לפי שעלייתם למעלה הוא ע\"י השיר אך הנה השיר הגשמי הוא כמו רצועה של ברזל סביב הצואר והוא משל להבין שיר של המלאכי' כי הן נמשלי' לבהמות וחיות כידוע אמנם השיר של הנשמות הן מזהב וכסף והוא נעשה כמו הטבעת מכסף או מזהב כו' דהנה בז' מיני מתכות הברזל הוא מדרגה היותר אחרונה מכולם כידוע בפי' אך<sup data-n=\"5548\">74</sup> את הזהב ואת הכסף כו' והענין הוא למעלה היינו בחי' מל' דאצי' שנק' ברזל לגבי אורו' העליונים חג\"ת דז\"א שהן נק' זהב וכסף כו' וכמו שידוע שיש במל' בחי' גבורות",[["5541","67","<b>ת\"ת דאימא שנעשה כתר לזו\"נ</b>: ראה ע\"ח שער מוחין דצלם רפ\"ה ורפ\"ז. שער דרושי הצלם דרוש ד' וה'."],["5542","68","<b>שניעורים כל הלילה בליל שבועות</b>: ראה זהר אמור צח, א. פע\"ח שער חה\"ש שכ\"ג, פ\"א. ושעה\"כ שם. שו\"ע אדה\"ז חאו\"ח סתצ\"ד, ס\"ג. לקו\"ת במדבר ח, א."],["5543","69","<b>המלאך סנד\"ל שקושר הכתרים</b>: נסמן לעיל ע' תשלח."],["5544","70","<b>הנה ישכיל עבדי</b>: ישעי' נב, יג."],["5545","71","<b>ישורון. . שיר. . ישר</b>: ראה ג\"כ לקו\"ת נצבים מה, א. שה\"ש א, ג."],["5546","72","<b>בקו האמצעי. . עמודא דאמציעותא</b>: ראה זהר (רע\"מ) תשא קפז, ב. ביאוה\"ז שם נד, ב."],["5547","73","<b>כל בעלי השיר יוצאין בשיר</b>: שבת נא, ב."],["5548","74","<b>אך את הזהב ואת הכסף</b>: מטות לא, כב."]]],[2100990381,"חזקו' וקשות כברזל וכענין המאמר בגמ' הקשה<sup data-n=\"5549\">75</sup> אדם קשה כברזל כו' וידוע דשרש חיו' המלאכי' נמשך רק מבחי' הדיבור בלבד והיינו בחי' חיצוניו' המל' שנק' ברזל וע\"כ בעלייה שלהם כשהן עולין ונכללי' בשיר במקור חוצבם הוא בשיר של ברזל כי שירת המלאכי' מחיצוניו' העולמות הוא אבל הנשמות שרשם מיחוד דזו\"נ שהוא בחי' זהב וכסף כו' בחי' פנימיו' דזו\"נ ע\"כ גם השיר שלהם כשעולין הוא בבחי' זהב וכסף כטבעת עגול מכסף וזהב כו' ונק' שיר שלהם שירו של הקדב\"ה בעצמו כנ\"ל וכמ\"ש ובלילה שירו עמי כו' שירו קרי משא\"כ שירת המלאכי' נק' שירה שיר ה\"א דמלכו' כו' וד\"ל.\n<b>וזהו</b> שיר<sup data-n=\"5550\">76</sup> השירים אשר לשלמה שיר על כל השירים לפי שנקרא שירו והוא שיר של שלמה מלכא<sup data-n=\"5551\">77</sup> דשלמא דילי' כי שירו של הקדב\"ה נק' שעשועי המלך בעצמותו כנ\"ל וכמ\"ש ואהי'<sup data-n=\"5552\">78</sup> אצלו שעשועי' כו' ואין אור מקיף זה מאיר רק בנשמות מצד ששרשם נמשך מעצמות המאציל כמ\"ש כי<sup data-n=\"5553\">79</sup> תהיו אתם ארץ חפץ וכן תקרא<sup data-n=\"5554\">80</sup> חפצי בה כו' וכידוע והיינו ג\"כ פי' וישורון מלשון שיר וזהו ויהי בישורון מלך כי כל ישראל בני מלכים הן ונעוץ סופן בתחלתן כנ\"ל באריכו' וד\"ל.\n<b>ובזה</b> יובן מה שמנה כאן ג' מדרגות זו אחר זו בתחלה קראם לכנ\"י בשם יעקב קהלת יעקב ואח\"כ ישורון ואח\"כ אמר שבטי ישראל כי ישורון כולל יעקב וישראל יחד &lt;שפג&gt;\nמטעם שבחי' שעשועי המלך בעצמותו הוא שמשתעשע בכנ\"י ומשירה נעשה שירו שאז נקרא ישורון בנו\"ן פשוטה כו' לפי שבריח התיכון מבריח מן הקצה לקצה דהיינו מכתר הכללי עד בחי' מל' כידוע וד\"ל.\n<b>(לכאורה</b><sup data-n=\"5555\">81</sup> בע\"ח משמע דישראל גבוה מישורון אך ע' בזהר הרקיע ד\"ב בענין וישורון ונטיל תרין שורין וצ\"ת).",[["5549","75","<b>הקשה אדם קשה כברזל</b>: מנחות צה, ב."],["5550","76","<b>שיר השירים אשר לשלמה</b>: שה\"ש א, א."],["5551","77","<b>מלכא דשלמא דילי'</b>: ראה זהר בראשית כט, א."],["5552","78","<b>ואהי' אצלו שעשועי'</b>: משלי ח, ל."],["5553","79","<b>כי תהיו אתם ארץ חפץ</b>: מלאכי ג, יב."],["5554","80","<b>תקרא חפצי בה</b>: ישעי' סב, ד."],["5555","81","<b>(לכאורה בע\"ח. . וצ\"ת)</b>: הג\"ה זו ליתא באוה\"ת שם."]]],[2100990382,"<h3>נוסח שני: תורה צוה</h3>\n<b></b><b>בעזר\"ה שמחת תורה ברבים בסעודה</b>\nשמחת תורה\n<b>תורה</b><sup data-n=\"5556\">1</sup> צוה<sup data-n=\"5557\">2</sup> לנו משה מורשה קהלת יעקב ויהי בישורון מלך וגו'. להבין זה מהו לשון ירושה. . הלא כתיב את<sup data-n=\"5558\">3</sup> אשר ישנו פה עמנו ואשר [איננו] פה כו', א\"כ איך יתכן לומר על התורה שהיא בחי' ירושה לנו מאבותינו כמ\"ש מורשה קהלת יעקב כו'. ועוד מהו ויהי [בישורון] כו'. אך הנה כתיב אלה<sup data-n=\"5559\">4</sup> המלכים אשר מלכו בארץ אדום לפני מלך מלך בישראל וימלוך בלע כו'. . שזהו בחי' ז'<sup data-n=\"5560\">5</sup> מלכין קדמאין דתהו שמתו ונשברו הכלים דתהו ונפלו דרך שבירה למטה לנוגה דבי\"ע. . להתלבש בע' שרים דעשי' והמה המזלות המשפיעים כל טוב הארץ ממגד<sup data-n=\"5561\">6</sup> תבואות שמש. . [אין<sup data-n=\"5562\">7</sup> לך] כל עשב למטה שאין לו מזלו מלמעלה שמכה ואומר לו גדל כו', וגבוה<sup data-n=\"5563\">8</sup> מעל גבוה שומר. . ומקבלים דין מן דין עד שמקור ושרש החיות גשמיות של כל הנפעלים דעשי'. . האילן וכל הבהמות וחיות הוא בחי' ז' מלכין קדמאין דתהו שנפלו בשבירה. . בעניינים תחתונים גשמי' דעשי' כמו צמר הציצית, קלף התפילין סכך הסוכה. . שנפלו למטה ולהחזירן לקדושה כנודע, והיינו כי שורשו. . וכבוד<sup data-n=\"5564\">9</sup> הדר מלכותו הדר הוא לכל. . לכך המה המבררים. .\n<b>וביאור</b> הענין כתי' מלכותך<sup data-n=\"5565\">10</sup> מל' כל עולמים וגו' כבוד<sup data-n=\"5566\">11</sup> מלכותך יאמרו וגו', שהתפשטות מדת המלוכה הוא על המלאכים עליונים וחיות הקודש הנושאות<sup data-n=\"5567\">12</sup> הכסא ונשואות עם כסא וזעות מחיל כסא כו', ואשר<sup data-n=\"5568\">13</sup> אימתך ומוראך עליהם כו' (כמ\"ש בפיוט), וכן בתפלת יוצר כולם מקבלים עליהם עול מלכות שמים זה מזה כו', וכולם עונים באימה ואומרים ביראה כו', דהיינו שעיקר התפשטות מדת מלכותו ית' עליהם דייקא להיות אימתו ופחדו תפול עליהם והם מקבלים עליהם העול זה של הפחד והאימה עד שזעות מחיל כסא וכמארז\"ל מזיעתן<sup data-n=\"5569\">14</sup> של חיות נהר דינור נגיד ונפיק על ראש רשעים יחול בגיהנם כו', ופי' שדברה<sup data-n=\"5570\">15</sup> תורה כלשון בני",[["5556","1","<b>תורה צוה</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1066 (ב, א). בכמה מקומות בהכת\"י קרוע.\nהנחת כ\"ק אדה\"א נדפס לעיל ע' תשלא."],["5557","2","<b>תורה צוה משה. . ויהי בישורון מלך</b>: ברכה לג, ד. ה."],["5558","3","<b>את אשר ישנו פה</b>: ראה נצבים כט, יד."],["5559","4","<b>אלה המלכים אשר מלכו בארץ אדום. . בלע</b>: וישלח לו, לא ואילך."],["5560","5","<b>ז' מלכין קדמאין דתהו</b>: ראה זהר (אדרא רבא) נשא קכח, א. ע\"ח שער הכללים פ\"א. שם (שער דרושי הנקודות) ש\"ח פ\"ד."],["5561","6","<b>ממגד תבואות שמש</b>: ברכה לג, יד."],["5562","7","[אין לך]<b> כל עשב למטה שאין לו מזלו מלמעלה</b>: ראה ב\"ר פ\"י, ו. השמטות לזח\"א רנא, א. זהר תרומה קכא, ב. מו\"נ ח\"ב פ\"י."],["5563","8","<b>וגבוה מעל גבוה שומר</b>: קהלת ה, ז."],["5564","9","<b>וכבוד הדר מלכותו</b>: תהלים קמה, יב."],["5565","10","<b>מלכותך מל' כל עולמים</b>: תהלים קמח, יג."],["5566","11","<b>כבוד מלכותך יאמרו</b>: תהלים קמה, יא."],["5567","12","<b>הנושאות הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד."],["5568","13","<b>ואשר אימתך ומוראך עליהם (כמ\"ש בפיוט)</b>: מוסף ליו\"כ."],["5569","14","<b>מזיעתן של חיות</b>: ראה חגיגה יג, סע\"ב. ס' הליקוטים [דא\"ח להצ\"צ] ערך זיעה."],["5570","15","<b>שדברה תורה כלשון בני אדם</b>: ברכות לא, ב."]]],[2100990383,"אדם, דכמו בהאדם שלמטה הזיעה היוצא מהגוף הוא הפסולת שנדחה לחוץ, וכאשר יתבהל האדם פתאום מאיזה מורא ופחד עד שיזדעזעו איבריו אז יצא הזיעה מגופו מצד שאין הכלי תכיל גודל עוצם הפחד עד שנדחה לחוץ הזיעה פסולת שבו כו', ככה ממש עד\"מ למעלה אשר מגודל עוצם הפחד והאימה של כבוד מלכותו ית' שתפול עליהם המה זעות מחיל כסא ויוצא מהן בחי' זיעה הפסולת שלהן לחוץ למטה ונתהוה מזעיתן הגיהנם למטה, והוא מצד שא\"א להם לקבל לתוכן כל המורא ופחד לכך המה זעות כו' כנ\"ל וד\"ל.\n<b>והנה</b> הגם שהתפשטות מדת המלוכה הוא על העליונים יותר מבתחתונים, כי מוראך עליהם דייקא וזעות מחיל כסא כו' כנ\"ל, אשר בלתי אפשר הי' להתחתונים לסבול המורא הגדול הזה מצד היותם מלובשים בגופים גשמים חומרים דעוה\"ז לכך מתגלה המורא הגדול והפחד על המלאכים עליונים יותר אין קץ מבתחתונים, אעפ\"כ מעלה יתירה נודעת לנו בישראל שלמטה מבמלאכים עליונים, והיינו כי עיקר התהוות המלאכים הוא משם כבוד מל' ית' ממש כי בדבר<sup data-n=\"5571\">16</sup> ה' שמים נעשו וברוח פיו כל צבאם וגו', וכן בתפלה נאמר ישתבח שמך לעד מלכנו יוצר משרתים כו', ולכן תפול עליהם האימה ופחד ממקורם ושרשם ממש להיותם זעות מחיל כסא כו', אבל נשמות<sup data-n=\"5572\">17</sup> ישראל עלו במחשבה קדומה כו', ולזאת המה ממשיכים בחי' כבוד הדר מלכותו כר'<sup data-n=\"5573\">18</sup> יוחנן דקארי למאני מכבדותי', להמשיך בחי' לבוש מלכות כדכתיב יביאו<sup data-n=\"5574\">19</sup> לבוש מלכות וגו' למדת מל' ית' להתפאר בלבושים העליונים שנמשכים למדת מל' ית' ע\"י מעשה התחתונים של ישראל שנמשכים מהדר<sup data-n=\"5575\">20</sup> מלך השמיני וזהו וכבוד הדר מלכותו כמ\"ש הוד<sup data-n=\"5576\">21</sup> והדר לבשת שכמו עד\"מ המלך ב\"ו מצטרך להתלבש בלבושים נאים ההגונים למלכות בכדי שיתפאר על העם בלבושיו הנאים כו'.\n<b>ככה</b> ממש עד\"מ למעלה כתי' וכבוד הדר מלכותו, הוא המשכת הלבושים עליונים למדת מל' ע\"י מעשה התחתונים בקיום המצות, והיינו כנודע שממעשה המצות שלמטה נעשה לבושים להנשמות בג\"ע להנות מזיו השכינה ב\"ה וכל ההשגו' שמשיגים מנועם ה' ית' הכל דרך אותו הלבוש של המצות וז\"ש שכר<sup data-n=\"5577\">22</sup> מצוה מצוה כו', [כי] כל הנשמות הנבראים ומחודשים מאין ליש בלתי אפשר להם להשיג רק מזיו השכינה שבג\"ע אשר הוא הארה בעלמא ממנו ית' [אבל שרש] המצות מגיעים למעלה מעלה להמשיך בחי' לבושי' למדת מל' ית' עצמה, וכמארז\"ל יפה<sup data-n=\"5578\">23</sup> שעה א'",[["5571","16","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["5572","17","<b>נשמות ישראל עלו במחשבה קדומה</b>: ראה ב\"ר פ\"א, ד."],["5573","18","<b>כר' יוחנן דקאי למאני מכבדותי'</b>: שבת קיג, ב."],["5574","19","<b>יביאו לבוש מלכות</b>: אסתר ו, ח."],["5575","20","<b>מהדר מלך השמיני</b>: וישלח לו, לט. וראה ג\"כ תו\"ח בראשית ח, א."],["5576","21","<b>הוד והדר לבשת</b>: תהלים קד, א. משלי לא, כה."],["5577","22","<b>שכר מצוה מצוה</b>: אבות פ\"ד מ\"ב. תניא פל\"ט."],["5578","23","<b>יפה שעה א' בתשובה ומע\"ט</b>: אבות פ\"ד, מי\"ז."]]],[2100990384,"בתשובה ומע\"ט מכל. . מצד שהמצות ממשיכים לבוש מלכות למדת מל' ממש וזהו הגבה למעלה מאד נעלה מהלבושים דהנשמות בג\"ע כו' וזהו ענין שמחה של מצוה. . [תחת<sup data-n=\"5579\">24</sup> אשר] לא עבדת וגו' בשמחה ובטוב לבב מרוב כל, פי' רו\"ב כ\"ל הוא כל<sup data-n=\"5580\">25</sup> חיי עוה\"ב דג\"ע העליון ותחתון והשמחה. . מצד שהיא מקור ג\"ע העליון שנהנין מזיו השכינה והיא לבוש מלכות ממש כנ\"ל, והיינו כי. . ב\"ה אשר קדשנו במצותיו וצונו להניח תפילין ולהתעטף בציצית ולישב בסוכה ודומיהן ומוכרחים. . בלי ידיעת טעם הדבר כלל כי אין טעם לרצון ואלו<sup data-n=\"5581\">26</sup> צונו לחטוב עצים היינו מקיימין,. . מצוה הוא אינו מצד ידיעת טעם הדבר שיאות כן לעשות דא\"כ לא תתקיים. . בלי ידיעת טעם כלל, אלא שקיום המצות הוא מצד גזירת<sup data-n=\"5582\">27</sup> המלך בלא טעם כלל. . דעת בצווי המצות האלה אשר<sup data-n=\"5583\">28</sup> יעשה האדם וחי בהם שלא צונו. . בכדי להמשיך מקיפים דאימא. . התענוג והמתיקות. .\n<b>אשר</b><sup data-n=\"5584\">29</sup> אנכי מצוך היום וארז\"ל היום<sup data-n=\"5585\">30</sup> לעשותם ולא למחר לעשותם, היום לעשותם ולמחר לקבל שכרן כו', והיינו כי לע\"ל ובעוה\"ב א\"א להיות התשובה לאתהפכא מרע לטוב הרחוקים שם בתכלית הריחוק ובאשר הוא שם שם הוא כו', כמארז\"ל באחר מוטב<sup data-n=\"5586\">31</sup> דלידייני' כו', אכן בעוה\"ז. . הדבר מאד לאתהפכא<sup data-n=\"5587\">32</sup> מחשוכא לנהורא ע\"י התשובה ברגע א' כו', מצד שאנכ\"י<sup data-n=\"5588\">33</sup> מי שאנכי המקיף דכ\"ע הוא מתגלה למטה עתה דוקא כי קמיה<sup data-n=\"5589\">34</sup> כחשיכה כאורה השוה ומשוה כו' המשפילי<sup data-n=\"5590\">35</sup> לראות בשמים ובארץ בשוה כו' וכמ\"ש במ\"א ע\"ש.\n<b>וזהו</b> תורה צוה לנו משה מורשה קהלת יעקב, פי' שכל התורה אשר צוה לנו משה, היא בחי' מורש\"ה, בכדי לירש את ארץ הכנעני והיינו כמ\"ש לאדום כה<sup data-n=\"5591\">36</sup> אמר אחיך ישראל כו' וכתיב<sup data-n=\"5592\">*36</sup> כה אמר אחיך אדום, כי הלא<sup data-n=\"5593\">37</sup> אח עשו ליעקב, עשו<sup data-n=\"5594\">38</sup> אבי אדום שרש הז' מלכין קדמאין דתהו שמתו שהם לפני מלך מלך בישראל, כי עשו<sup data-n=\"5595\">39</sup>",[["5579","24","[תחת אשר]<b> לא עבדת וגו'</b>: תבוא כח, מז."],["5580","25","<b>כל חיי עוה\"ב דג\"ע</b>: ראה ג\"כ תו\"א הוספות מג\"א קכב, ב."],["5581","26","<b>ואלו צונו לחטוב עצים</b>: ראה לקו\"ת שלח מ, א. המשך תרס\"ו ע' נד. לקו\"ש חי\"א ע' 230 ואילך. חכ\"א ע' 17."],["5582","27","<b>גזירת המלך בלא טעם</b>: ראה ג\"כ לעיל בביאור ד\"ה ועתה יגדל."],["5583","28","<b>אשר יעשה האדם וחי בהם</b>: נסמן לעיל ע' תנח."],["5584","29","<b>אשר אנכי מצוך היום</b>: דברים ו, ו."],["5585","30","<b>היום לעשותם. . ולמחר לקבל שכרן</b>: ואתחנן ז, יא. וראה עירובין כב, א."],["5586","31","<b>מוטב דלידייני'</b>: חגיגה טו, ב."],["5587","32","<b>לאתהפכא מחשוכא לנהורא</b>: ראה זהר בהקדמה ד, א."],["5588","33","<b>שאנכי מי שאנכי</b>: ראה זח\"א קסז, ב. זח\"ג יא, א. לקו\"ת להאריז\"ל תולדות כז, טו. אבן עזרא שם. תניא מהדורא קמא ספמ\"ט. לקו\"ת פינחס פ, ב. ראה לא, ד."],["5589","34","<b>קמיה כחשיכה כאורה</b>: נסמן לעיל ע' תשכח."],["5590","35","<b>המשפילי לראות בשמים ובארץ</b>: תהלים קיג, ו."],["5591","36","<b>כה אמר אחיך ישראל</b>: חקת כ, יד."],["5592","*36","<b>וכתיב כה אמר אחיך אדום</b>: כ\"ה בהכת\"י."],["5593","37","<b>הלא אח עשו ליעקב</b>: מלאכי א, ב."],["5594","38","<b>עשו אבי אדום</b>: וישלח לו, ט."],["5595","39","<b>עשו יצא ראשון אדמוני כולו כאדרת שער</b>: תולדות כה, כה."]]],[2100990385,"יצא ראשון אדמוני כולו כאדרת שער. . הוא שרש התיקון המברר כל הברורים דמלכין ונשמות בכל המצות שבתורה שמלובשים בעניינים גשמיי' צמר הציצית קלף. . כו' שנפלו בהן הניצוצין דמלכים שמתו וע\"י קיום המצות חוזרים לקדושה, וזהו מורשה שהוא בחי' ירושה לאדום וארץ הכנעני כו', קהלת יעקב קהלת ואסיפת כל הניצוצין שנתפזרו למטה בנוג\"ה דבי\"ע בקבוץ ואסיפה בבחי' יעקב<sup data-n=\"5596\">40</sup> י' עקב, המברר כו' ואח\"כ קרא ה' שמו ישראל כי<sup data-n=\"5597\">41</sup> שרית עם אלקים וגו' עם אלקים דייקא ולא על אלקים כו', והיינו כמ\"ש בזוהר<sup data-n=\"5598\">42</sup> ע\"פ ואהבת בכל לבבך, בשני יצריך, דא רזא כו' ע\"ש, שגם היצה\"ר מסייעו ועוזרו בחזרתו לקדושה בבחי' אתהפכא מחשוכא לנהורא, וזהו כי שרית עם אלקים דייקא כי אלקים<sup data-n=\"5599\">43</sup> גי' הטב\"ע שהוא בחי' המדות טבעיי' שבאדם כי עיר פרא<sup data-n=\"5600\">44</sup> אדם יולד במדות מגונות דלא סגי בלא\"ה כו', לכן בבא<sup data-n=\"5601\">45</sup> לטהר מסייעין אותו אף בחי' האלקים גי' הטב\"ע כי דא רזא שנז' בזוהר וזהו עם אלקים דייקא ולא על אלקים וכנ\"ל וד\"ל.\n<b>ויהי</b> בישורון מלך, פי' כי יש ג'<sup data-n=\"5602\">46</sup> בחי' יעקב ישראל ישורון, והעולה על כולנה הוא ישורו\"ן<sup data-n=\"5603\">47</sup> כי הוא ל' שיר ויש\"ר ועגול והכל. . והיינו בחי' המשכת המקיף העליון הסכ\"ע בשוה המשפילי לראות כו' השוה<sup data-n=\"5604\">48</sup> ומשוה קטן וגדול ע\"י אתעדל\"ת בשיר בפסד\"ז דתפלה אשר אליו הוא נושא את נפשו ורצונו להתכלל בו ית', ועי\"ז נמשך דוגמתו אתעדל\"ע בחי' ישורו\"ן. . קמיה כחשיכה כאורה וגם הוא ל' שיר רננה דאוריי' חדוה דאוריי' הקול פשוט ומורכב מתנועת הניגון הנמשך מהרצון [שא\"א] להתלבש בהדבור כו' והוא העיגול מבלי שימצא בו ראש וסוף דאין יתרון להעליון לגבי התחתון כי הוא שוה ומשוה כו'.\n<b>וזהו</b> ענין שמחת תורה, השמחה של התורה עצמה הוא רננה דאוריי' בחי' ישורון השיר היוצא מפנימיות הלב שלמעלה מהדבור שיוצאין<sup data-n=\"5605\">49</sup> בשי\"ר ונמשכין בשיר כו' וזה<sup data-n=\"5606\">50</sup> היום עשה ה' נגילה ונשמחה בו ממש [ומיום] הזה ממשיכים שמחה על כל השנה בחדות ה' מעוזינו שמחת התורה שהיא שעשועי<sup data-n=\"5607\">51</sup> המלך ב\"ה כו' כנ\"ל וד\"ל.",[["5596","40","<b>יעקב י' עקב</b>: ע\"ח שער ג (שער סדר האצילות) פ\"ב. תו\"א ויצא כא, ב."],["5597","41","<b>כי שרית עם אלקים</b>: וישלח לב, כט."],["5598","42","<b>בזוהר ע\"פ ואהבת בכל לבבך בשני יצריך דא רזא</b>: ואתחנן ד, ה. ספרי שם. זוהר וירא קו, א."],["5599","43","<b>אלקים ג' הטבע</b>: פרדס שער יב (שער הנתיבות) פ\"ב. ראשית חכמה שער התשובה פ\"ו ד\"ה והמרגיל (קנא, ב). של\"ה פט, א. (דאיתא בזהר) קפט, א. ועוד."],["5600","44","<b>פרא אדם יולד</b>: איוב יא, יב."],["5601","45","<b>בבא לטהר מסייעין אותו</b>: ראה שבת קד, א. יומא לח, סע\"ב."],["5602","46","<b>ג' בחי' יעקב ישראל ישורון</b>: ראה זהר בראשית קעז, ב."],["5603","47","<b>ישורון. . ל' שיר</b>: ראה לקו\"ת נצבים מה, א. אוה\"ת ברכה ע' א'תתנג. א' תתסט."],["5604","48","<b>השוה ומשוה קטן וגדול</b>: לשון פיוט האוחז ביד משפט."],["5605","49","<b>שיוצאין בשיר ונמשכין בשיר</b>: שבת נא, ב."],["5606","50","<b>וזה היום עשה ה' נגילה ונשמחה בו</b>: תהלים קיח, כד."],["5607","51","<b>שעשועי המלך</b>: נת' בעמק המלך שער א. וראה לקו\"ת שה\"ש כז, סע\"א."]]],[2100990386,"<b>ולתוס'</b> ביאור מעט מזעיר, יובן מדרז\"ל<sup data-n=\"5608\">52</sup> ע\"פ מה אנוש כי תזכרנו כו' אשר תנה הודך על השמים, בשעה שעלה משה למרום לקבל התורה אמרו מה\"ש לפני הקב\"ה מה אנוש כי תזכרנו כו' א\"ל הקב\"ה החזר להם תשובה, א\"ל משה כלום יצה\"ר יש בכם כו' ע\"ש. ולכאורה יפלא כי מפני שאין להם יצה\"ר. . אדרבה ה\"ז משובח יותר. אך הענין כנ\"ל דכתי' בכל לבבך בשני יצריך. . ודא רזא שנז' בזוהר, וכד אתכפיא ואתהפכא סט\"א. . שיר ורננה שנ\"ל שיש בה מעלה. . אשר קדשנו במצותיו וצונו, ואלו צונו לחטוב עצים שאין בהם טעם כלל היינו מקיימין בשוה כנ\"ל, ואח\"כ הוא השמחה של מצוה מצד. . מתיקות התענוג שבקיום המצות האלה אשר יעשה האדם וחי בהם כו', כי יפה שעה א' בתשובה ומע\"ט מכל חיי עוה\"ב מצד היותם כבוד הדר מלכותו לבוש מלכות מקור הג\"ע כו' כנ\"ל.\n<b>וזהו</b> בחי' התפארת של המלך מה\"מ הקב\"ה בגדי כבוד לבושים הנאים המה המצות שצונו, שבכל מצוה יש סודות ורזין עלאין מחכמה נפלאה העליונה כי אורייתא<sup data-n=\"5609\">53</sup> מחכמה נפקא, וכמו עד\"מ במלך ב\"ו כשמצוה לעבדיו איזה צווי שמוכרחים לקיים הצווי יהי' מה שיהי', אך כשנגלה הטעם של המצוה ההיא שמלבד הצווי יש בה טוב טעם ותענוג גדול וחכמה נפלאה הרי בזה יתגדל כבודו של המלך ביותר ויתרומם מאד כו', ככה עד\"מ למעלה, שהמצות המה לבושי מלכות והמה המפארים לכבוד מלכותו ית' מצד שהמה. . מחכמה העליונה כי אורייתא מחכמה נפקא וכתי' בה ואהי'<sup data-n=\"5610\">54</sup> אצלו אמון ואהי' שעשועים יום יום משחקת לפניו כו', שהתורה [היא] שעשוע המלך ב\"ה, כמו עד\"מ למטה בנפש המשכלת כשמשכיל על כל דבר טוב באיזה חכמה נפלאה משתעשע בה מאד ומתענג בה מאד, שהארת העונג מלובש בחכמה, ככה ממש למעלה בהחכמה שבתורה מלובש הארת העונג עליון.\n<b>וזהו</b> ואהי' אצלו שעשועים כו' שעשועי המלך ב\"ה וכמ\"ש בת\"ז רננה<sup data-n=\"5611\">55</sup> דאורייתא חדוה דאורייתא טעמי תורה פי' שכל התנ\"ך הוא בנגינת הטעמים ובהטעמים מלובש הארת העונג עליון שהוא בחי' שיר\"ה דכתיב יומם<sup data-n=\"5612\">56</sup> יצוה ה' חסדו ובלילה שיר\"ה עמי, שיר\"ה הוא בחי' הנגינה והטעמים שבתנ\"ך שהוא רננ\"ה דאורייתא,. . בלילה בבחי' חשך והעלם למטה, והיינו כמו השיר והנגון הגשמי הוא קול בלא דבור היוצא מהבל הלב, והוא פנימי' יותר מהדבור אף שמלובש בו השכל מצד שהקול בלא דבור היוצא מהבל הלב בנגון ושיר הוא הנמשך מלמעלה מהשכל מבחי' הרצון פשוט שבפנימי' הלב, אשר א\"א לו להתלבש בצרופי אותיות הדבור (משא\"כ השכל שלמטה מהרצון, שיוכל להתלבש בצרופי אותיות הדבור כו'), זולתי קול פשוט",[["5608","52","<b>מדרז\"ל ע\"פ מה אנוש כי תזכרנו כו' אשר תנה הודך על השמים</b>: תהלים ח, ב. שבת פח, סע\"ב ואילך."],["5609","53","<b>אורייתא מחכמה נפקא</b>: זח\"ב פה, א. ועוד."],["5610","54","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["5611","55","<b>רננה דאורייתא</b>: ראה זהר בהקדמה ח, א. תו\"ח בראשית ד, א. לו, ב. לז, ג. מאמרי אדה\"א דברים ח\"ג ע' תשפא."],["5612","56","<b>יומם יצוה ה' חסדו</b>: תהלים מב, ט."]]],[2100990387,"ומורכב מתנועת הניגון שבו נרמז תנועת הרצון שבלב, וגם השיר והנגון הוא עגול אשר נעוץ תחלה בסוף וסוף בתחלה שסופו של הזמר והנגון יש לו שייכות והתחברות אל התחלה שכאשר מסיים הנגון מתחיל מהתחלה, ויש להסוף שייכות להתחלה ממש בלי היכר פירוד ביניהם (שאם הי' היכר פרוד ביניהם ה\"ז כב' נגונים ולא הי' מתחברים כו'. . לחכמי המוזיקא שעד\"ז נעשים כל השירים ונגונים להתערב הסוף בתחלה כעגול זה מבלי שימצא ראש וסוף כו').\n<b>ולכן</b> ארז\"ל (פ' במה בהמה מס' שבת ע\"ש) כל בעלי השיר יוצאין בשי\"ר ונמשכין בשי\"ר, שהטבעת של ברזל עגול הקשור בסוס ובהמה לנוי ותכשיט נק' בל' רז\"ל שי\"ר, וכן הנגון נק' בל' שיר שהכל א' כי גם הנגון עגול כנ\"ל, וזהו רננה דאורייתא דכתיב שיר\"ה עמי, שז\"ס הטעמים של הנגינה שבתנ\"ך שהוא למעלה מהאותיות. . מבחי' רצון העליון הפשוט הסובב כ\"ע בשוה המשפילי לראות בשמים ובארץ בשוה שכחשיכה כאורה כו', שא\"א להתלבש באותיות זולתי קול השיר והרננה שיש בו מתיקות התענוג והשעשועים נפלאה כו', שהוא מקור התענוגים שבג\"ע עליון ותחתון, כי יפה שעה בתשובה ובמע\"ט מכל חיי עוה\"ב כו' כנ\"ל, וזהו שיר\"ה דייקא עמי, שיר\"ו ממש של המאציל ב\"ה שהוא שעשוע המלך בעצמותו ית' כנודע.\n<b>לכך</b> נענש<sup data-n=\"5613\">57</sup> דוד המלך ע\"ה שקראן זמירות כמ\"ש זמירות<sup data-n=\"5614\">58</sup> היו לי חוקיך בבית מגורי, א\"ל הקב\"ה דוד זמירות קרית ליה כו', כי דוד בבית מגורו בארץ ציה קרא אותן זמירות, שהוא בחי' חיצוניות מלשון זמר העריצים בכדי לזמר החיצונים להכניעם שהוצרך לפי שעה בהיותו בארץ ציה כו', וע\"ז נענש כי הם בחי' שיר\"ה הפנימי' הנמשכים מסוכ\"ע הרצון עליון “ שעשוע המלך בעצמותו ית'.\n<b>וזהו</b> שמברכין<sup data-n=\"5615\">59</sup> עובר לעשייתן של המצות ברוך אתה ה' אלקינו מלך העולם אשר קדשנו במצותיו, [ברוך] הוא ל' המשכה שממשיכים ממקור החיים ב\"ה להיות אתה לנוכח בבחי' גלוי ואח\"כ הוי' אלקינ\"ו הזכרת ב' שמות אלו כדי. . בכדי לקיים מצות המלך וזהו בחי' הראשונה שבמצות, והשני' הוא מ\"ש להלן אשר (הוא נתינת טעם) קדשנו במצותיו. . לבושו המלך ב\"ה וכתיב תחת אשר לא עבדת בשמחה כו', מרוב כ\"ל כי יפה שעה א' כו' מכל חיי עוה\"ב. . העליון ב\"ה וזהו אשר קדשנ\"ו דייקא במצותי\"ו.\n<b>וזהו</b> בחי' דו\"ר שיש. . רחימו הוא. . לבוש מלכות ושעשועי המלך כו', ודחילו הוא לקיים מצות. . וזבחים כי שמוע<sup data-n=\"5616\">60</sup> מזבח טוב להקשיב מחלב אילים, וזהו",[["5613","57","<b>נענש דוד המלך ע\"ה</b>: ראה סוטה לה, א. אגה\"ק (ד\"ה דוד זמירות ע' תקס ואילך)."],["5614","58","<b>זמירות היו לי חוקיך בבית מגורי</b>: תהלים קיט, נד."],["5615","59","<b>שמברכין עובר לעשייתן</b>: ראה פסחים ז, ב."],["5616","60","<b>שמוע מזבח טוב</b>: ראה שמואל-א טו, כב."]]],[2100990388,"והיו הדברים. . שרש התורה הוא ע\"י התפלה דוקא בבחי' שיר ורינה בפה מנקודת הלב אליו<sup data-n=\"5617\">61</sup> ולא למדותיו כו', כי רוח<sup data-n=\"5618\">62</sup> אייתי רוח ואמשיך רוח בחי' רצון העליון הפשוט שרש התורה, וכמ\"ש בזוהר<sup data-n=\"5619\">63</sup> וכן בגמ' שסנדלפו\"ן קושר כתרים מבעותהון וצלותהון דישראל, וכן במ\"ת היו קושרים לכאו\"א ב'<sup data-n=\"5620\">64</sup> כתרים א' כנגד נעשה כו' רק בחטא העגל כתיב ויתנצלו<sup data-n=\"5621\">65</sup> את עדים כו', ועתה מחזירין העטרה ליושנה ע\"י התפלה ואח\"כ ת\"ת דייקא ולכן (התפלל) אמר אבא<sup data-n=\"5622\">66</sup> בנימין על ב' דברים הייתי מצטער כו' על תפלתי שתהא סמוכה למיטתי דייקא, מצד שהת\"ת שקודם התפלה הוא למטה במדרגה הרבה, כי ע\"י התפלה יצטרך להמשיך תחלה הרצון עליון, שיר\"ה עמי ואח\"כ ללמוד בתורה לשמה ממש וכנ\"ל וד\"ל.",[["5617","61","<b>אליו ולא למדותיו</b>: ראה פרדס שער (לב) הכוונה פ\"ב בשם הספרי."],["5618","62","<b>רוח אייתי רוח</b>: ראה זהר תרומה קסב, ב. סידור ערב שבת קסג, ד."],["5619","63","<b>בזוהר. . קושר כתרים מבעותהון וצלותהון דישראל</b>: ראה זהר וישלח קסז, ב. סה\"מ תש\"ח ע' 202 בהערה."],["5620","64","<b>ב' כתרים א' כנגד נעשה</b>: משפטים כד, ז. שבת פח, א."],["5621","65","<b>ויתנצלו את עדים</b>: תשא לג, ו."],["5622","66","<b>אבא בנימין. . על תפלתי שתהא סמוכה למטתי</b>: ברכות ה, ב. וראה לקו\"ת ברכה צו, ב."]]],[2100990389,"<h3>נוסח שני: ביאור על התורה</h3>\n<b></b><b>בעזרה\"י אסרו חג, באור על התורה הנז\"ל</b>\nאסרו חג\n<b>להבין</b><sup data-n=\"5623\">1</sup> שורשן של הדברים הנז\"ל. הנה ידוע שהשבירה הי' בתהו, עולם הנקודים, בז' מלכים דאדום שמתו ונפלו למטה לב\"ן דאצי' ומב\"ן לנוג\"ה דבי\"ע המעורב טו\"ר, והמברר הוא בחי' ש' מ\"ה שנמשך מבחי' טעמים (והשבירה הי' רק בנקודים שלמטה מטעמים כנודע) בחי' משה שאמר ונחנו<sup data-n=\"5624\">2</sup> מ\"ה כי בחכמה<sup data-n=\"5625\">3</sup> כח מ\"ה דוקא אתברירו וזהו תורה ציוה לנו משה מורש\"ה וגו'.\n<b>והנה</b> סדר הבירורין מלמעלה למטה הוא כך, בהיות בהמלכים שמתו הי' בחי' תערובת סיגים ופסולת כנודע, ולזאת תחלה מתברר תכלית המובחר שבהן באצי' להתכלל במובחר שבאצי' והסיגים שא\"א להם להתכלל במובחר דאצי' נדחים לחוץ למחנה דאצי' לעולם הבריאה שאעפ\"י שלגבי אצילות נחשבים לסיגים ופסולת שנדחו לחוץ, לגבי בריאה נחשבים למובחר שבמובחר שבבריאה, וכן הסיגים דבריאה נחשבים למובחר ביצי' ודיצי' בעשיה עד שהסיגים דעשי' מתפשטים",[["5623","1","<b>להבין שורשן של הדברים הנז\"ל</b>: הנחת ר' משה בן אדה\"ז. נעתק מכת\"י 1066 (ד, א)."],["5624","2","<b>ונחנו מה</b>: בשלח טז, ז."],["5625","3","<b>בחכמה כח מה</b>: זח\"ג לד, א."]]],[2100990390,"בקליפת נוגה המעורב טו\"ר ומשם יפרד לג' קליפות הטמאות שהן תכלית הרע שאין לו תקנה עד אשר רוח<sup data-n=\"5626\">4</sup> הטומאה יעבור כו'.\n<b>וזשארז\"ל</b> בשטן לפעמים לגנאי ממש באמרם ז\"ל נתן<sup data-n=\"5627\">5</sup> עיניו במקדש ראשון כו', ולפעמים מזכירים מעט לשבח, כדדרש (מס'<sup data-n=\"5628\">6</sup> ב\"ב ס\"פ השותפין) ר' אחא בפופנאי שטן ופנינה לש\"ש נתכוונו, נמצא יש בו מעט טוב, הכונה לש\"ש, ולפי דבריהם ז\"ל באמרם נתן עיניו כו' משמע שאין בו טוב כלל רק רע, מצד הקנאה שנתן עיניו ולא כיון לש\"ש כלל. אך הענין הוא ששניהם אמת, כי הסתעפות הרע גמור שלמטה הוא נמשך עפ\"י רבוי ההשתלשלות וברור אחר ברור וצירוף אחר צרוף עד לאחר גמר ותכלית כל הברורין שכבר נתברר ממנו כל הטוב לגמרי ונשאר בחי' רע גמור בנקי' בלי תערובת, אבל טרם הפרדו מן הטוב אזי יש בו עדיין תערובת טוב ג\"כ.\n<b>וזשארז\"ל</b> שטן ופנינה לש\"ש נתכוונו, שזהו בחי' השטן דיצי' הרע דיצי' שיש בו עדיין תערובת מעט טוב, הכוונה לטובה לש\"ש שמתברר אח\"כ בירידת השפע למטה בעשי' הטוב שבו בטוב דעשי', והרע שבו היוצא ונפרד מעשי' הוא תכלית הגסות והפסולת בלי תערובת טוב כלל וזהו השטן דעשי' שארז\"ל נתן עיניו במקדש ראשון כו' נתן עיניו מצד הקנאה והשנאה ולא כיון לש\"ש כלל כו'.\n<b>והנה</b> זלע\"ז<sup data-n=\"5629\">7</sup> ממש עשה האלקים דכמו שיש בסט\"א בחי' סדר הבירורי\"ן מלמעלה למטה ברבוי ההשתלשלות וצרוף אחר צרוף עד שמתהוים הקליפות גשמי' דעשי' לאחר שנתברר מהן הטוב לגמרי בירידת השפע מעולם ועד עולם כו', כן לעומת זה בקדושה בבחינת הטוב שבקדושה יש כמה מדרגות זו למעלה מזו ומתברר הטוב עצמו בברור אחר ברור וצרוף אחר צרוף אך בהפוך הסדר מלמטה למעלה שהטוב דעשיה נתברר הטוב והמובחר שבו שאפשר להתעלות בהתכללות הטוב דיצירה והשאר נחשב לפסולת לגבי יצי' הגם שכולו טוב בעשי' והטוב דיצי' נתברר המובחר שבו להתעלות בטוב דבריאה כו' עד שאף הטוב דבריאה מתברר המובחר שבו שאפשר להתכלל באצי' והשאר נחשב לפסולת וסיגים לגבי אצי' הגם שלגבי בריאה הוא כולו טוב כו'.\n<b>ובזה</b> יובן ענין שני כתובים המכחישין זא\"ז דכתיב וצבא<sup data-n=\"5630\">8</sup> השמים לך משתחוים, נמצא כתוב בהן לשבח שנמצא בהן מציאת הביטול של השתחואה כו', וכתיב הן<sup data-n=\"5631\">9</sup> בקדושיו לא יאמין ובמלאכיו ישים תהלה ושמים לא זכו בעיניו וגו', אך שניהם",[["5626","4","<b>רוח הטומאה יעבור</b>: זכרי' יג, ב — ואת רוח הטומאה אעביר."],["5627","5","<b>נתן עיניו במקדש ראשון</b>: סוכה נב, א."],["5628","6","<b>(מס' ב\"ב ס\"פ השותפין). . שטן ופנינה לש\"ש נתכוונו</b>: טז, א."],["5629","7","<b>זלע\"ז ממש עשה האלקים</b>: קהלת ז, ד."],["5630","8","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו."],["5631","9","<b>הן בקדושיו לא יאמין</b>: איוב טו, טו."]]]]});
